('24cb8bf6-0d9f-5052-a334-4738b71e1f25', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Ingmar Bergman ji kîjan welatî ye?', 'Swêd', 'Danîmarka', 'Norwêc', 'Fînlandiya', 'A', 'Fîlmên wî bi pirsên hebûnê û bi dîmenên hişk ên bakur têne nasîn.', 'Fîlmên wî bi pirsên hebûnê û bi dîmenên hişk ên bakur têne nasîn.', 'Filmleri varoluş sorularıyla ve kuzeyin sert görüntüleriyle tanınır.', 3, true, 'multiple_choice', NULL, NULL, 'Editoryal — sînemaya kurdî û ya cîhanê', 'Svenska Filminstitutet, dosyaya Ingmar Bergman', 'approved', 'Kurmancî', 2, now()),
