('78e12d24-0bb4-5043-8297-3c32eb9e56eb', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlmê "Cîranê Min Totoro" ji hêla kîjan stûdyoyê ve hatiye çêkirin?', 'Studio Ghibli', 'Toei Animation', 'Madhouse', 'Pixar', 'A', 'Karakterê Totoro paşê bû nîşana fermî ya heman stûdyoyê.', 'Karakterê Totoro paşê bû nîşana fermî ya heman stûdyoyê.', 'Totoro karakteri sonradan aynı stüdyonun resmî simgesi oldu.', 5, true, 'multiple_choice', NULL, NULL, 'Editoryal — sînemaya kurdî û ya cîhanê', 'Studio Ghibli, Tonari no Totoro (1988) — arşîva stûdyoyê', 'approved', 'Kurmancî', 2, now()),
('be5fd7d9-4902-597d-b5dc-710f353ae559', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Belgefîlma "Nanook of the North" piştî Şerê Cîhanê yê Duyem hate kişandin.', 'Rast', 'Şaş', '-', '-', 'B', 'Ew di sala 1922''yan de derket û wek yek ji belgefîlmên dirêj ên pêşîn tê hesibandin.', 'Ew di sala 1922''yan de derket û wek yek ji belgefîlmên dirêj ên pêşîn tê hesibandin.', '1922''de gösterime girdi ve uzun metrajlı ilk belgesellerden biri sayılır.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()),
('8aaf4398-232e-5e73-85b2-e85308f6ca85', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di sînemaya klasîk de ji bo tevgereke xwezayî di çirkeyekê de 24 wêne tên nîşandan.', 'Rast', 'Şaş', '-', '-', 'A', 'Ev hejmar bi ketina deng re bû pîvana standard; berê ew ji 16 heta 20 diguherî.', 'Ev hejmar bi ketina deng re bû pîvana standard; berê ew ji 16 heta 20 diguherî.', 'Bu sayı, sesin filme girmesiyle standart ölçü oldu; öncesinde 16 ile 20 arasında değişiyordu.', 1, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()),
('8122df61-b7b1-55d5-8579-f0c9fbf2cf00', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Yekem fîlmê dirêj ê bi deng "Ronahiyên Bajêr" bû.', 'Rast', 'Şaş', '-', '-', 'B', 'Ew fîlm bêdeng e; deriyê sînemaya dengdar di sala 1927''an de "The Jazz Singer"ê vekir.', 'Ew fîlm bêdeng e; deriyê sînemaya dengdar di sala 1927''an de "The Jazz Singer"ê vekir.', 'O film sessizdir; konuşmalı sinemanın kapısını 1927''de "The Jazz Singer" açtı.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()),
('48203fd0-5f1f-51e3-aa08-82e794a4026d', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Sê fîlmên "Pather Panchali", "Aparajito" û "Apur Sansar" ji kîjan welatî ne?', 'Hindistan', 'Pakistan', 'Bangladeş', 'Efxanistan', 'A', 'Derhênerê wan Satyajit Ray e; her sê fîlm jiyana heman kesî ji gund heta bajêr dişopînin.', 'Derhênerê wan Satyajit Ray e; her sê fîlm jiyana heman kesî ji gund heta bajêr dişopînin.', 'Yönetmenleri Satyajit Ray''dir; üç film aynı kişinin köyden şehre uzanan yaşamını izler.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()),
('b2e3b7ef-76ca-574b-9bee-229308bb75d2', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Ousmane Sembène, ku wek bavê sînemaya Afrîkayê tê hesibandin, ji kîjan welatî ye?', 'Misir', 'Senegal', 'Nîjerya', 'Afrîkaya Başûr', 'B', 'Ew berê romannivîs bû; berê xwe da sînemayê da ku gel bêyî xwendinê jî çîrokên wî bibihîze.', 'Ew berê romannivîs bû; berê xwe da sînemayê da ku gel bêyî xwendinê jî çîrokên wî bibihîze.', 'Önce romancıydı; halk okuma bilmeden de öykülerini duysun diye sinemaya yöneldi.', 4, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()),
('76f59c6d-2f99-5b1a-89c9-914c20c152ff', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Peyva "paparazzi" ku îro ji bo wênegirên stêrkan tê bikaranîn, ji karakterekî kîjan fîlmî tê?', 'La Dolce Vita', 'Cinema Paradiso', 'Diziyên Bîsikletê', 'Roma, Bajarê Vekirî', 'A', 'Derhênerê wî Federico Fellini ye; ew karakter wênegirekî rojnameyê bû ku li kolanên Romayê li pey kesên navdar digeriya.', 'Derhênerê wî Federico Fellini ye; ew karakter wênegirekî rojnameyê bû ku li kolanên Romayê li pey kesên navdar digeriya.', 'Yönetmeni Federico Fellini''dir; o karakter, Roma sokaklarında ünlülerin peşinden koşan bir gazete fotoğrafçısıydı.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()),
('d886b816-cbef-51e6-ad0c-79a40ac5b542', (select id from categories where slug = 'cihan'), 'ku-kmr', '"Don Kîşot" wek yekem romana nûjen a wêjeya Ewropayê tê hesibandin.', 'Rast', 'Şaş', '-', '-', 'A', 'Cervantes ew di destpêka sedsala 17em de nivîsî; şêwaza wî ya henekî bû mînak ji bo romanên paşerojê.', 'Cervantes ew di destpêka sedsala 17em de nivîsî; şêwaza wî ya henekî bû mînak ji bo romanên paşerojê.', 'Cervantes eseri 17. yüzyılın başında yazdı; alaycı üslubu sonraki romanlara örnek oldu.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()),
('97a7c8aa-a36e-5e01-9225-ea3c1c6ea478', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Nûbûna sereke ya fîlmê 1927an "The Jazz Singer" di dîroka sînemayê de çi bû?', 'Diyaloga hevaheng a bi deng', 'Karanîna pêşîn a Technicolorê', 'Yekem fîlmê sê-alî', 'Yekem anîmasyona dirêj', 'A', 'Bi pergala Vitaphone axaftin û stran bi dîmenê re hevdemî hatin dayîn; ev yek bû sedem ku serdema bêdengiyê di nav çend salan de bi dawî bibe. Nûbûnên pêvajoya rengîn û anîmasyona dirêjmetraj heta dawiya salên 1930an li benda mane.', 'Bi pergala Vitaphone axaftin û stran bi dîmenê re hevdemî hatin dayîn; ev yek bû sedem ku serdema bêdengiyê di nav çend salan de bi dawî bibe. Nûbûnên pêvajoya rengîn û anîmasyona dirêjmetraj heta dawiya salên 1930an li benda mane.', 'Vitaphone sistemiyle konuşma ve şarkı görüntüyle eşzamanlı verildi; bu, sessiz dönemin birkaç yıl içinde kapanmasına yol açtı. Renkli süreç ve uzun metraj animasyon yenilikleri 1930''ların sonunu bekledi.', 3, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=26d9d477945368f2', 'approved', 'Kurmancî', 2, now()),
('aca417a4-0ace-55a1-a48e-6bce5a502a16', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Dîmena navdar a pêpelûkên Odessayê di kîjan fîlmê Sergey Eisenstein ê 1925an de derbas dibe?', 'Cotmeh', 'Grev', 'Îvanê Tirsnak', 'Keştiya Şer Potemkin', 'D', 'Eyzenştayn di vê dîmenê de wê têgeha hevgirêdanê ku bi dîmenên li hev diqelêbin hest çêdike nîşan da. "Grev" jî berhema sala 1925an e lê dîmena pêpelûkan ne ya wê ye; "Cotmeh" ya sala 1928an e û "Îvanê Tirsnak" jî ya sala 1944an e.', 'Eyzenştayn di vê dîmenê de wê têgeha hevgirêdanê ku bi dîmenên li hev diqelêbin hest çêdike nîşan da. "Grev" jî berhema sala 1925an e lê dîmena pêpelûkan ne ya wê ye; "Cotmeh" ya sala 1928an e û "Îvanê Tirsnak" jî ya sala 1944an e.', 'Ayzenştayn bu sahnede çarpışan görüntülerle duygu üreten kurgu anlayışını gösterdi. Grev de 1925 yapımıdır ama merdiven sahnesi ona ait değildir; Ekim 1928, Korkunç İvan ise 1944 tarihlidir.', 4, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=0f120fcbc5c8f3ed', 'approved', 'Kurmancî', 2, now()),
('333a1f82-f38a-5be6-99e2-ee8a9137324b', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Navê "Bollywood" ji bo pîşesaziya fîlmên hindî yên kîjan bajarî tê bikaranîn?', 'Kolkata', 'Mumbai', 'Çennaî', 'Delhî', 'B', 'Nav ji navê kevn ê bajêr Bombay û Hollywoodê tê û berhemhênana fîlmên hindî vedibêje. Sînemaya tamîlî ya li Çennaîyê Kollywood, sînemaya bengalî ya li Kolkatayê jî Tollywood tê binavkirin.', 'Nav ji navê kevn ê bajêr Bombay û Hollywoodê tê û berhemhênana fîlmên hindî vedibêje. Sînemaya tamîlî ya li Çennaîyê Kollywood, sînemaya bengalî ya li Kolkatayê jî Tollywood tê binavkirin.', 'Ad, şehrin eski adı Bombay ile Hollywood''un birleşiminden gelir ve Hintçe film üretimini anlatır. Chennai''deki Tamil sineması Kollywood, Kolkata''daki Bengalce sinema ise Tollywood diye anılır.', 1, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=df151daa9a6608c5', 'approved', 'Kurmancî', 2, now()),
('ffe1613a-ced2-529b-8af4-ca241917b170', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlmê 1920yî "Kabîneya Doktor Caligari" bi dekorên xwar û siyên tûj nûnerê kîjan şêwazê ye?', 'Ekspresyonîzma almanî', 'Realîzma poetîk', 'Sînema-çav', 'Film noir a fransî', 'A', 'Di vê tevgerê de dekor û ronahî rewşa giyanî ya karakteran derdixin holê; li şûna mekanekî rasteqîn, cîhaneke boyaxkirî û xwar tê avakirin. Realîzma poetîk ya Fransaya salên 1930î ye, Sînema-çav jî ya belgefîlma sovyetî ye.', 'Di vê tevgerê de dekor û ronahî rewşa giyanî ya karakteran derdixin holê; li şûna mekanekî rasteqîn, cîhaneke boyaxkirî û xwar tê avakirin. Realîzma poetîk ya Fransaya salên 1930î ye, Sînema-çav jî ya belgefîlma sovyetî ye.', 'Bu akımda dekor ve ışık karakterin ruh halini dışarı taşır; gerçekçi mekân yerine boyanmış, eğri bir dünya kurulur. Şiirsel gerçekçilik 1930''lar Fransa''sına, sine-göz ise Sovyet belgeseline aittir.', 3, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=a7f3735e54740257', 'approved', 'Kurmancî', 2, now()),
('7eabeb14-5064-56a6-83d2-85d8088d70f5', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Derhênerê swêdî yê fîlmê 1957an "Det sjunde inseglet" (Mohra Heftemîn) kî ye?', 'Victor Sjöström', 'Bo Widerberg', 'Ingmar Bergman', 'Jan Troell', 'C', 'Fîlm vedibêje ku şovalyeyekî ku ji Seferên Xaçparêzan vedigere, bi Mirinê re satrancê dilîze; pirsa baweriyê û mirinê di hemû berhemên derhêner de didome. Sjöström, Widerberg û Troell jî navên girîng ên sînemaya swêdî ne.', 'Fîlm vedibêje ku şovalyeyekî ku ji Seferên Xaçparêzan vedigere, bi Mirinê re satrancê dilîze; pirsa baweriyê û mirinê di hemû berhemên derhêner de didome. Sjöström, Widerberg û Troell jî navên girîng ên sînemaya swêdî ne.', 'Film, Haçlı seferinden dönen bir şövalyenin Ölüm''le satranç oynamasını anlatır; inanç ve ölüm sorusu yönetmenin bütün işlerinde sürer. Sjöström, Widerberg ve Troell de İsveç sinemasının önemli adlarıdır.', 3, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=d1b7689e4eef818d', 'approved', 'Kurmancî', 2, now()),
('6e8bb6f8-8471-5bbc-9546-be248e4d2779', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan festîvala fîlman a navneteweyî ya sereke di sala 1932yan de, berî yên din, hat damezrandin?', 'Cannes', 'Berlînale', 'Venedîk', 'Karlovy Vary', 'C', 'Xelata mezin a vê festîvalê ya ku di sala 1932yan de dest pê kiriye, Şêrê Zêrîn e. Cannes û Karlovy Vary di sala 1946an de bûn birêkûpêk, Berlînale jî di sala 1951ê de hat damezrandin.', 'Xelata mezin a vê festîvalê ya ku di sala 1932yan de dest pê kiriye, Şêrê Zêrîn e. Cannes û Karlovy Vary di sala 1946an de bûn birêkûpêk, Berlînale jî di sala 1951ê de hat damezrandin.', '1932''de başlayan bu festivalin büyük ödülü Altın Aslan''dır. Cannes ve Karlovy Vary 1946''da düzenli hale geldi, Berlinale ise 1951''de kuruldu.', 3, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=2e3edeb909338378', 'approved', 'Kurmancî', 2, now()),
('e122a630-69d9-5243-b67e-59c6cf763b32', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Krîza afirînerî ya derhênerekî di fîlmê 1963yan "8½" de tê vegotin; ev berhem ya kîjan derhênerê îtalî ye?', 'Federico Fellini', 'Luchino Visconti', 'Michelangelo Antonioni', 'Pier Paolo Pasolini', 'A', 'Derhêner xitimîna xwe ya hunerî bi tevliheviya xewn, bîr û rastiyê vegot; sernav bal dikişîne ser hejmara fîlmên ku heta wê rojê kişandibû. Visconti, Antonioni û Pasolini jî hostayên îtalî yên heman serdemê ne.', 'Derhêner xitimîna xwe ya hunerî bi tevliheviya xewn, bîr û rastiyê vegot; sernav bal dikişîne ser hejmara fîlmên ku heta wê rojê kişandibû. Visconti, Antonioni û Pasolini jî hostayên îtalî yên heman serdemê ne.', 'Yönetmen kendi tıkanmışlığını rüya, anı ve gerçeği iç içe geçirerek anlattı; başlık o güne dek çektiği film sayısına gönderme yapar. Visconti, Antonioni ve Pasolini de aynı dönemin İtalyan ustalarıdır.', 3, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=068e0b93748efb97', 'approved', 'Kurmancî', 2, now()),
('f586102d-117a-5474-be47-2d0610295ea9', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di standarda klasîk a sînemaya 35 mm de di saniyeyekê de çend kadro tên nîşandan?', '16', '24', '30', '48', 'B', 'Bi derbasbûna bo sînemaya dengdar re ev leza kadroyan bû standard, çimkî xwendina rast a banda dengî lezeke sabît hewce dikir. Di serdema bêdengiyê de leza kişandinê di navbera 16 û 18an de dihat guhertin.', 'Bi derbasbûna bo sînemaya dengdar re ev leza kadroyan bû standard, çimkî xwendina rast a banda dengî lezeke sabît hewce dikir. Di serdema bêdengiyê de leza kişandinê di navbera 16 û 18an de dihat guhertin.', 'Sesli sinemaya geçişle birlikte bu hız standart oldu, çünkü ses bandının düzgün okunması sabit bir hız gerektiriyordu. Sessiz dönemde çekim hızı 16 ile 18 arasında değişebiliyordu.', 2, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=e1f37b20f11a9dd5', 'approved', 'Kurmancî', 2, now()),
('96717f3e-30d1-5af2-8a5e-8a81bc0ecd0b', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlmê 1959an "Les 400 coups" ku destpêka Pêla Nû ya Fransî tê hesibandin, ji kê ye?', 'François Truffaut', 'Jean-Luc Godard', 'Claude Chabrol', 'Jean-Pierre Melville', 'A', 'Derhêner bi yekem fîlmê xwe yê dirêjmetraj li Cannesê xelata derhênerê herî baş wergirt; fîlm şopên zaroktiya wî hildigire. Godard û Chabrol jî ji nivîskariya Cahiers du cinéma derbasî derhêneriyê bûn; Melville jî derhênerekî ku beriya vî nifşî hatibû û wan wek nimûne digirt, bû.', 'Derhêner bi yekem fîlmê xwe yê dirêjmetraj li Cannesê xelata derhênerê herî baş wergirt; fîlm şopên zaroktiya wî hildigire. Godard û Chabrol jî ji nivîskariya Cahiers du cinéma derbasî derhêneriyê bûn; Melville jî derhênerekî ku beriya vî nifşî hatibû û wan wek nimûne digirt, bû.', 'Yönetmen ilk uzun metrajıyla Cannes''da en iyi yönetmen ödülünü aldı; film kendi çocukluğundan izler taşır. Godard ve Chabrol da Cahiers du cinéma yazarlığından yönetmenliğe geçti; Melville ise bu kuşaktan önce gelen, onların örnek aldığı bir yönetmendi.', 3, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=749ef2a6e4dc39bd', 'approved', 'Kurmancî', 2, now()),
('146ac1dd-ad4a-5cb8-99c1-c6da65ff14f3', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Derhênerê senegalî yê ku bi fîlmê 1966an "La Noire de…" tê nasîn kî ye?', 'Djibril Diop Mambéty', 'Souleymane Cissé', 'Ousmane Sembène', 'Med Hondo', 'C', 'Derhênerê ku ji romannivîsiyê hatibû, bi çîroka jineke senegalî ya li Fransayê dixebitî, yek ji fîlmên pêşîn ên dirêjmetraj ên Afrîkaya binê Sahrayê ku baldariya navneteweyî kişand, çêkir. Mambéty, Cissé û Hondo jî navên girîng ên sînemaya afrîkî ne.', 'Derhênerê ku ji romannivîsiyê hatibû, bi çîroka jineke senegalî ya li Fransayê dixebitî, yek ji fîlmên pêşîn ên dirêjmetraj ên Afrîkaya binê Sahrayê ku baldariya navneteweyî kişand, çêkir. Mambéty, Cissé û Hondo jî navên girîng ên sînemaya afrîkî ne.', 'Roman yazarlığından gelen yönetmen, Fransa''da çalışan bir Senegalli kadının öyküsüyle Sahra altı Afrika''nın uluslararası ilgi gören ilk uzun metrajlarından birini verdi. Mambéty, Cissé ve Hondo da Afrika sinemasının önemli adlarıdır.', 4, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=615e259e084a335b', 'approved', 'Kurmancî', 2, now()),
('1326b43f-60fa-5453-8d10-353f4afb78c0', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Derhênerê hongkongî yê fîlmê 2000î "In the Mood for Love" kî ye?', 'Wong Kar-waî', 'John Woo', 'Tsui Hark', 'Ann Hui', 'A', 'Fîlm nêzîkbûna neaxaftî ya di navbera du cîranan de li Hong Konga salên 1960î bi kadroyên teng û derbasbûnên hêdîkirî vedibêje. Woo, Tsui Hark û Ann Hui jî damarên din ên heman sînemayê temsîl dikin.', 'Fîlm nêzîkbûna neaxaftî ya di navbera du cîranan de li Hong Konga salên 1960î bi kadroyên teng û derbasbûnên hêdîkirî vedibêje. Woo, Tsui Hark û Ann Hui jî damarên din ên heman sînemayê temsîl dikin.', 'Film, 1960''ların Hong Kong''unda iki komşunun söze dökülmeyen yakınlığını dar kadrajlar ve yavaşlatılmış geçişlerle anlatır. Woo, Tsui Hark ve Ann Hui aynı sinemanın başka damarlarını temsil eder.', 3, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=d6b205f55ff99827', 'approved', 'Kurmancî', 2, now()),
('3483febd-432a-5b8d-9b9f-b5fd28f2520d', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kûrahiya qadê ya berfireh bi fîlmê 1941ê "Citizen Kane" navdar bû; derhênerê wî kî ye?', 'Howard Hawks', 'Orson Welles', 'John Ford', 'Billy Wilder', 'B', 'Derhêner fîlm di 25 saliya xwe de kişand; dîmenên ku tê de plana pêş û paş bi hev re zelal dimînin, digel derhênerê dîmenê Gregg Toland pêş xist. Ford, Hawks û Wilder jî navên mezin ên din ên heman serdema stûdyoyan in.', 'Derhêner fîlm di 25 saliya xwe de kişand; dîmenên ku tê de plana pêş û paş bi hev re zelal dimînin, digel derhênerê dîmenê Gregg Toland pêş xist. Ford, Hawks û Wilder jî navên mezin ên din ên heman serdema stûdyoyan in.', 'Yönetmen filmi 25 yaşında çekti; ön ve arka planın birlikte net kaldığı görüntüleri görüntü yönetmeni Gregg Toland''la geliştirdi. Ford, Hawks ve Wilder aynı stüdyo döneminin diğer büyük adlarıdır.', 3, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=51d0979d01d1cb29', 'approved', 'Kurmancî', 2, now()),
('ed612456-efe0-5c05-bef9-d101e5224340', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Cureyê fîlmî yê ku li rojavayê Amerîkayê ya sedsala 19an, bi kovboy û şerên sînoran derbas dibe kîjan e?', 'Western', 'Melodram', 'Film noir', 'Trîler', 'A', 'Ev cure efsaneya deverên sînorî bi hesp, çek û zeviyên vekirî ava dike. Fîlma tarî di şeva bajêr de derbas dibe, melodram xwe dispêre pevçûna hestî, tirs jî li benda xetereyê ye.', 'Ev cure efsaneya deverên sînorî bi hesp, çek û zeviyên vekirî ava dike. Fîlma tarî di şeva bajêr de derbas dibe, melodram xwe dispêre pevçûna hestî, tirs jî li benda xetereyê ye.', 'Bu tür sınır bölgesinin efsanesini at, silah ve açık arazi üzerinden kurar. Kara film kentin gecesinde geçer, melodram duygusal çatışmaya, gerilim ise tehlike beklentisine dayanır.', 2, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=5ae34d13da9e5f81', 'approved', 'Kurmancî', 2, now()),
('e0f2d66f-6d4b-5bd1-9e8f-0e4758fdc94c', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan kovara fransî di salên 1950î de nêrîna "derhêner nivîskarê fîlmî ye" belav kir?', 'Sight and Sound', 'Positif', 'Cahiers du cinéma', 'Variety', 'C', 'Rexnegirên ciwan ên li dora kovarê pêşniyar kirin ku heta di nav rêsayên stûdyoyê de jî mora şexsî ya derhênerekî tê xwendin; paşê wan bi xwe fîlm kişandin. Positif kovareke fransî ya reqîb e, Sight and Sound îngilîzî ye, Variety jî weşana sektorî ya amerîkî ye.', 'Rexnegirên ciwan ên li dora kovarê pêşniyar kirin ku heta di nav rêsayên stûdyoyê de jî mora şexsî ya derhênerekî tê xwendin; paşê wan bi xwe fîlm kişandin. Positif kovareke fransî ya reqîb e, Sight and Sound îngilîzî ye, Variety jî weşana sektorî ya amerîkî ye.', 'Dergi çevresindeki genç eleştirmenler, stüdyo düzeni içinde bile bir yönetmenin kişisel damgasının okunabileceğini savundu; sonra kendileri film çekti. Positif rakip Fransız dergisi, Sight and Sound İngiliz, Variety ise Amerikan sektör yayınıdır.', 4, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=812f622118f6e513', 'approved', 'Kurmancî', 2, now()),
('5c91be50-97dd-5371-80ea-3610e59172fb', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Palme d''Or a sala 2019an ji fîlmê "Parasite" re hat dayîn; ev fîlm ji kîjan welatî ye?', 'Japonya', 'Koreya Başûr', 'Çîn', 'Taywan', 'B', 'Fîlmê Bong Joon-ho cudahiya çînan a di navbera du malbatan de bi qatên xaniyekî tenê vedibêje. Heman fîlm sala pey re li Oscarê wek fîlmê herî baş hat hilbijartin û bû yekemîn berhema ne bi îngilîzî ku vê xelatê wergirt.', 'Fîlmê Bong Joon-ho cudahiya çînan a di navbera du malbatan de bi qatên xaniyekî tenê vedibêje. Heman fîlm sala pey re li Oscarê wek fîlmê herî baş hat hilbijartin û bû yekemîn berhema ne bi îngilîzî ku vê xelatê wergirt.', 'Bong Joon-ho''nun filmi iki ailenin sınıf farkını tek bir evin katmanlarında anlatır. Aynı film ertesi yıl Oscar''da en iyi film seçilerek bu ödülü kazanan ilk İngilizce olmayan yapım oldu.', 2, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=65df1ffb99815f0a', 'approved', 'Kurmancî', 2, now()),
('32668f2b-434d-5740-a24c-27d0387fe92c', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Ceribandina ku nîşan da wateya heman dîmena rûyî li gorî dîmena pê re diguhere, bi navê kê tê zanîn?', 'Dziga Vertov', 'Vsevolod Pudovkin', 'Lev Kuleşov', 'Aleksandr Dovjenko', 'C', 'Di ceribandinê de heman rûyê bêalî; dema bi dîmenên şorbeyê, tabûtê û zarokekî re hat lihevkirin, temaşevanan wê bi rêzê wek birçîbûn, xemgînî û dilovanî şîrove kir. Ramana ku wate ne di yek dîmenê de, lê di têkiliya navbera dîmenan de çêdibe, bingeha dibistana montajê ya Sovyetê ye.', 'Di ceribandinê de heman rûyê bêalî; dema bi dîmenên şorbeyê, tabûtê û zarokekî re hat lihevkirin, temaşevanan wê bi rêzê wek birçîbûn, xemgînî û dilovanî şîrove kir. Ramana ku wate ne di yek dîmenê de, lê di têkiliya navbera dîmenan de çêdibe, bingeha dibistana montajê ya Sovyetê ye.', 'Deneyde aynı nötr yüz; çorba, tabut ve çocuk görüntüleriyle eşleştirilince izleyiciler sırasıyla açlık, keder ve şefkat okudu. Anlamın tek çekimde değil çekimlerin ilişkisinde doğduğu fikri Sovyet kurgu okulunun temelidir.', 5, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=0969a18fb8881f36', 'approved', 'Kurmancî', 2, now()),
('575e00ff-6ae4-5d28-a85d-290a6f9f4b71', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Derhênerê spanî yê ku bi fîlmê xwe yê 1999an "Her Tişt Li Ser Dayika Min" Oscara fîlmê biyanî wergirt kî ye?', 'Carlos Saura', 'Luis Buñuel', 'Pedro Almodóvar', 'Alejandro Amenábar', 'C', 'Fîlm xelat di merasîma sala 2000an de wergirt; derhêner bi rengên zindî û vegotina xwe ya li ser melodramê tê nasîn. Buñuel ji nifşekî pir berê ye, Saura û Amenábar jî bi fîlmên din tên bi bîr anîn.', 'Fîlm xelat di merasîma sala 2000an de wergirt; derhêner bi rengên zindî û vegotina xwe ya li ser melodramê tê nasîn. Buñuel ji nifşekî pir berê ye, Saura û Amenábar jî bi fîlmên din tên bi bîr anîn.', 'Film ödülü 2000''deki törende aldı; yönetmen canlı renkleri ve melodrama yaslanan anlatısıyla tanınır. Buñuel çok daha önceki kuşaktandır, Saura ve Amenábar ise başka filmlerle anılır.', 3, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=592225b188cb079d', 'approved', 'Kurmancî', 2, now()),
('292f3545-26ff-5687-8a98-b920437fd307', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Derhênerê fîlmê 1979an "Stalker" ê ku li Yekîtiya Sovyetê hat kişandin kî ye?', 'Andrey Tarkovskî', 'Sergey Parajanov', 'Elem Klimov', 'Nikita Mihalkov', 'A', 'Derhêner bi dîmenên dirêj û rîtma xwe ya giran, ne aksiyona xeyalî-zanistî, lê pirsa baweriyê xist pêş; fîlm ji romana birayên Strugatskî hatiye guncandin. Parajanov, Klimov û Mihalkov jî derhênerên din ên Sovyetê yên heman serdemê ne.', 'Derhêner bi dîmenên dirêj û rîtma xwe ya giran, ne aksiyona xeyalî-zanistî, lê pirsa baweriyê xist pêş; fîlm ji romana birayên Strugatskî hatiye guncandin. Parajanov, Klimov û Mihalkov jî derhênerên din ên Sovyetê yên heman serdemê ne.', 'Yönetmen uzun çekimleri ve ağır ritmiyle bilimkurgunun aksiyonunu değil inanç sorusunu öne aldı; film Strugatski kardeşlerin romanından uyarlandı. Parajanov, Klimov ve Mihalkov aynı dönemin diğer Sovyet yönetmenleridir.', 4, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=4011f53fddfab8b4', 'approved', 'Kurmancî', 2, now()),
('a7ab08f6-38f6-596f-9643-0893778a3396', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di zimanê Hitchcock de, tişta ku lehengan dide tevgerê lê bi xwe ne girîng e, çawa tê binavkirin?', 'MacGuffin', 'Deus ex machina', 'Vegera paşve', 'Mîzansen', 'A', 'Ev hêman dikare belgeyek, çentiyek an formulek be; erka wê ew e ku leyistin-revê dest pê bike, ne naveroka wê. Berevajî wê, deus ex machina girêka dawiyê ji derve çareser dike, mîzansen jî rêxistina hundirê kadrajê vedibêje.', 'Ev hêman dikare belgeyek, çentiyek an formulek be; erka wê ew e ku leyistin-revê dest pê bike, ne naveroka wê. Berevajî wê, deus ex machina girêka dawiyê ji derve çareser dike, mîzansen jî rêxistina hundirê kadrajê vedibêje.', 'Bu öğe bir belge, valiz ya da formül olabilir; işlevi kovalamacayı başlatmaktır, içeriği değil. Deus ex machina tersine düğümü sonda dışarıdan çözer, mizansen ise kadraj içi düzenlemeyi anlatır.', 4, true, 'multiple_choice', NULL, NULL, 'Sînema: huner, dîrok û derhêner', 'internal:expansion_2026_08/cinema#gate=validate_batch.py#hash=115e530809b63791', 'approved', 'Kurmancî', 2, now()),
('8c930d3c-7b2f-5527-b1db-65fd74060e7c', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Xelatên Oscarê cara yekem di kîjan salê de hatin pêşkêşkirin?', '1919', '1939', '1949', '1929', 'D', 'Merasima yekem a Xelatên Akademiyê (Oscar) di 16''ê gulana 1929''an de li Hollywoodê hate lidarxistin. Ji wê demê vir ve Oscar her sal tê dayîn û bûye xelata herî bi prestîj a pîşesaziya fîlmê.', 'Merasima yekem a Xelatên Akademiyê (Oscar) di 16''ê gulana 1929''an de li Hollywoodê hate lidarxistin. Ji wê demê vir ve Oscar her sal tê dayîn û bûye xelata herî bi prestîj a pîşesaziya fîlmê.', 'Akademi Ödülleri''nin (Oscar) ilk töreni 16 Mayıs 1929''da Hollywood''da yapıldı. O zamandan beri Oscar her yıl verilir ve film endüstrisinin en prestijli ödülü hâline geldi.', 3, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()),
('00751d41-1f57-5cab-ae8b-cf50eea625b1', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Palmiya Zêrîn xelata herî bilind a kîjan festîvalê ye?', 'Festîvala Venedîkê', 'Festîvala Cannesê', 'Festîvala Berlînê', 'Festîvala Torontoyê', 'B', 'Palmiya Zêrîn ji sala 1955''an vir ve xelata sereke ya Festîvala Cannesê ye ku her sal li Fransayê tê lidarxistin. Venedîk xelata Şêrê Zêrîn, Berlîn jî xelata Hirçê Zêrîn dide.', 'Palmiya Zêrîn ji sala 1955''an vir ve xelata sereke ya Festîvala Cannesê ye ku her sal li Fransayê tê lidarxistin. Venedîk xelata Şêrê Zêrîn, Berlîn jî xelata Hirçê Zêrîn dide.', 'Altın Palmiye, 1955''ten beri her yıl Fransa''da düzenlenen Cannes Film Festivali''nin ana ödülüdür. Venedik Altın Aslan, Berlin ise Altın Ayı ödülünü verir.', 2, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()),
('c4db8369-94ba-500a-a652-ddd44ad668c0', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan festîvala fîlman a herî kevn a cîhanê ye?', 'Festîvala Cannesê', 'Festîvala Berlînê', 'Festîvala Venedîkê', 'Festîvala Lokarnoyê', 'C', 'Festîvala Venedîkê di sala 1932''an de hate damezrandin û wek festîvala fîlman a herî kevn a cîhanê tê zanîn. Cannes di sala 1946''an, Berlîn jî di sala 1951''ê de dest pê kirin.', 'Festîvala Venedîkê di sala 1932''an de hate damezrandin û wek festîvala fîlman a herî kevn a cîhanê tê zanîn. Cannes di sala 1946''an, Berlîn jî di sala 1951''ê de dest pê kirin.', 'Venedik Film Festivali 1932''de kuruldu ve dünyanın en eski film festivali olarak kabul edilir. Cannes 1946''da, Berlin ise 1951''de başladı.', 4, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()),
('a14b4bb8-e088-531e-8d7d-19d4e779995b', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Festîvala Cannesê di kîjan welatî de tê lidarxistin?', 'Îtalya', 'Fransa', 'Spanya', 'Swîsre', 'B', 'Festîvala Cannesê ji sala 1946''an vir ve her gulan li bajarê Cannesê yê li başûrê Fransayê tê lidarxistin. Xelata wê ya sereke Palmiya Zêrîn e û festîval yek ji bûyerên herî girîng ên pîşesaziya fîlmê ye.', 'Festîvala Cannesê ji sala 1946''an vir ve her gulan li bajarê Cannesê yê li başûrê Fransayê tê lidarxistin. Xelata wê ya sereke Palmiya Zêrîn e û festîval yek ji bûyerên herî girîng ên pîşesaziya fîlmê ye.', 'Cannes Film Festivali, 1946''dan beri her mayıs Fransa''nın güneyindeki Cannes şehrinde düzenlenir. Ana ödülü Altın Palmiye''dir ve festival, film endüstrisinin en önemli etkinliklerindendir.', 3, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()),
('e21ee11a-7f4b-59d4-bb64-111465f3afda', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlmê ku di merasima yekem a Oscarê de xelata Fîlmê Herî Baş wergirt kîjan e?', 'The Jazz Singer', 'Citizen Kane', 'Wings', 'Gone with the Wind', 'C', 'Wings (1927) di merasima yekem a Oscarê ya 1929''an de xelata Fîlmê ya Herî Baş wergirt. Ev fîlm derbarê pilotekî Şerê Cîhanê yê Yekem de ye û bi dîmenên xwe yên hewayî tê nasîn.', 'Wings (1927) di merasima yekem a Oscarê ya 1929''an de xelata Fîlmê ya Herî Baş wergirt. Ev fîlm derbarê pilotekî Şerê Cîhanê yê Yekem de ye û bi dîmenên xwe yên hewayî tê nasîn.', 'Kanatlar (Wings, 1927), 1929''daki ilk Oscar töreninde En İyi Film ödülünü kazandı. I. Dünya Savaşı pilotlarını konu alır ve hava sahneleriyle tanınır.', 4, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()),
('d3054595-a680-5590-a580-b153e3b9957b', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Saziya ku Oscarê dide û di sala 1927''an de hatiye damezrandin kîjan e?', 'Cannes Film Society', 'AMPAS', 'British Academy (BAFTA)', 'Tribeca Institute', 'B', 'Akademiya Huner û Zanistên Fîlmê (AMPAS) di sala 1927''an de li Hollywoodê hate damezrandin û ji 1929''an vir ve Xelatên Akademiyê (Oscar) dide. BAFTA ya Brîtanî û saziyên din ên ku xelatên xwe hene ji vê akademiyê cuda ne.', 'Akademiya Huner û Zanistên Fîlmê (AMPAS) di sala 1927''an de li Hollywoodê hate damezrandin û ji 1929''an vir ve Xelatên Akademiyê (Oscar) dide. BAFTA ya Brîtanî û saziyên din ên ku xelatên xwe hene ji vê akademiyê cuda ne.', 'Sinema Sanatları ve Bilimleri Akademisi (AMPAS) 1927''de Hollywood''da kuruldu ve 1929''dan beri Akademi Ödülleri''ni (Oscar) verir. İngiliz BAFTA ve kendi ödülleri olan diğer kurumlar bu akademiden farklıdır.', 4, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()),
