('9292c85a-db1d-5400-8861-62d50a85bacb', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Li gorî NASAyê, ji sedî çendê atmosfera Cîhanê oksîjen e?', 'Ji sedî 50', 'Ji sedî 21', 'Ji sedî 78', 'Ji sedî 5', 'B', 'Atmosfera Cîhanê ji sedî 21 oksîjen dihewîne; para herî mezin gazeke din e.', 'Atmosfera Cîhanê ji sedî 21 oksîjen dihewîne; para herî mezin gazeke din e.', 'Dünya atmosferinin yüzde 21''i oksijendir; en büyük payı başka bir gaz oluşturur.', 2, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()),
