('e354ab52-ca0e-59a1-89ca-cef98c25a973', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Li gorî USGSê, okyanûs ji sedî çendê ava Cîhanê pêk tînin?', 'Ji sedî 71', 'Ji sedî 50', 'Ji sedî 96,5', 'Ji sedî 30', 'C', 'Li gorî USGSê okyanûs nêzî ji sedî 96,5ê ava dinyayê pêk tînin; tenê nêzî ji sedî 2,5ê ava giştî ava şêrîn e.', 'Li gorî USGSê okyanûs nêzî ji sedî 96,5ê ava dinyayê pêk tînin; tenê nêzî ji sedî 2,5ê ava giştî ava şêrîn e.', 'USGS''e göre okyanuslar Dünya''daki suyun yaklaşık %96,5''ini tutar; toplam suyun yalnızca yaklaşık %2,5''i tatlı sudur.', 2, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()),
('622b8997-76db-531d-aa40-076c96f88189', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Piraniya ava şêrîn a Cîhanê li ku ye?', 'Di golan de', 'Di çeman de', 'Di baranê de', 'Di qeşa û cemedan de', 'D', 'Zêdetirî ji sedî 68ê ava şêrîn di qeşa û cemedan de girtî ye.', 'Zêdetirî ji sedî 68ê ava şêrîn di qeşa û cemedan de girtî ye.', 'Tatlı suyun yüzde 68''den fazlası buz ve buzullarda kilitlidir.', 2, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()),
('f56925d4-c278-526f-9954-445e9858a610', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Dûrahiya navînî ya di navbera Cîhan û Heyvê de çend kîlometre ye?', '150.000 km', '384.400 km', '1.740 km', '12.000 km', 'B', 'Heyv bi navînî 384.400 kîlometre ji Cîhanê dûr e.', 'Heyv bi navînî 384.400 kîlometre ji Cîhanê dûr e.', 'Ay, Dünya''dan ortalama 384.400 kilometre uzaktadır.', 2, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()),
('edc3a923-c9d9-5b57-8b5f-9e04b61980dc', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Cihê herî kûr ê okyanûsê bi çi navî tê nasîn?', 'Mariana Rise', 'Pacific Basin', 'Challenger Deep', 'Atlas Trench', 'C', 'Cihê herî kûr ê okyanûsê Challenger Deep e û li binê okyanûsa Aramê ya rojava ye.', 'Cihê herî kûr ê okyanûsê Challenger Deep e û li binê okyanûsa Aramê ya rojava ye.', 'Okyanusun en derin yeri Challenger Deep''tir ve batı Pasifik''in altındadır.', 2, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()),
