('b7eda776-68d1-527a-9198-7742e0eded27', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Salên 1920yî li Dewletên Yekbûyî bi navê kîjan celebê muzîkê tên bibîranîn?', 'Rock', 'Pop', 'Hip-hop', 'Jazz', 'D', 'Salên 1920yî li Dewletên Yekbûyî wekî "Serdema Cazê" tên bibîranîn.', 'Salên 1920yî li Dewletên Yekbûyî wekî "Serdema Cazê" tên bibîranîn.', '1920''ler ABD''de "Caz Çağı" (Jazz Age) adıyla anılır; dönemin adı yazar F. Scott Fitzgerald''a mal edilir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Jazz_Age', NULL, 'https://en.wikipedia.org/wiki/Jazz_Age', 'approved', 'Kurmancî', 1, now()),
('17811d1e-1b4e-5a45-a0af-b8c65df1b7df', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan celeb muzîkê di salên 1990yan de li Seattle derketiye?', 'Pop', 'Grunge', 'Hip-hop', 'Country', 'B', 'Grunge di salên 1990yan de li Seattle derketiye. Ev celeb muzîkê ji rockê derketiye û bi gîtarên xwe yên giran û dengên xwe yên xemgîn ve tê naskirin.', 'Grunge di salên 1990yan de li Seattle derketiye. Ev celeb muzîkê ji rockê derketiye û bi gîtarên xwe yên giran û dengên xwe yên xemgîn ve tê naskirin.', 'Grunge, 1980''larda Seattle''da ortaya çıkmıştır. Bu müzik türü rock''tan türemiştir ve ağır gitarları ve hüzünlü sesleriyle tanınır. 1990''larda ana akıma yayıldı.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Grunge', NULL, 'https://en.wikipedia.org/wiki/Grunge', 'approved', 'Kurmancî', 1, now()),
('0efe2731-a9ac-5c03-b9f9-2c0dfe8133d5', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan amûr di navenda muzîka bluesê de ye?', 'Piyano', 'Baterî', 'Gîtar', 'Keman', 'C', 'Gîtar amûra navendî ya kevneşopiya bluesê ye.', 'Gîtar amûra navendî ya kevneşopiya bluesê ye.', 'Gitar, blues geleneğinin merkezindeki çalgıdır; tel bükme ve slide teknikleri türün sesini kurar.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Blues', NULL, 'https://en.wikipedia.org/wiki/Blues', 'approved', 'Kurmancî', 1, now()),
('f2340c63-8e3b-501e-952e-d525133ed5ea', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan koma muzîkê bi strana xwe ya "Bohemian Rhapsody" navdar bû?', 'Queen', 'Led Zeppelin', 'Pink Floyd', 'The Doors', 'A', 'Queen bi strana xwe ya "Bohemian Rhapsody" pir navdar bû. Ev stran di sala 1975an de derketiye û wekî yek ji stranên herî navdar ên dîroka muzîkê tê hesibandin.', 'Queen bi strana xwe ya "Bohemian Rhapsody" pir navdar bû. Ev stran di sala 1975an de derketiye û wekî yek ji stranên herî navdar ên dîroka muzîkê tê hesibandin.', 'Queen, "Bohemian Rhapsody" şarkısıyla çok ünlü olmuştur. Bu şarkı 1975''te çıkmış ve müzik tarihinin en ünlü şarkılarından biri olarak kabul edilir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Bohemian_Rhapsody', NULL, 'https://en.wikipedia.org/wiki/Bohemian_Rhapsody', 'approved', 'Kurmancî', 1, now()),
('4e0a9ff4-832a-5111-9e2d-964e4d41a3dd', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di hilberîna popa nûjen de kîjan amûra elektronîk roleke sereke dilîze?', 'Tembûr', 'Bilûr', 'Zirne', 'Sentezker', 'D', 'Ji salên 1980yî ve sentezker bûye çavkaniya sereke ya dengê popê.', 'Ji salên 1980yî ve sentezker bûye çavkaniya sereke ya dengê popê.', '1980''lerden bu yana sentezleyici, pop prodüksiyonunun temel ses kaynağıdır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Synthesizer', NULL, 'https://en.wikipedia.org/wiki/Synthesizer', 'approved', 'Kurmancî', 1, now()),
('3f6c9485-cd66-5575-b847-5f2d25b07437', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di operayê de stranbêj bi piranî bi kîjan awayî stranan dibêjin?', 'Bê mikrofon', 'Bi mikrofonê', 'Bi kasetê', 'Bi radyoyê', 'A', 'Di operayê de stranbêj bi piranî bê mikrofon stranan dibêjin. Ev yek ji ber ku dengê wan bi xwezayî û bi hêz e, û di salonên operayê de akustîk baş e.', 'Di operayê de stranbêj bi piranî bê mikrofon stranan dibêjin. Ev yek ji ber ku dengê wan bi xwezayî û bi hêz e, û di salonên operayê de akustîk baş e.', 'Operada şarkıcılar çoğunlukla mikrofonsuz şarkı söyler. Bunun nedeni, seslerinin doğal ve güçlü olması ve opera salonlarındaki akustiğin iyi olmasıdır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Opera', NULL, 'https://en.wikipedia.org/wiki/Opera', 'approved', 'Kurmancî', 1, now()),
('c79d3fde-67a6-569e-b340-a89c68a462e1', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan bestekar bi opera xwe ya "Carmen" tê naskirin?', 'Wolfgang Amadeus Mozart', 'Ludwig van Beethoven', 'Giuseppe Verdi', 'Georges Bizet', 'D', 'Georges Bizet bi opera xwe ya "Carmen" tê naskirin. Ev opera di sala 1875ê de hatiye nivîsandin û yek ji navdartirîn operayên fransî ye.', 'Georges Bizet bi opera xwe ya "Carmen" tê naskirin. Ev opera di sala 1875ê de hatiye nivîsandin û yek ji navdartirîn operayên fransî ye.', 'Georges Bizet, "Carmen" operasıyla tanınır. Bu opera 1875 yılında bestelenmiştir ve en ünlü Fransız operalarından biridir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Carmen', NULL, 'https://en.wikipedia.org/wiki/Carmen', 'approved', 'Kurmancî', 1, now()),
('72ccfdff-d217-599f-83af-2ee4d151c89d', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di operayê de, kîjan peyv ji bo strana çar stranbêjan tê bikaranîn?', 'Trio', 'Kuartet', 'Dûet', 'Arya', 'B', 'Di operayê de, kuartet ji bo strana çar stranbêjan tê bikaranîn. Kuartet bi piranî ji bo nîşandana têkiliya di navbera çar lehengên operayê de tê bikaranîn.', 'Di operayê de, kuartet ji bo strana çar stranbêjan tê bikaranîn. Kuartet bi piranî ji bo nîşandana têkiliya di navbera çar lehengên operayê de tê bikaranîn.', 'Operada, dört şarkıcının söylediği şarkı için kuartet kullanılır. Kuartet çoğunlukla operadaki dört kahraman arasındaki ilişkiyi göstermek için kullanılır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Quartet', NULL, 'https://en.wikipedia.org/wiki/Quartet', 'approved', 'Kurmancî', 1, now()),
('7931d784-f5c3-5e4e-b9c5-61316e3266b5', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di muzîkê de, hevahengiya dengan ku bi hev re têne lêdan çi ye?', 'Melodî', 'Armonî', 'Rîtm', 'Kontrpuan', 'B', 'Armonî hevahengiya dengan e ku bi hev re têne lêdan. Melodî rêzika dengan, rîtm demê û kontrpuan jî tevliheviya melodiyan e.', 'Armonî hevahengiya dengan e ku bi hev re têne lêdan. Melodî rêzika dengan, rîtm demê û kontrpuan jî tevliheviya melodiyan e.', 'Armoni, birlikte çalınan seslerin uyumudur. Melodi seslerin sırası, ritim zaman ve kontrpuan da melodilerin birleşimidir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Harmony', NULL, 'https://en.wikipedia.org/wiki/Harmony', 'approved', 'Kurmancî', 1, now()),
('14b96820-a3a1-566e-8144-1385d4707eb6', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan têgîn ji bo nîşankirina hevahengiya dengan tê bikaranîn?', 'Rîtm', 'Tempo', 'Armonî', 'Nota', 'C', 'Armonî ji bo nîşankirina hevahengiya dengan tê bikaranîn. Rîtm demê, tempo lezê û nota jî bilindahiyê nîşan dide.', 'Armonî ji bo nîşankirina hevahengiya dengan tê bikaranîn. Rîtm demê, tempo lezê û nota jî bilindahiyê nîşan dide.', 'Armoni, seslerin uyumunu belirtmek için kullanılır. Ritim zamanı, tempo hızı ve nota da yüksekliği gösterir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Harmony', NULL, 'https://en.wikipedia.org/wiki/Harmony', 'approved', 'Kurmancî', 1, now()),
('5f72ab2b-9454-59f1-afde-4bd384ea34e4', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di kîjan salê de fîlma "Citizen Kane" a Orson Welles derket?', '1942', '1941', '1940', '1943', 'B', 'Ev fîlma efsanewî di sala 1941ê de derket û bi gelemperî weke yek ji fîlmên herî baş ên dîrokê tê hesibandin.', 'Ev fîlma efsanewî di sala 1941ê de derket û bi gelemperî weke yek ji fîlmên herî baş ên dîrokê tê hesibandin.', 'Bu efsanevi film 1941''de gösterime girdi ve genellikle tarihin en iyi filmlerinden biri olarak kabul edilir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Citizen_Kane', NULL, 'https://en.wikipedia.org/wiki/Citizen_Kane', 'approved', 'Kurmancî', 1, now()),
('965b0e74-e0fc-56c7-b8cb-6e79cfc5c944', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di kîjan salê de fîlma "The Godfather" a Francis Ford Coppola derket?', '1972', '1971', '1973', '1974', 'A', 'Fîlma "The Godfather" di sala 1972an de derket û weke yek ji fîlmên herî girîng ên dîroka sînemayê tê zanîn.', 'Fîlma "The Godfather" di sala 1972an de derket û weke yek ji fîlmên herî girîng ên dîroka sînemayê tê zanîn.', '"The Godfather" filmi 1972''de gösterime girdi ve sinema tarihinin en önemli filmlerinden biri olarak kabul edilir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Godfather', NULL, 'https://en.wikipedia.org/wiki/The_Godfather', 'approved', 'Kurmancî', 1, now()),
('691d2590-e752-5792-ba5a-841adf0813d2', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerê polonî fîlma "The Pianist" derxist?', 'Andrzej Wajda', 'Krzysztof Kieślowski', 'Roman Polanski', 'Paweł Pawlikowski', 'C', 'Roman Polanski derhênerê vî fîlmî ye ku di sala 2002yan de derket û li ser jiyana Władysław Szpilman e.', 'Roman Polanski derhênerê vî fîlmî ye ku di sala 2002yan de derket û li ser jiyana Władysław Szpilman e.', 'Roman Polanski, 2002''de gösterime giren ve Władysław Szpilman''ın hayatını konu alan bu filmin yönetmenidir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Pianist_(2002_film)', NULL, 'https://en.wikipedia.org/wiki/The_Pianist_(2002_film)', 'approved', 'Kurmancî', 1, now()),
('00ad6966-5cee-5b62-8adf-6ac8bdb73ed9', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di fîlmekî de, kîjan kes berpirsiyarê biryara cihê kamerayê û tevgera aktoran e?', 'Senarîst', 'Montajker', 'Derhêner', 'Kameraman', 'C', 'Derhêner (rejîsor) berpirsiyarê vîzyona fîlmê ye û biryar dide ka kamera li ku be û aktor çawa bilivin. Senarîst çîrokê dinivîse, montajker wêneyan dibire û dizeliqîne, kameraman jî wêneyan digire.', 'Derhêner (rejîsor) berpirsiyarê vîzyona fîlmê ye û biryar dide ka kamera li ku be û aktor çawa bilivin. Senarîst çîrokê dinivîse, montajker wêneyan dibire û dizeliqîne, kameraman jî wêneyan digire.', 'Yönetmen (rejisör) filmin vizyonundan sorumludur ve kameranın nerede olacağına ve oyuncuların nasıl hareket edeceğine karar verir. Senarist hikayeyi yazar, montajcı görüntüleri kesip birleştirir, kameraman ise görüntüleri çeker.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Film_director', NULL, 'https://en.wikipedia.org/wiki/Film_director', 'approved', 'Kurmancî', 1, now()),
('3a918fe8-e1cc-50c3-a085-9272f268b4ed', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di fîlmekî de, kîjan kes berpirsiyarê birîna wêneyan û lihevxistina wan e?', 'Derhêner', 'Senarîst', 'Montajker', 'Kameraman', 'C', 'Montajker (editor) berpirsiyarê birîna wêneyan, hilbijartina wan û lihevxistina wan e ji bo çêkirina fîlmekî. Derhêner vîzyona fîlmê kontrol dike, senarîst çîrokê dinivîse, kameraman jî wêneyan digire.', 'Montajker (editor) berpirsiyarê birîna wêneyan, hilbijartina wan û lihevxistina wan e ji bo çêkirina fîlmekî. Derhêner vîzyona fîlmê kontrol dike, senarîst çîrokê dinivîse, kameraman jî wêneyan digire.', 'Montajcı, görüntüleri kesmek, seçmek ve bir film oluşturmak için birleştirmekten sorumludur. Yönetmen filmin vizyonunu kontrol eder, senarist hikayeyi yazar, kameraman ise görüntüleri çeker.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Film_editor', NULL, 'https://en.wikipedia.org/wiki/Film_editor', 'approved', 'Kurmancî', 1, now()),
('34947686-8537-5ad5-8a89-621fa5d2fee5', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan fîlmê François Truffaut yek ji fîlmên destpêkê yên Pêla Nû ya Fransî ye?', 'Breathless', 'Cléo from 5 to 7', 'The 400 Blows', 'Hiroshima mon amour', 'C', '"The 400 Blows" (Les Quatre Cents Coups) di sala 1959an de ji aliyê François Truffaut ve hatiye derxistin û wekî yek ji fîlmên bingehîn ên Pêla Nû ya Fransî tê hesibandin. Fîlm çîroka xortekî bi navê Antoine Doinel vedibêje.', '"The 400 Blows" (Les Quatre Cents Coups) di sala 1959an de ji aliyê François Truffaut ve hatiye derxistin û wekî yek ji fîlmên bingehîn ên Pêla Nû ya Fransî tê hesibandin. Fîlm çîroka xortekî bi navê Antoine Doinel vedibêje.', '"The 400 Blows" (Les Quatre Cents Coups) 1959''da François Truffaut tarafından çekilmiş ve Fransız Yeni Dalgası''nın temel filmlerinden biri olarak kabul edilir. Film, Antoine Doinel adlı bir gencin hikayesini anlatır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_400_Blows', NULL, 'https://en.wikipedia.org/wiki/The_400_Blows', 'approved', 'Kurmancî', 1, now()),
('d3184c21-54f9-55df-a022-a6d34c2b8009', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan fîlmê Roberto Rossellini yek ji fîlmên destpêkê yên neorealîzma îtalyan e?', 'Bicycle Thieves', 'Rome, Open City', 'La dolce vita', 'The 400 Blows', 'B', '"Rome, Open City" di sala 1945an de ji aliyê Roberto Rossellini ve hatiye derxistin û wekî yek ji fîlmên destpêkê yên neorealîzma îtalyan tê qebûlkirin. Fîlm li ser berxwedana îtalyan a li dijî naziyan e.', '"Rome, Open City" di sala 1945an de ji aliyê Roberto Rossellini ve hatiye derxistin û wekî yek ji fîlmên destpêkê yên neorealîzma îtalyan tê qebûlkirin. Fîlm li ser berxwedana îtalyan a li dijî naziyan e.', '"Rome, Open City" 1945''te Roberto Rossellini tarafından çekilmiş ve İtalyan neorealizminin ilk filmlerinden biri olarak kabul edilir. Film, İtalyanların Nazilere karşı direnişini konu alır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Rome,_Open_City', NULL, 'https://en.wikipedia.org/wiki/Rome,_Open_City', 'approved', 'Kurmancî', 1, now()),
('b0091823-8bae-58c5-aebe-8dcf6af44ec3', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan fîlmê Jean-Luc Godard yek ji fîlmên herî navdar ên Pêla Nû ya Fransî ye?', 'Breathless', 'The 400 Blows', 'Jules and Jim', 'Hiroshima mon amour', 'A', '"Breathless" (À bout de souffle) di sala 1960î de ji aliyê Jean-Luc Godard ve hatiye derxistin û yek ji fîlmên herî navdar ên Pêla Nû ya Fransî ye. Fîlm bi teknîka xwe ya "jump cut" tê nasîn.', '"Breathless" (À bout de souffle) di sala 1960î de ji aliyê Jean-Luc Godard ve hatiye derxistin û yek ji fîlmên herî navdar ên Pêla Nû ya Fransî ye. Fîlm bi teknîka xwe ya "jump cut" tê nasîn.', '"Breathless" (À bout de souffle) 1960''ta Jean-Luc Godard tarafından çekilmiş ve Fransız Yeni Dalgası''nın en ünlü filmlerinden biridir. Film, "jump cut" tekniğiyle tanınır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Breathless_(1960_film)', NULL, 'https://en.wikipedia.org/wiki/Breathless_(1960_film)', 'approved', 'Kurmancî', 1, now()),
('43cc1d7a-4f3c-5c02-9560-2521b7c899b4', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerê amerîkî fîlma "Pulp Fiction" di sala 1994an de derxist?', 'Steven Spielberg', 'Quentin Tarantino', 'Martin Scorsese', 'Francis Ford Coppola', 'B', 'Quentin Tarantino derhênerê fîlma "Pulp Fiction" e. Ev fîlm di sala 1994an de derket û di festîvala Cannesê de Xelata Palmiyeya Zêrîn wergirt. Steven Spielberg, Martin Scorsese û Francis Ford Coppola jî derhênerên navdar in lê ev fîlm ne ya wan e.', 'Quentin Tarantino derhênerê fîlma "Pulp Fiction" e. Ev fîlm di sala 1994an de derket û di festîvala Cannesê de Xelata Palmiyeya Zêrîn wergirt. Steven Spielberg, Martin Scorsese û Francis Ford Coppola jî derhênerên navdar in lê ev fîlm ne ya wan e.', 'Quentin Tarantino, "Pulp Fiction" filminin yönetmenidir. Bu film 1994 yılında gösterime girdi ve Cannes Film Festivali''nde Altın Palmiye Ödülü kazandı. Steven Spielberg, Martin Scorsese ve Francis Ford Coppola da ünlü yönetmenlerdir ancak bu film onlara ait değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Pulp_Fiction', NULL, 'https://en.wikipedia.org/wiki/Pulp_Fiction', 'approved', 'Kurmancî', 1, now()),
('f52a52d0-88e6-5f90-b92d-cd1d5543cfb2', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di fîlma "Pulp Fiction" de, kîjan aktor rola Jules Winnfield lîstiye?', 'John Travolta', 'Bruce Willis', 'Uma Thurman', 'Samuel L. Jackson', 'D', 'Samuel L. Jackson di fîlma "Pulp Fiction" a Quentin Tarantino de rola Jules Winnfield lîstiye. Ev rol yek ji rolên herî navdar ên kariyera wî ye. John Travolta rola Vincent Vega lîstiye, Bruce Willis rola Butch Coolidge û Uma Thurman jî rola Mia Wallace lîstiye.', 'Samuel L. Jackson di fîlma "Pulp Fiction" a Quentin Tarantino de rola Jules Winnfield lîstiye. Ev rol yek ji rolên herî navdar ên kariyera wî ye. John Travolta rola Vincent Vega lîstiye, Bruce Willis rola Butch Coolidge û Uma Thurman jî rola Mia Wallace lîstiye.', 'Samuel L. Jackson, Quentin Tarantino''nun "Ucuz Roman" filminde Jules Winnfield rolünü canlandırdı. Bu rol, kariyerinin en ünlü rollerinden biridir. John Travolta Vincent Vega, Bruce Willis Butch Coolidge ve Uma Thurman ise Mia Wallace rolünü oynadı.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Pulp_Fiction', NULL, 'https://en.wikipedia.org/wiki/Pulp_Fiction', 'approved', 'Kurmancî', 1, now()),
('68333b3e-a0e5-5444-8f7d-2121b3478dec', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlma "Babamın Kanatları" bi lîstikvaniya "Menderes Samancılar" kîjan pirsgirêka civakî tîne ziman?', 'Gera tûrîstên dewlemend li ser peravên deryayê', 'Pêşketina şîrketên komputerê di qada firotina serhêl de', 'Perwerdehiya pîlotên balafiran di akademiyên leşkerî de', 'Kuştinên karkeran di qada înşatê de û bêewlehiya jiyana karkerên koçber', 'D', 'Karkerê bi navê Îbrahîm bi penceşêrê ketiye û li înşata luks hewl dide ji bo malbata xwe tezmînatê bihêle.', 'Karkerê bi navê Îbrahîm bi penceşêrê ketiye û li înşata luks hewl dide ji bo malbata xwe tezmînatê bihêle.', 'Film, lüks toplu konut şantiyelerinde çalışan ve ölümcül hastalığa yakalanan inşaat işçisi İbrahim''in çaresizliğini anlatır.', 4, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()),
('515ff510-410b-5a50-8dad-5160d9177d89', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Li herêmên nêzîkî ekvatorê, bi germahî û barîna zêde, kîjan cure daristan tê dîtin?', 'Daristana kajan', 'Daristana baranê', 'Daristana pelweşîner', 'Daristana bejayî', 'B', 'Daristana baranê li herêmên nêzîkî ekvatorê, bi germahî û barîna zêde, gelek cureyên riwekan lê hene.', 'Daristana baranê li herêmên nêzîkî ekvatorê, bi germahî û barîna zêde, gelek cureyên riwekan lê hene.', 'Yağmur ormanı, ekvatora yakın, yüksek sıcaklık ve yağışın olduğu bölgelerde bulunur ve birçok bitki türüne ev sahipliği yapar.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Tropical_rainforest', NULL, 'https://en.wikipedia.org/wiki/Tropical_rainforest', 'approved', 'Kurmancî', 1, now()),
('35a1bc3b-52f6-5855-8ba7-73b2ff5fe04c', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Li deverên ziwa û hişk, bi barîna kêm, kîjan cure giyayî bi piranî tê dîtin?', 'Giyayên çolê', 'Giyayên deştê', 'Giyayên mêrgan', 'Giyayên zozanan', 'A', 'Giyayên çolê li deverên ziwa û hişk, bi barîna kêm, bi piranî tên dîtin.', 'Giyayên çolê li deverên ziwa û hişk, bi barîna kêm, bi piranî tên dîtin.', 'Çöl otları, kurak ve kuru, az yağışlı bölgelerde en çok bulunur.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Desert', NULL, 'https://en.wikipedia.org/wiki/Desert', 'approved', 'Kurmancî', 1, now()),
('846d58b2-1510-5ee3-b46d-37612097dcbc', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Li herêmên sar, bi zivistanên dirêj û havînên kurt, kîjan cure daristan tê dîtin?', 'Daristana baranê', 'Daristana taygayê', 'Daristana pelweşîner', 'Daristana tropîkal', 'B', 'Daristana taygayê li herêmên sar, bi zivistanên dirêj û havînên kurt, tê dîtin.', 'Daristana taygayê li herêmên sar, bi zivistanên dirêj û havînên kurt, tê dîtin.', 'Tayga ormanı, uzun kışlar ve kısa yazlar ile soğuk bölgelerde bulunur.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Taiga', NULL, 'https://en.wikipedia.org/wiki/Taiga', 'approved', 'Kurmancî', 1, now()),
