('69da1715-393c-5acb-8c54-2d538ea1cddd', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Ji bo şiklê erdê yê dirêj ê ku ji derdora xwe nizmtir e kîjan têgeh tê bikaranîn?', 'Zinar', 'Çem', 'Newal', 'Gol', 'C', 'Newal şiklekî erdê yê dirêj e ku ji derdora xwe nizmtir e; dibe ku çem tê de hebe, lê newal ne çem bi xwe ye.', 'Newal şiklekî erdê yê dirêj e ku ji derdora xwe nizmtir e; dibe ku çem tê de hebe, lê newal ne çem bi xwe ye.', 'Vadi, çevresindeki yükseltilere göre alçakta kalan, uzanan yeryüzü şeklidir; içinde akarsu bulunabilir ama vadi akarsuyun kendisi değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Valley', NULL, 'https://en.wikipedia.org/wiki/Valley', 'approved', 'Kurmancî', 1, now()),
('32ab3478-e1b9-58c8-9bb3-58de5fbe48d6', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan têgeh ji bo erdekî bilind û pan re tê bikaranîn?', 'Plato', 'Deşt', 'Zinar', 'Newal', 'A', 'Plato erdekî bilind û pan e ku ji derdora xwe bilindtir e. Deşt ne bilind e, zinar ne pan e, newal jî ne bilind e.', 'Plato erdekî bilind û pan e ku ji derdora xwe bilindtir e. Deşt ne bilind e, zinar ne pan e, newal jî ne bilind e.', 'Plato, çevresine göre yüksekte kalan geniş düzlüklerdir. Ova yüksek değildir, kaya geniş değildir, vadi de yüksek değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Plateau', NULL, 'https://en.wikipedia.org/wiki/Plateau', 'approved', 'Kurmancî', 1, now()),
('e3357eec-f258-577c-99f8-9f3131ca0ff3', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan têgeh ji bo erdekî nizm û pan re tê bikaranîn ku çemek di nav re derbas dibe?', 'Zinar', 'Plato', 'Newal', 'Deşt', 'D', 'Deşt erdekî nizm û pan e ku çemek di nav re derbas dibe. Zinar ne nizm e, plato bilind e, newal jî ne pan e.', 'Deşt erdekî nizm û pan e ku çemek di nav re derbas dibe. Zinar ne nizm e, plato bilind e, newal jî ne pan e.', 'Ova, içinden bir akarsuyun geçtiği alçak ve geniş düzlüklerdir. Kaya alçak değildir, plato yüksektir, vadi de geniş değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Plain', NULL, 'https://en.wikipedia.org/wiki/Plain', 'approved', 'Kurmancî', 1, now()),
('fa171689-95a2-57d3-b09a-861cc95ba45f', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan têgeh ji bo erdekî nizm û pan re tê bikaranîn ku ji aliyê çemekî ve tê avdan?', 'Deşt', 'Zinar', 'Plato', 'Newal', 'A', 'Deşt erdekî nizm û pan e ku ji aliyê çemekî ve tê avdan. Zinar ne nizm e, plato bilind e, newal jî ne pan e.', 'Deşt erdekî nizm û pan e ku ji aliyê çemekî ve tê avdan. Zinar ne nizm e, plato bilind e, newal jî ne pan e.', 'Ova, bir akarsu tarafından sulanan alçak ve geniş düzlüklerdir. Kaya alçak değildir, plato yüksektir, vadi de geniş değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Plain', NULL, 'https://en.wikipedia.org/wiki/Plain', 'approved', 'Kurmancî', 1, now()),
('56c0aa20-fc77-5115-a081-093497676993', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Ji cihê ku çemek axê bi xwe re dibe û li devê deryayê kom dike re kîjan têgeh tê bikaranîn?', 'Newal', 'Plato', 'Deşt', 'Delta', 'D', 'Delta, ji cihê ku çemek axê bi xwe re dibe û li devê deryayê kom dike re tê gotin. Newal û plato ne têgehên rast in ji bo vê pênaseyê.', 'Delta, ji cihê ku çemek axê bi xwe re dibe û li devê deryayê kom dike re tê gotin. Newal û plato ne têgehên rast in ji bo vê pênaseyê.', 'Delta, beraberinde toprak taşıyan akarsuyun denize döküldüğü yerde toprağı biriktirmesiyle oluşur. Vadi ve plato bu tanım için doğru terimler değildir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/River_delta', NULL, 'https://en.wikipedia.org/wiki/River_delta', 'approved', 'Kurmancî', 1, now()),
('db5c4e55-e936-5bc2-b918-0c8cb3d8b3ed', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di navbera du çiyayan de, kîjan têgeh ji bo erdekî nizm re tê bikaranîn?', 'Plato', 'Deşt', 'Newal', 'Delta', 'C', 'Newal, erdekî nizm e ku di navbera du çiyayan de ye. Plato bilind e, deşt ne di navbera çiyayan de ye, delta jî li cihê ku çem digihîje deryayê çêdibe.', 'Newal, erdekî nizm e ku di navbera du çiyayan de ye. Plato bilind e, deşt ne di navbera çiyayan de ye, delta jî li cihê ku çem digihîje deryayê çêdibe.', 'Vadi, iki dağ arasında kalan alçak arazidir. Plato yüksektir, ova dağlar arasında değildir, delta ise akarsuyun denize döküldüğü yerdir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Valley', NULL, 'https://en.wikipedia.org/wiki/Valley', 'approved', 'Kurmancî', 1, now()),
('b5818278-ef5e-5ec2-b1a2-61afa98a90c9', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan lewhe li ser rûyê erdê di bin okyanûsan de ye?', 'Lewheya parzemînî', 'Lewheya volkanîk', 'Lewheya qeşayî', 'Lewheya okyanûsî', 'D', 'Lewheya okyanûsî li bin okyanûsan e û ji lewheya parzemînî ziravtir û tîrtir e.', 'Lewheya okyanûsî li bin okyanûsan e û ji lewheya parzemînî ziravtir û tîrtir e.', 'Okyanusal levha, okyanusların altındadır ve kıtasal levhadan daha ince ve yoğundur.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Oceanic_crust', NULL, 'https://en.wikipedia.org/wiki/Oceanic_crust', 'approved', 'Kurmancî', 1, now()),
('ca7dd807-a2f7-5241-9b37-3a072812442d', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan lewhe li ser rûyê erdê di bin parzemînan de ye?', 'Lewheya okyanûsî', 'Lewheya volkanîk', 'Lewheya parzemînî', 'Lewheya qeşayî', 'C', 'Lewheya parzemînî li bin parzemînan e û ji lewheya okyanûsî stûrtir û siviktir e.', 'Lewheya parzemînî li bin parzemînan e û ji lewheya okyanûsî stûrtir û siviktir e.', 'Kıtasal levha, kıtaların altındadır ve okyanusal levhadan daha kalın ve daha hafiftir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Continental_crust', NULL, 'https://en.wikipedia.org/wiki/Continental_crust', 'approved', 'Kurmancî', 1, now()),
('3cf25b9b-70ba-544a-8ace-e22f62f443dc', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan bûyer bi tevgera lewheyan ve girêdayî ye?', 'Barîn', 'Berf', 'Erdhej', 'Ba', 'C', 'Erdhej bi tevgera lewheyan ve girêdayî ye, ji ber ku lewheyên tektonîk li hev dixin û enerjiyê berdidin.', 'Erdhej bi tevgera lewheyan ve girêdayî ye, ji ber ku lewheyên tektonîk li hev dixin û enerjiyê berdidin.', 'Deprem, tektonik levhaların birbirine çarpması ve enerji açığa çıkarması nedeniyle levha hareketleriyle ilişkilidir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Earthquake', NULL, 'https://en.wikipedia.org/wiki/Earthquake', 'approved', 'Kurmancî', 1, now()),
('23454807-2c24-593c-a76d-175d6588ec22', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di nexşeyekê de pîvana 1:50.000 tê çi wateyê?', 'Yek santîmetre li nexşeyê 5 kîlometre ye', 'Yek santîmetre li nexşeyê 500 santîmetre ye', 'Yek santîmetre li nexşeyê 5 metre ye', 'Yek santîmetre li nexşeyê 500 metre ye', 'D', 'Pîvana 1:50.000 tê wê wateyê ku yekîneyek li ser nexşeyê bi 50.000 yekîneyên li erdê re wekhev e. Ji ber ku 50.000 santîmetre 500 metre ye, ev pîvan nîşan dide ku 1 santîmetreya li nexşeyê li erdê dibe 500 metre.', 'Pîvana 1:50.000 tê wê wateyê ku yekîneyek li ser nexşeyê bi 50.000 yekîneyên li erdê re wekhev e. Ji ber ku 50.000 santîmetre 500 metre ye, ev pîvan nîşan dide ku 1 santîmetreya li nexşeyê li erdê dibe 500 metre.', '1:50.000 ölçeği, haritadaki bir birimin yerdeki 50.000 birime eşit olduğu anlamına gelir. 50.000 santimetre beş yüz metre olduğundan, bu ölçek haritadaki bir santimetrenin yaklaşık beş yüz metre olduğu anlamına gelir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Scale_(map)', NULL, 'https://en.wikipedia.org/wiki/Scale_(map)', 'approved', 'Kurmancî', 1, now()),
('c97a758c-60f5-5b96-a466-ec95b96ec91f', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan xet li ser nexşeyê hêlîdirêja sifir e?', 'Xeta Greenwichê', 'Xeta ekvatorê', 'Xeta tropîkê', 'Xeta qutbê', 'A', 'Xeta Greenwichê (merîdyena sifir) hêlîdirêja sifir e û ji Greenwicha Londonê derbas dibe. Ekvator hêlîpana sifir e, ne hêlîdirêj.', 'Xeta Greenwichê (merîdyena sifir) hêlîdirêja sifir e û ji Greenwicha Londonê derbas dibe. Ekvator hêlîpana sifir e, ne hêlîdirêj.', 'Greenwich çizgisi (baş meridyen) sıfır boylamıdır ve Greenwich, Londra''dan geçer. Ekvator, sıfır enlemidir, boylam değil.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Prime_meridian', NULL, 'https://en.wikipedia.org/wiki/Prime_meridian', 'approved', 'Kurmancî', 1, now()),
('6e2bbba5-4c90-56b6-b767-a0f1cfe815c0', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan xet li ser nexşeyê hêlîpana sifir e?', 'Xeta ekvatorê', 'Xeta Greenwichê', 'Xeta tropîkê', 'Xeta qutbê', 'A', 'Xeta ekvatorê hêlîpana sifir e û erdê dike du nîvkadên bakur û başûr. Greenwich hêlîdirêja sifir e.', 'Xeta ekvatorê hêlîpana sifir e û erdê dike du nîvkadên bakur û başûr. Greenwich hêlîdirêja sifir e.', 'Ekvator çizgisi sıfır enlemidir ve dünyayı kuzey ve güney olmak üzere iki yarımküreye ayırır. Greenwich ise sıfır boylamıdır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Equator', NULL, 'https://en.wikipedia.org/wiki/Equator', 'approved', 'Kurmancî', 1, now()),
('5b2de641-4e4b-5a58-bb9e-2223f1f015ad', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan nexşe bilindahî û şiklên erdê bi hûrgulî nîşan dide?', 'Nexşeya siyasî', 'Nexşeya aborî', 'Nexşeya topografîk', 'Nexşeya dînî', 'C', 'Nexşeya topografîk bilindahiyan, çiyayan, deştan û rûberên erdê nîşan dide. Nexşeya siyasî sînorên welatan nîşan dide.', 'Nexşeya topografîk bilindahiyan, çiyayan, deştan û rûberên erdê nîşan dide. Nexşeya siyasî sînorên welatan nîşan dide.', 'Topografik harita yükseklikleri, dağları, ovaları ve dünya yüzeyini gösterir. Siyasi harita ise ülkelerin sınırlarını gösterir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Topographic_map', NULL, 'https://en.wikipedia.org/wiki/Topographic_map', 'approved', 'Kurmancî', 1, now()),
('5f94a96e-da78-5026-a1da-03ca28e3fb78', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan projeksiyon rûberên parzemînan bi rêjeya rast nîşan dide?', 'Projeksiyona Mercator', 'Projeksiyona Peters', 'Projeksiyona Robinson', 'Projeksiyona Azîmûtal', 'B', 'Projeksiyona Peters rûberên parzemînan bi rêjeya rast nîşan dide, lê şikilên wan xerab dike. Mercator rûberan mezin dike, Robinson hevsengiyekê çêdike.', 'Projeksiyona Peters rûberên parzemînan bi rêjeya rast nîşan dide, lê şikilên wan xerab dike. Mercator rûberan mezin dike, Robinson hevsengiyekê çêdike.', 'Peters Projeksiyonu kıtaların yüzeylerini gerçek oranlarıyla gösterir, ancak şekillerini bozar. Mercator yüzeyleri büyütür, Robinson ise bir denge kurar.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Gall%E2%80%93Peters_projection', NULL, 'https://en.wikipedia.org/wiki/Gall%E2%80%93Peters_projection', 'approved', 'Kurmancî', 1, now()),
('b0ff7385-00e6-5736-9f1a-ec13f7858a42', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan têgeh ji bo xetên ku bilindahiya wekhev nîşan didin tê bikaranîn?', 'Xetên îzolîn', 'Xetên paralel', 'Xetên merîdyen', 'Xeta ekvatorê', 'A', 'Xetên îzolîn (contour lines) xetên ku bilindahiya wekhev li ser nexşeya topografîk nîşan didin in. Paralel û merîdyen koordînat in, ne bilindahî.', 'Xetên îzolîn (contour lines) xetên ku bilindahiya wekhev li ser nexşeya topografîk nîşan didin in. Paralel û merîdyen koordînat in, ne bilindahî.', 'İzolin (kontur) çizgileri, topografik haritada eşit yükseklikteki noktaları gösteren çizgilerdir. Paraleller ve meridyenler koordinattır, yükseklik değil.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Contour_line', NULL, 'https://en.wikipedia.org/wiki/Contour_line', 'approved', 'Kurmancî', 1, now()),
('0e8ec496-8f62-565b-9f16-ee9609573189', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan projeksiyon ji bo nexşeya cîhanê ya ku rûber û şikilan bi hevsengiyekê nîşan dide tê bikaranîn?', 'Projeksiyona Robinson', 'Projeksiyona Mercator', 'Projeksiyona Peters', 'Projeksiyona Azîmûtal', 'A', 'Projeksiyona Robinson rûber û şikilan bi hevsengiyekê nîşan dide, ji ber vê yekê ji bo nexşeya cîhanê tê bikaranîn. Mercator rûberan mezin dike, Peters jî şikilan xerab dike.', 'Projeksiyona Robinson rûber û şikilan bi hevsengiyekê nîşan dide, ji ber vê yekê ji bo nexşeya cîhanê tê bikaranîn. Mercator rûberan mezin dike, Peters jî şikilan xerab dike.', 'Robinson Projeksiyonu yüzeyleri ve şekilleri dengeli bir şekilde gösterir, bu yüzden dünya haritası için kullanılır. Mercator yüzeyleri büyütür, Peters ise şekilleri bozar.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Robinson_projection', NULL, 'https://en.wikipedia.org/wiki/Robinson_projection', 'approved', 'Kurmancî', 1, now()),
('f4e67d62-aea8-56a1-88e8-878db7b034d9', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan têgih ji bo xeta ku hêlîpan û hêlîdirêjan li ser nexşeyê nîşan dide tê bikaranîn?', 'Xeta îzolîn', 'Tora koordînat', 'Xeta paralel', 'Xeta merîdyen', 'B', 'Tora koordînat (graticule) ji xetên ku hêlîpan û hêlîdirêjan li ser nexşeyê nîşan didin pêk tê. Xetên îzolîn bilindahiyê nîşan didin.', 'Tora koordînat (graticule) ji xetên ku hêlîpan û hêlîdirêjan li ser nexşeyê nîşan didin pêk tê. Xetên îzolîn bilindahiyê nîşan didin.', 'Koordinat ağı (graticule), haritada enlem ve boylamları gösteren çizgilerdir. İzolin çizgisi ise yüksekliği gösterir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Graticule_(cartography)', NULL, 'https://en.wikipedia.org/wiki/Graticule_(cartography)', 'approved', 'Kurmancî', 1, now()),
('4fe3efb1-11ed-5766-9d87-b86ff92c88ca', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Ji guhertina nifûsê ya ku ji ferqa navbera zayîn û mirinan pêk tê re çi tê gotin?', 'Zêdebûna xwezayî', 'Zêdebûna koçberiyê', 'Zêdebûna tevayî', 'Zêdebûna demkî', 'A', 'Zêdebûna xwezayî ferqa di navbera zayîn û mirinan de ye. Zêdebûna koçberiyê ji ber koçberan e, ya tevayî hemû sedeman dihewîne, ya demkî jî demkî ye.', 'Zêdebûna xwezayî ferqa di navbera zayîn û mirinan de ye. Zêdebûna koçberiyê ji ber koçberan e, ya tevayî hemû sedeman dihewîne, ya demkî jî demkî ye.', 'Doğal artış, doğumlar ve ölümler arasındaki farktır. Göç artışı göçmenlerden kaynaklanır, toplam artış tüm nedenleri kapsar, geçici artış ise geçicidir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Natural_increase', NULL, 'https://en.wikipedia.org/wiki/Natural_increase', 'approved', 'Kurmancî', 1, now()),
('7d907bb0-aaf6-5960-87df-dbb192569c0a', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan têgih ji bo koçkirina mirovan ji welatekî bo welatekî din tê bikaranîn?', 'Koçberiya hundirîn', 'Koçberiya derveyî', 'Koçberiya demkî', 'Koçberiya çerxî', 'B', 'Koçberiya derveyî tê wateya koçkirina bo welatekî din. Koçberiya hundirîn di nav welatekî de ye, ya demkî û çerxî jî demkî ne.', 'Koçberiya derveyî tê wateya koçkirina bo welatekî din. Koçberiya hundirîn di nav welatekî de ye, ya demkî û çerxî jî demkî ne.', 'Dış göç, başka bir ülkeye göç etmek anlamına gelir. İç göç bir ülke içindedir, geçici ve döngüsel göç ise geçicidir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Human_migration', NULL, 'https://en.wikipedia.org/wiki/Human_migration', 'approved', 'Kurmancî', 1, now()),
('4be17de0-7e2c-526f-a407-3bf4e9decc14', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan têgih ji bo nifûsa ku li deverekê dijî û ji dayik dibe tê bikaranîn?', 'Nifûsa tevayî', 'Nifûsa koçber', 'Nifûsa xwecih', 'Nifûsa demkî', 'C', 'Nifûsa xwecih ew nifûs e ku li wê deverê ji dayik bûye û lê dijî. Nifûsa tevayî hemû kesan dihewîne, ya koçber û demkî jî ne xwecih in.', 'Nifûsa xwecih ew nifûs e ku li wê deverê ji dayik bûye û lê dijî. Nifûsa tevayî hemû kesan dihewîne, ya koçber û demkî jî ne xwecih in.', 'Yerli nüfus, o bölgede doğmuş ve orada yaşayan nüfustur. Toplam nüfus herkesi kapsar, göçmen ve geçici nüfus ise yerli değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Indigenous_peoples', NULL, 'https://en.wikipedia.org/wiki/Indigenous_peoples', 'approved', 'Kurmancî', 1, now()),
('29206f33-922b-5460-ac59-c30012622004', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Ji hejmara kesên ku dikevin ser yekîneyeke qadê re çi tê gotin?', 'Dendika nifûsê', 'Nifûsa tevayî', 'Rêjeya zayînê', 'Rêjeya mirinê', 'A', 'Dendika nifûsê hejmara mirovan di yek kîlometre çargoşe de ye. Nifûsa tevayî hemû kesan e, rêjeya zayînê û mirinê jî pîvanên din in.', 'Dendika nifûsê hejmara mirovan di yek kîlometre çargoşe de ye. Nifûsa tevayî hemû kesan e, rêjeya zayînê û mirinê jî pîvanên din in.', 'Nüfus yoğunluğu, bir kilometrekaredeki insan sayısıdır. Toplam nüfus herkestir, doğum ve ölüm oranları ise diğer ölçütlerdir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Population_density', NULL, 'https://en.wikipedia.org/wiki/Population_density', 'approved', 'Kurmancî', 1, now()),
('46579dc0-7aab-53a3-9f6c-3b7195794ad9', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Zimanê nivîskî yê herî kevn ku li Mezopotamyayê hatiye dîtin kîjan e?', 'Akkadî', 'Sumerî', 'Elamî', 'Aramî', 'B', 'Sumerî zimanê herî kevn e ku bi nivîsî hatiye dîtin, li dora 3000 sal berî zayînê. Akkadî paşê derket, Elamî û Aramî jî zimanên din ên herêmê bûn.', 'Sumerî zimanê herî kevn e ku bi nivîsî hatiye dîtin, li dora 3000 sal berî zayînê. Akkadî paşê derket, Elamî û Aramî jî zimanên din ên herêmê bûn.', 'Sümerce, milattan önce 3000 civarında yazılı olarak bulunan en eski dildir. Akadca daha sonra ortaya çıktı, Elamca ve Aramice ise bölgenin diğer dilleriydi.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Sumerian_language', NULL, 'https://en.wikipedia.org/wiki/Sumerian_language', 'approved', 'Kurmancî', 1, now()),
('6cfe7544-22b1-53a6-a3e3-fd1c83c74830', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan padîşahî qanûnên navdar ên Babîlê çêkirin?', 'Sargon', 'Naram-Sîn', 'Gudea', 'Hamûrabî', 'D', 'Hamûrabî, padîşahê Babîlê, qanûnên ku bi navê wî têne zanîn çêkirin. Sargon û Naram-Sîn padîşahên Akkadê bûn, Gudea jî hukimdarê Lagashê bû.', 'Hamûrabî, padîşahê Babîlê, qanûnên ku bi navê wî têne zanîn çêkirin. Sargon û Naram-Sîn padîşahên Akkadê bûn, Gudea jî hukimdarê Lagashê bû.', 'Babil kralı Hammurabi, kendi adıyla bilinen kanunları oluşturdu. Sargon ve Naram-Sin Akkad krallarıydı, Gudea ise Lagaş hükümdarıydı.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Hammurabi', NULL, 'https://en.wikipedia.org/wiki/Hammurabi', 'approved', 'Kurmancî', 1, now()),
('f3c3db66-11ad-5124-928d-80424aef578c', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di serdema kîjan şaristaniyê de nivîsa bizmarî (cuneiform) pêş ket?', 'Babîlî', 'Sumerî', 'Asûrî', 'Akkadî', 'B', 'Nivîsîna bi tîpên çivîk ji aliyê Sumeriyan ve hate îcad kirin û pêş ket. Babîlî, Asûrî û Akkadî paşê vê nivîsînê bi kar anîn.', 'Nivîsîna bi tîpên çivîk ji aliyê Sumeriyan ve hate îcad kirin û pêş ket. Babîlî, Asûrî û Akkadî paşê vê nivîsînê bi kar anîn.', 'Çivi yazısı Sümerler tarafından icat edildi ve geliştirildi. Babilliler, Asurlular ve Akkadlar daha sonra bu yazıyı kullandılar.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Cuneiform', NULL, 'https://en.wikipedia.org/wiki/Cuneiform', 'approved', 'Kurmancî', 1, now()),
('6fd21bb9-c8a1-5574-89c3-abacb7b0405f', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan padîşahê Asûrê pirtûkxaneya navdar a Nînovayê ava kir?', 'Sargon II', 'Sennacherib', 'Aşurbanipal', 'Tiglath-Pileser III', 'C', 'Aşurbanipal pirtûkxaneya navdar a Nînovayê ava kir, ku bi hezaran nivîsên bizmarî tê de bûn. Sargon II, Sennacherib û Tiglath-Pileser III padîşahên din bûn.', 'Aşurbanipal pirtûkxaneya navdar a Nînovayê ava kir, ku bi hezaran nivîsên bizmarî tê de bûn. Sargon II, Sennacherib û Tiglath-Pileser III padîşahên din bûn.', 'Aşurbanipal, içinde binlerce çivi yazılı metin bulunan ünlü Ninova Kütüphanesi''ni inşa ettirdi. Sargon II, Sennacherib ve Tiglath-Pileser III ise diğer krallardı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Ashurbanipal', NULL, 'https://en.wikipedia.org/wiki/Ashurbanipal', 'approved', 'Kurmancî', 1, now()),
('4e9168af-2986-5d35-8433-0e161c941f76', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Şerê Cîhanê yê Yekem di kîjan salê de dest pê kir?', '1912', '1914', '1916', '1918', 'B', 'Şerê Cîhanê yê Yekem di 28''ê tîrmeha 1914''an de dest pê kir, piştî ku Arşîdûk Franz Ferdinand hate kuştin. Ev bûyer bû sedema zincîreka bûyeran ku bû sedema şerê navneteweyî.', 'Şerê Cîhanê yê Yekem di 28''ê tîrmeha 1914''an de dest pê kir, piştî ku Arşîdûk Franz Ferdinand hate kuştin. Ev bûyer bû sedema zincîreka bûyeran ku bû sedema şerê navneteweyî.', 'Birinci Dünya Savaşı, Arşidük Franz Ferdinand''ın öldürülmesinin ardından 28 Temmuz 1914''te başladı. Bu olay, uluslararası savaşa yol açan bir dizi olayın tetikleyicisi oldu.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/World_War_I', NULL, 'https://en.wikipedia.org/wiki/World_War_I', 'approved', 'Kurmancî', 1, now()),
('cc90f0c7-3317-5d44-9c76-672e2612337b', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Şerê Waterlooyê di kîjan salê de pêk hat?', '1815', '1805', '1812', '1820', 'A', 'Şerê Waterlooê di 18''ê hezîrana 1815''an de pêk hat. Di vî şerî de hêzên Brîtanî û Prûsî bi serokatiya Wellington û Blücher, Napoleon Bonaparte têk birin.', 'Şerê Waterlooê di 18''ê hezîrana 1815''an de pêk hat. Di vî şerî de hêzên Brîtanî û Prûsî bi serokatiya Wellington û Blücher, Napoleon Bonaparte têk birin.', 'Waterloo Savaşı 18 Haziran 1815''te gerçekleşti. Bu savaşta Wellington ve Blücher liderliğindeki İngiliz ve Prusya kuvvetleri, Napolyon Bonapart''ı yendi.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Battle_of_Waterloo', NULL, 'https://en.wikipedia.org/wiki/Battle_of_Waterloo', 'approved', 'Kurmancî', 1, now()),
('f9b4fa8d-8e7f-5a39-beb1-24a7474c8f31', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di kîjan serdemê de Şerê Sed Salan qewimî?', 'Sedsala 12''an û 13''an', 'Sedsala 13''an û 14''an', 'Sedsala 14''an û 15''an', 'Sedsala 15''an û 16''an', 'C', 'Şerê Sed Salan di navbera 1337 û 1453''an de qewimî, ango di sedsala 14''an û 15''an de. Ev şer di navbera Îngilistan û Fransayê de bû.', 'Şerê Sed Salan di navbera 1337 û 1453''an de qewimî, ango di sedsala 14''an û 15''an de. Ev şer di navbera Îngilistan û Fransayê de bû.', 'Yüz Yıl Savaşları 1337 ile 1453 yılları arasında, yani 14. ve 15. yüzyılda gerçekleşti. Bu savaş İngiltere ve Fransa arasında yapıldı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Hundred_Years%27_War', NULL, 'https://en.wikipedia.org/wiki/Hundred_Years%27_War', 'approved', 'Kurmancî', 1, now()),
('8f21cef6-6cba-5d75-93dc-624e8246ccae', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan şerên navdar di navbera Romayê û Kartacayê de qewimîn?', 'Şerên Pûnîk', 'Şerên Medî', 'Şerên Yewnanî', 'Şerên Galî', 'A', 'Şerên Pûnîk di navbera 264 û 146''an berî zayînê de navbera Romayê û Kartacayê de qewimîn. Sê şerên mezin hebûn ku di encama wan de Kartaca hate hilweşandin.', 'Şerên Pûnîk di navbera 264 û 146''an berî zayînê de navbera Romayê û Kartacayê de qewimîn. Sê şerên mezin hebûn ku di encama wan de Kartaca hate hilweşandin.', 'Pön Savaşları, MÖ 264 ile 146 yılları arasında Roma ile Kartaca arasında yapıldı. Üç büyük savaş yaşandı ve sonucunda Kartaca yıkıldı.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Punic_Wars', NULL, 'https://en.wikipedia.org/wiki/Punic_Wars', 'approved', 'Kurmancî', 1, now()),
('552cdebf-a7f3-5b1f-8136-00ebd67ccfd2', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan şer di sala 1805''an de qewimî û tê de Napoleonî artêşên Rûs û Awistirî têk birin?', 'Şerê Jenayê', 'Şerê Borodinoyê', 'Şerê Austerlitzê', 'Şerê Leipzigê', 'C', 'Şerê Austerlitzê, ku wek "Şerê Sê Împaratoran" jî tê zanîn, di 2''ê kanûna pêşîn a 1805''an de qewimî. Napoleonî di vî şerî de artêşên Rûs û Awistirî yên bi serokatiya Çar Alexanderê Yekem û Împarator Francisê Duyem têk birin.', 'Şerê Austerlitzê, ku wek "Şerê Sê Împaratoran" jî tê zanîn, di 2''ê kanûna pêşîn a 1805''an de qewimî. Napoleonî di vî şerî de artêşên Rûs û Awistirî yên bi serokatiya Çar Alexanderê Yekem û Împarator Francisê Duyem têk birin.', '"Üç İmparator Savaşı" olarak da bilinen Austerlitz Savaşı, 2 Aralık 1805''te gerçekleşti. Napolyon bu savaşta Çar I. Alexander ve İmparator II. Francis liderliğindeki Rus ve Avusturya ordularını yendi.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Battle_of_Austerlitz', NULL, 'https://en.wikipedia.org/wiki/Battle_of_Austerlitz', 'approved', 'Kurmancî', 1, now()),
('0c183eb0-451d-5f6f-851a-d623fe5ba42d', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Şerê Verdunê di kîjan salê de qewimî?', '1916', '1914', '1915', '1917', 'A', 'Şerê Verdunê di 21''ê sibata 1916''an de dest pê kir û heta 18''ê kanûna pêşîn a 1916''an dom kir. Ev şer yek ji dirêjtirîn û xwîntirîn şerên Şerê Cîhanê yê Yekem bû.', 'Şerê Verdunê di 21''ê sibata 1916''an de dest pê kir û heta 18''ê kanûna pêşîn a 1916''an dom kir. Ev şer yek ji dirêjtirîn û xwîntirîn şerên Şerê Cîhanê yê Yekem bû.', 'Verdun Savaşı 21 Şubat 1916''da başladı ve 18 Aralık 1916''ya kadar sürdü. Bu savaş, Birinci Dünya Savaşı''nın en uzun ve en kanlı savaşlarından biriydi.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Battle_of_Verdun', NULL, 'https://en.wikipedia.org/wiki/Battle_of_Verdun', 'approved', 'Kurmancî', 1, now()),
('94e21bc2-eb03-53d7-9b4b-9fa0e667a6b9', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan şerê deryayî di 1805''an de qewimî û tê de Horatio Nelsonî artêşa deryayî ya Brîtanî bi rê ve bir?', 'Şerê Jutlandê', 'Şerê Lepantoyê', 'Şerê Trafalgarê', 'Şerê Midwayê', 'C', 'Şerê Trafalgarê di 21''ê çiriya pêşîn a 1805''an de qewimî. Di vî şerî de artêşa deryayî ya Brîtanî bi fermandariya Admiral Horatio Nelson li dijî artêşa deryayî ya Fransa û Spanyayê bi ser ket, lê ew bi xwe di şer de hate kuştin.', 'Şerê Trafalgarê di 21''ê çiriya pêşîn a 1805''an de qewimî. Di vî şerî de artêşa deryayî ya Brîtanî bi fermandariya Admiral Horatio Nelson li dijî artêşa deryayî ya Fransa û Spanyayê bi ser ket, lê ew bi xwe di şer de hate kuştin.', 'Trafalgar Savaşı 21 Ekim 1805''te gerçekleşti. Bu savaşta Amiral Horatio Nelson liderliğindeki İngiliz donanması, Fransa ve İspanya donanmalarına karşı zafer kazandı, ancak Nelson savaşta öldürüldü.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Battle_of_Trafalgar', NULL, 'https://en.wikipedia.org/wiki/Battle_of_Trafalgar', 'approved', 'Kurmancî', 1, now()),
('34fe0598-4cda-54b5-a762-68c10acb0d80', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Şerê Jutlandê di navbera kîjan hêzên deryayî de qewimî?', 'DYA û Japon', 'Fransa û Îtalya', 'Rûsya û Osmanî', 'Brîtanya û Almanya', 'D', 'Şerê Jutlandê di 31''ê gulanê û 1''ê hezîrana 1916''an de di navbera artêşa deryayî ya Brîtanî (Royal Navy) û artêşa deryayî ya Alman (Kaiserliche Marine) de qewimî. Ev yek ji mezintirîn şerên deryayî yên Şerê Cîhanê yê Yekem bû.', 'Şerê Jutlandê di 31''ê gulanê û 1''ê hezîrana 1916''an de di navbera artêşa deryayî ya Brîtanî (Royal Navy) û artêşa deryayî ya Alman (Kaiserliche Marine) de qewimî. Ev yek ji mezintirîn şerên deryayî yên Şerê Cîhanê yê Yekem bû.', 'Jutland Savaşı, 31 Mayıs ve 1 Haziran 1916''da İngiliz Kraliyet Donanması ile Alman İmparatorluk Donanması arasında gerçekleşti. Bu, Birinci Dünya Savaşı''nın en büyük deniz savaşlarından biriydi.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Battle_of_Jutland', NULL, 'https://en.wikipedia.org/wiki/Battle_of_Jutland', 'approved', 'Kurmancî', 1, now()),
('82f9cbcb-c79d-5be4-96e8-1a0953902b94', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Şerê Cîhanê yê Duyem di kîjan salê de bi dawî bû?', '1944', '1946', '1945', '1947', 'C', 'Şerê Cîhanê yê Duyem di 2''ê îlona 1945''an de bi dawî bû, piştî ku Japonya teslîm bû. Ev teslîmbûn piştî bombekirina atomî ya Hiroşîma û Nagasakiyê pêk hat.', 'Şerê Cîhanê yê Duyem di 2''ê îlona 1945''an de bi dawî bû, piştî ku Japonya teslîm bû. Ev teslîmbûn piştî bombekirina atomî ya Hiroşîma û Nagasakiyê pêk hat.', 'İkinci Dünya Savaşı, Japonya''nın teslim olmasının ardından 2 Eylül 1945''te sona erdi. Bu teslimiyet, Hiroşima ve Nagazaki''ye atılan atom bombalarından sonra gerçekleşti.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/End_of_World_War_II_in_Asia', NULL, 'https://en.wikipedia.org/wiki/End_of_World_War_II_in_Asia', 'approved', 'Kurmancî', 1, now()),
('1ed0c7de-9dd9-5c4c-8605-9e3d753c6ea4', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan şer di navbera 1950 û 1953''an de li Nîvgirava Koreyê qewimî?', 'Şerê Koreyê', 'Şerê Viyetnamê', 'Şerê Çîn-Japonê', 'Şerê Rûs-Japonê', 'A', 'Şerê Koreyê di 25''ê hezîrana 1950''an de dest pê kir û di 27''ê tîrmeha 1953''an de bi agirbestê bi dawî bû. Ev şer di navbera Koreya Bakur (bi piştgiriya Çînê û Yekîtiya Sovyetê) û Koreya Başûr (bi piştgiriya DYA û Neteweyên Yekbûyî) de qewimî.', 'Şerê Koreyê di 25''ê hezîrana 1950''an de dest pê kir û di 27''ê tîrmeha 1953''an de bi agirbestê bi dawî bû. Ev şer di navbera Koreya Bakur (bi piştgiriya Çînê û Yekîtiya Sovyetê) û Koreya Başûr (bi piştgiriya DYA û Neteweyên Yekbûyî) de qewimî.', 'Kore Savaşı 25 Haziran 1950''de başladı ve 27 Temmuz 1953''te ateşkesle sona erdi. Bu savaş, Kuzey Kore (Çin ve Sovyetler Birliği''nin desteğiyle) ile Güney Kore (ABD ve Birleşmiş Milletler''in desteğiyle) arasında gerçekleşti.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Korean_War', NULL, 'https://en.wikipedia.org/wiki/Korean_War', 'approved', 'Kurmancî', 1, now()),
('f5c406da-e24b-53f2-a83f-d9cbcc130038', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Şerê Viyetnamê di kîjan salê de bi dawî bû?', '1973', '1975', '1974', '1976', 'B', 'Şerê Viyetnamê di 30''ê nîsana 1975''an de bi dawî bû, dema ku hêzên komunîst ên Viyetnama Bakur Saigon (paytexta Viyetnama Başûr) dagir kir. Ev bûyer dawiya Şerê Viyetnamê bû.', 'Şerê Viyetnamê di 30''ê nîsana 1975''an de bi dawî bû, dema ku hêzên komunîst ên Viyetnama Bakur Saigon (paytexta Viyetnama Başûr) dagir kir. Ev bûyer dawiya Şerê Viyetnamê bû.', 'Vietnam Savaşı, Kuzey Vietnam Komünist güçlerinin Saigon''u (Güney Vietnam''ın başkenti) ele geçirmesiyle 30 Nisan 1975''te sona erdi. Bu olay Vietnam Savaşı''nın sonu oldu.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Fall_of_Saigon', NULL, 'https://en.wikipedia.org/wiki/Fall_of_Saigon', 'approved', 'Kurmancî', 1, now()),
('ff4b46c1-8737-529d-a4a4-72dd9760425b', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Li gorî kevneşopiya romayiyan, kîjan bajar di sala 753''yan a berî zayînê de hat avakirin?', 'Atîna', 'Sparta', 'Korînt', 'Roma', 'D', 'Li gorî kevneşopiya romayiyan, Romulus û Remusî di sala 753''yan a berî zayînê de bajarê Romayê damezrand. Ev dîrok ji hêla dîroknasên kevnar ve hat qebûlkirin.', 'Li gorî kevneşopiya romayiyan, Romulus û Remusî di sala 753''yan a berî zayînê de bajarê Romayê damezrand. Ev dîrok ji hêla dîroknasên kevnar ve hat qebûlkirin.', 'Roma geleneğine göre Romulus ve Remus, MÖ 753 yılında Roma şehrini kurdular. Bu tarih antik tarihçiler tarafından kabul edilmiştir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Rome', NULL, 'https://en.wikipedia.org/wiki/Rome', 'approved', 'Kurmancî', 1, now()),
('3decfebb-2f2f-55e2-a01c-11a09ce9c43c', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan kesayetî wek yekem împaratorê Romayê tê zanîn?', 'Jules Cesar', 'Neron', 'Augustus', 'Kaligula', 'C', 'Augustusê ku bi navê Octavian jî dihat naskirin, di sala 27''an a berî zayînê de bû yekem împaratorê Romayê. Ew piştî şerê navxweyî yê ku bi mirina Jules Cesar re dest pê kir, desthilatdar bû.', 'Augustusê ku bi navê Octavian jî dihat naskirin, di sala 27''an a berî zayînê de bû yekem împaratorê Romayê. Ew piştî şerê navxweyî yê ku bi mirina Jules Cesar re dest pê kir, desthilatdar bû.', 'Octavian olarak da bilinen Augustus, MÖ 27''de Roma''nın ilk imparatoru oldu. Jül Sezar''ın ölümüyle başlayan iç savaştan sonra iktidara geldi.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Augustus', NULL, 'https://en.wikipedia.org/wiki/Augustus', 'approved', 'Kurmancî', 1, now()),
('e281773d-8952-568f-b228-43a47e55d602', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan kesayetî wek "Bavê Dîrokê" tê zanîn?', 'Homeros', 'Thukydides', 'Herodotos', 'Hesiodos', 'C', 'Herodotos ji ber pirtûka xwe ya "Dîrok" wek Bavê Dîrokê tê zanîn. Ew di sedsala 5''an a berî zayînê de jiyaye û wî dîroka şerên Yewnan û Persan nivîsandiye.', 'Herodotos ji ber pirtûka xwe ya "Dîrok" wek Bavê Dîrokê tê zanîn. Ew di sedsala 5''an a berî zayînê de jiyaye û wî dîroka şerên Yewnan û Persan nivîsandiye.', 'Herodotos, "Tarih" adlı eseri nedeniyle Tarihin Babası olarak bilinir. MÖ 5. yüzyılda yaşamış ve Yunan-Pers savaşlarının tarihini yazmıştır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Herodotus', NULL, 'https://en.wikipedia.org/wiki/Herodotus', 'approved', 'Kurmancî', 1, now()),
('b1d44fdf-f613-5076-a8cb-b13456dad2ca', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan împaratorê Romayê dîwarê ku bi navê wî tê zanîn li Brîtanyayê ava kir?', 'Trajan', 'Marcus Aurelius', 'Septimius Severus', 'Hadrian', 'D', 'Împarator Hadrianî di sala 122''an de dîwarê ku bi navê wî tê zanîn li bakurê Brîtanyayê ava kir. Ev dîwar ji bo parastina ji êrîşên gelên bakur hate çêkirin.', 'Împarator Hadrianî di sala 122''an de dîwarê ku bi navê wî tê zanîn li bakurê Brîtanyayê ava kir. Ev dîwar ji bo parastina ji êrîşên gelên bakur hate çêkirin.', 'İmparator Hadrian, 122 yılında kendi adıyla anılan duvarı Britanya''nın kuzeyinde inşa ettirdi. Bu duvar, kuzeydeki halkların saldırılarına karşı korunmak için yapıldı.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Hadrian%27s_Wall', NULL, 'https://en.wikipedia.org/wiki/Hadrian%27s_Wall', 'approved', 'Kurmancî', 1, now()),
('f33bdd73-d12d-544c-8c61-bb056f008f0f', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di kîjan salê de Jules Cesar ji aliyê senatoran ve hate kuştin?', '44 berî zayînê', '49 berî zayînê', '27 berî zayînê', '31 berî zayînê', 'A', 'Jules Cesar di 15''ê adara sala 44''an a berî zayînê de ji aliyê komeke senatoran ve hate kuştin. Ev bûyer wek "Ides of March" tê zanîn.', 'Jules Cesar di 15''ê adara sala 44''an a berî zayînê de ji aliyê komeke senatoran ve hate kuştin. Ev bûyer wek "Ides of March" tê zanîn.', 'Jül Sezar, MÖ 44 yılının 15 Mart''ında bir grup senatör tarafından öldürüldü. Bu olay "Mart İdesi" olarak bilinir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Assassination_of_Julius_Caesar', NULL, 'https://en.wikipedia.org/wiki/Assassination_of_Julius_Caesar', 'approved', 'Kurmancî', 1, now()),
('067d1d00-08e2-5457-90fd-70393ddb3aa8', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di kîjan salê de Împaratoriya Romayê ya Rojava bi dawî bû?', '410', '455', '507', '476', 'D', 'Împaratoriya Romayê ya Rojava di sala 476''an de bi dawî bû. Ev dema ku Odoacerî împaratorê dawî Romulus Augustus ji text xist, pêk hat.', 'Împaratoriya Romayê ya Rojava di sala 476''an de bi dawî bû. Ev dema ku Odoacerî împaratorê dawî Romulus Augustus ji text xist, pêk hat.', 'Batı Roma İmparatorluğu, 476 yılında sona erdi. Bu, Odoacer''ın son imparator Romulus Augustus''u tahttan indirdiği dönemdir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Romulus_Augustulus', NULL, 'https://en.wikipedia.org/wiki/Romulus_Augustulus', 'approved', 'Kurmancî', 1, now()),
('e7209b84-ecbd-5a38-ab04-d20819015efe', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan kesayetî wek "Bavê Tibê" tê zanîn?', 'Galen', 'Aristoteles', 'Hippokrates', 'Pythagoras', 'C', 'Hippokrates wek Bavê Tibê tê zanîn ji ber ku ew yekem kes bû ku wî tib wek zanistek serbixwe damezrand. Ew di sedsala 5''an a berî zayînê de jiyaye.', 'Hippokrates wek Bavê Tibê tê zanîn ji ber ku ew yekem kes bû ku wî tib wek zanistek serbixwe damezrand. Ew di sedsala 5''an a berî zayînê de jiyaye.', 'Hipokrat, tıbbı bağımsız bir bilim olarak kuran ilk kişi olduğu için Tıbbın Babası olarak bilinir. MÖ 5. yüzyılda yaşamıştır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Hippocrates', NULL, 'https://en.wikipedia.org/wiki/Hippocrates', 'approved', 'Kurmancî', 1, now()),
('0f1a8f0f-e5ef-5b42-b16a-2820b64fbb9b', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan şerê navdar di sala 216''an a berî zayînê de qewimî û tê de Hannibalî artêşa Romayê têk bir?', 'Şerê Zamayê', 'Şerê Cannaeyê', 'Şerê Trebiayê', 'Şerê Trasimeneyê', 'B', 'Şerê Cannaeyê di 2''ê tebaxa sala 216''an a berî zayînê de qewimî. Hannibalî bi taktîka xwe ya dorpêçkirinê artêşa Romayê têk bir.', 'Şerê Cannaeyê di 2''ê tebaxa sala 216''an a berî zayînê de qewimî. Hannibalî bi taktîka xwe ya dorpêçkirinê artêşa Romayê têk bir.', 'Cannae Savaşı, MÖ 216 yılının 2 Ağustos''unda yapıldı. Hannibal, kuşatma taktiğiyle Roma ordusunu yendi.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Battle_of_Cannae', NULL, 'https://en.wikipedia.org/wiki/Battle_of_Cannae', 'approved', 'Kurmancî', 1, now()),
('45ddcd6a-0fdc-5eb9-81a0-4d9300415f6a', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan kesayetî wek "Bavê Komediyê" tê zanîn?', 'Sophokles', 'Aristophanes', 'Euripides', 'Aiskhylos', 'B', 'Aristophanes wek Bavê Komediyê tê zanîn. Ew di sedsala 5''an a berî zayînê de li Atînayê jiyaye û wî komediyên navdar nivîsandine.', 'Aristophanes wek Bavê Komediyê tê zanîn. Ew di sedsala 5''an a berî zayînê de li Atînayê jiyaye û wî komediyên navdar nivîsandine.', 'Aristofanes, Komedinin Babası olarak bilinir. MÖ 5. yüzyılda Atina''da ünlü komediler yazmıştır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Aristophanes', NULL, 'https://en.wikipedia.org/wiki/Aristophanes', 'approved', 'Kurmancî', 1, now()),
('cb036808-d1aa-5988-af85-1a6dff5558d8', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di serdema keşfên deryayî de kîjan welatê Ewropayê yekem bû ku rêya deryayî ya Hindistanê dît?', 'Portûgal', 'Spanya', 'Fransa', 'Îngilîstan', 'A', 'Portûgalê, bi serokatiya keşfvanên wekî Vasco da Gama, yekem car rêya deryayî ya Hindistanê di sala 1498''an de dît. Ev yek destpêka serdestiya Portûgalê li ser bazirganiya deryayî bû.', 'Portûgalê, bi serokatiya keşfvanên wekî Vasco da Gama, yekem car rêya deryayî ya Hindistanê di sala 1498''an de dît. Ev yek destpêka serdestiya Portûgalê li ser bazirganiya deryayî bû.', 'Portekiz, Vasco da Gama gibi kaşiflerin önderliğinde Hindistan''a giden deniz yolunu ilk kez 1498''de buldu. Bu, Portekiz''in deniz ticaretindeki üstünlüğünün başlangıcı oldu.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Portuguese_discoveries', NULL, 'https://en.wikipedia.org/wiki/Portuguese_discoveries', 'approved', 'Kurmancî', 1, now()),
('1f651bc7-4763-5858-9281-2aa809ae864c', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di serdema keşfên deryayî de kîjan keşfvanê Portûgalî yekem car derbasî Kapa Hêviya Baş bû?', 'Vasco da Gama', 'Pedro Álvares Cabral', 'Diogo Cão', 'Bartolomeu Dias', 'D', 'Bartolomeu Dias di sala 1488''an de yekem car derbasî Kapa Hêviya Baş bû. Vê yekê rê ji bo rêya deryayî ya Hindistanê vekir.', 'Bartolomeu Dias di sala 1488''an de yekem car derbasî Kapa Hêviya Baş bû. Vê yekê rê ji bo rêya deryayî ya Hindistanê vekir.', 'Bartolomeu Dias, 1488''de Ümit Burnu''nu ilk kez geçti. Bu, Hindistan''a giden deniz yolunun önünü açtı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Bartolomeu_Dias', NULL, 'https://en.wikipedia.org/wiki/Bartolomeu_Dias', 'approved', 'Kurmancî', 1, now()),
('2a2d0701-532d-5866-aa07-fc4ba357c0c7', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di sala 1519''an de kîjan keşfvanî dest bi sefera yekem a li dora dinyayê kir?', 'Hernán Cortés', 'Ferdinand Magellan', 'Francisco Pizarro', 'Juan Sebastián Elcano', 'B', 'Ferdinand Magellanî di sala 1519''an de dest bi sefera yekem a li dora dinyayê kir. Her çend ew di rê de mir jî, ekîba wî di sala 1522''an de sefer bi dawî anî.', 'Ferdinand Magellanî di sala 1519''an de dest bi sefera yekem a li dora dinyayê kir. Her çend ew di rê de mir jî, ekîba wî di sala 1522''an de sefer bi dawî anî.', 'Ferdinand Macellan, 1519''da dünyanın ilk çevresini dolaşma seferine başladı. Yolda ölmesine rağmen, ekibi seferi 1522''de tamamladı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Ferdinand_Magellan', NULL, 'https://en.wikipedia.org/wiki/Ferdinand_Magellan', 'approved', 'Kurmancî', 1, now()),
('38b58913-46d2-5e3a-a126-7251ac80884c', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di sala 1519''an de kîjan keşfvanê spanî dest bi dagirkirina Meksîkayê kir?', 'Francisco Pizarro', 'Hernán Cortés', 'Vasco Núñez de Balboa', 'Pedro de Valdivia', 'B', 'Hernán Cortés di sala 1519''an de dest bi dagirkirina Împaratoriya Aztekan a li Meksîkayê kir. Ev yek bû sedema hilweşandina Împaratoriya Aztekan.', 'Hernán Cortés di sala 1519''an de dest bi dagirkirina Împaratoriya Aztekan a li Meksîkayê kir. Ev yek bû sedema hilweşandina Împaratoriya Aztekan.', 'Hernán Cortés, 1519''da Meksika''daki Aztek İmparatorluğu''nun fethine başladı. Bu, Aztek İmparatorluğu''nun yıkılmasına neden oldu.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Hern%C3%A1n_Cort%C3%A9s', NULL, 'https://en.wikipedia.org/wiki/Hern%C3%A1n_Cort%C3%A9s', 'approved', 'Kurmancî', 1, now()),
('e2aa7f7e-e696-5e12-b230-0a822d6f792f', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan kesî makîneya hilmê ya pêşkeftî di sala 1769''an de çêkir?', 'Richard Arkwright', 'Samuel Crompton', 'Edmund Cartwright', 'James Watt', 'D', 'James Watt di 1769''an de makîneya hilmê ya pêşkeftî çêkir, ku ji bo kargehan û veguhestinê enerjiyê peyda kir û Şoreşa Pîşesaziyê zûtir kir.', 'James Watt di 1769''an de makîneya hilmê ya pêşkeftî çêkir, ku ji bo kargehan û veguhestinê enerjiyê peyda kir û Şoreşa Pîşesaziyê zûtir kir.', 'James Watt, 1769''da fabrikalar ve ulaşım için enerji sağlayan ve Sanayi Devrimi''ni hızlandıran gelişmiş buhar makinesini yaptı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/James_Watt', NULL, 'https://en.wikipedia.org/wiki/James_Watt', 'approved', 'Kurmancî', 1, now()),
('549ea3f4-560c-5c51-a1cc-a8b8705ebec7', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di Şoreşa Pîşesaziyê de kîjan bûyer bû sedema zêdebûna bajaran?', 'Zêdebûna çandiniyê', 'Koçberiya gundiyan bo kargehan', 'Kêmbûna nifûsê', 'Pêşketina karwanan', 'B', 'Ji ber ku kargeh li bajaran hatin avakirin, gelek gundî ji bo kar û jiyanek baştir koçî bajaran kirin, ev jî bû sedema zêdebûna nifûsa bajaran.', 'Ji ber ku kargeh li bajaran hatin avakirin, gelek gundî ji bo kar û jiyanek baştir koçî bajaran kirin, ev jî bû sedema zêdebûna nifûsa bajaran.', 'Fabrikalar şehirlerde kurulduğu için birçok köylü iş ve daha iyi bir yaşam için şehirlere göç etti, bu da şehir nüfusunun artmasına neden oldu.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Urbanization', NULL, 'https://en.wikipedia.org/wiki/Urbanization', 'approved', 'Kurmancî', 1, now()),
('53dd191e-7e0a-52c0-bd91-c49ed2f5fae6', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Makîneya hilmê pêşî ji bo çi di pîşesaziyê de hat bikaranîn?', 'Ji bo pompekirina avê ji kanan', 'Ji bo rêsandina tekstîlê', 'Ji bo veguhastina trênê', 'Ji bo çapkirina rojnameyan', 'A', 'Bikaranîna yekem a girîng a makîneya hilmê pompekirina avê ji kanên komirê bû.', 'Bikaranîna yekem a girîng a makîneya hilmê pompekirina avê ji kanên komirê bû.', 'Newcomen ve ardından Watt makinelerinin ilk önemli sanayi kullanımı kömür madenlerinden su pompalamaktı; tekstil ve ulaşım sonra geldi.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Textile_industry', NULL, 'https://en.wikipedia.org/wiki/Textile_industry', 'approved', 'Kurmancî', 1, now()),
('86e32dd9-c9b8-5152-9742-186fbddcdc54', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan pêvajo para karê destan di hilberînê de kêm kir?', 'Pîşesaziya makîneyan', 'Pîşesaziya çandiniyê', 'Pîşesaziya keştiyan', 'Pîşesaziya madenê', 'A', 'Makînebûnê hilberîn bileztir û erzantir kir, ji ber wê para karê destan kêm bû; lê pîşeyên destan bi temamî winda nebûn.', 'Makînebûnê hilberîn bileztir û erzantir kir, ji ber wê para karê destan kêm bû; lê pîşeyên destan bi temamî winda nebûn.', 'Makineleşme üretimi hızlandırıp ucuzlattığı için el işçiliğinin payı azaldı; el zanaatları tümüyle ortadan kalkmadı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Industrialisation', NULL, 'https://en.wikipedia.org/wiki/Industrialisation', 'approved', 'Kurmancî', 1, now()),
('b8f1eab6-e70e-5728-8359-f93cc234f770', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan wesayîtê di sedsala 19an de veguhastina bejahiyê guhert?', 'Balafir', 'Tirimpêl', 'Keştiya bazirganiyê', 'Trên', 'D', 'Rêhesin û lokomotîfa hilmê di sedsala 19an de veguhastina bejahiyê guhert.', 'Rêhesin û lokomotîfa hilmê di sedsala 19an de veguhastina bejahiyê guhert.', 'Demiryolu ve buharlı lokomotif 19. yüzyılda kara taşımacılığını dönüştürdü; otomobil ve uçak 20. yüzyıl gelişmeleridir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/History_of_rail_transport', NULL, 'https://en.wikipedia.org/wiki/History_of_rail_transport', 'approved', 'Kurmancî', 1, now()),
('4e908073-e1c3-514b-ae24-cb4680160fae', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan bûyer di sala 1811''an de li Brîtanyayê qewimî û tê de karkeran makîne hilweşandin?', 'Serhildana Chartîstan', 'Serhildana Luddîtan', 'Serhildana Swing', 'Serhildana Peterloo', 'B', 'Serhildana Luddîtan di sala 1811''an de li Brîtanyayê qewimî, karkerên ku ji ber makîneyan karê xwe winda kiribûn, dest bi hilweşandina makîneyan kirin.', 'Serhildana Luddîtan di sala 1811''an de li Brîtanyayê qewimî, karkerên ku ji ber makîneyan karê xwe winda kiribûn, dest bi hilweşandina makîneyan kirin.', 'Luddite İsyanı 1811''de Britanya''da meydana geldi; makineler yüzünden işlerini kaybeden işçiler makineleri tahrip etmeye başladı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Luddite', NULL, 'https://en.wikipedia.org/wiki/Luddite', 'approved', 'Kurmancî', 1, now()),
('b442bee1-6431-5a97-a3e6-af23a009a5bc', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan kesî di sala 1776''an de pirtûka "Lêkolîna li ser Dewlemendiya Neteweyan" nivîsand?', 'Adam Smith', 'David Ricardo', 'Karl Marx', 'John Stuart Mill', 'A', 'Adam Smith di 1776''an de pirtûka "Lêkolîna li ser Dewlemendiya Neteweyan" nivîsand, ku bingeha aboriya klasîk avêt û bandor li ser Şoreşa Pîşesaziyê kir.', 'Adam Smith di 1776''an de pirtûka "Lêkolîna li ser Dewlemendiya Neteweyan" nivîsand, ku bingeha aboriya klasîk avêt û bandor li ser Şoreşa Pîşesaziyê kir.', 'Adam Smith, 1776''da "Ulusların Zenginliği" kitabını yazdı; bu kitap klasik ekonominin temelini attı ve Sanayi Devrimi''ni etkiledi.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Wealth_of_Nations', NULL, 'https://en.wikipedia.org/wiki/The_Wealth_of_Nations', 'approved', 'Kurmancî', 1, now()),
('4ed30e8b-0683-5d3f-b502-9ba5ab46e89b', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan bajarê Brîtanyayê di Şoreşa Pîşesaziyê de wekî navenda tekstîlê dihat zanîn?', 'Londra', 'Manchester', 'Edinburgh', 'Dublin', 'B', 'Manchester di Şoreşa Pîşesaziyê de navenda tekstîlê bû, ji ber ku li wir gelek kargehên ristin û tevnê hatin avakirin.', 'Manchester di Şoreşa Pîşesaziyê de navenda tekstîlê bû, ji ber ku li wir gelek kargehên ristin û tevnê hatin avakirin.', 'Manchester, Sanayi Devrimi''nde tekstilin merkeziydi çünkü orada birçok eğirme ve dokuma fabrikası kuruldu.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Manchester', NULL, 'https://en.wikipedia.org/wiki/Manchester', 'approved', 'Kurmancî', 1, now()),
('37558c77-fa11-5f2a-8701-8b7813e6387c', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan kesî di sala 1793''an de makîneya pembû ya ku ji bo veqetandina pembû dihat bikaranîn îcad kir?', 'Eli Whitney', 'Samuel Slater', 'Francis Cabot Lowell', 'John Kay', 'A', 'Eli Whitney di 1793''an de makîneya pembû îcad kir, ku ji bo veqetandina pembû ji tovê wî dihat bikaranîn, ev jî hilberîna pembû zêde kir.', 'Eli Whitney di 1793''an de makîneya pembû îcad kir, ku ji bo veqetandina pembû ji tovê wî dihat bikaranîn, ev jî hilberîna pembû zêde kir.', 'Eli Whitney, 1793''te pamuğu tohumundan ayırmak için kullanılan çırçır makinesini icat etti; bu da pamuk üretimini artırdı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Cotton_gin', NULL, 'https://en.wikipedia.org/wiki/Cotton_gin', 'approved', 'Kurmancî', 1, now()),
('cd8e04e8-ba34-5c95-951f-cbb4d74b8d10', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan rêbaz di lêkolîna dîroka devkî de herî zêde tê bikaranîn?', 'Analîza statîstîkî', 'Kolana arkeolojîk', 'Ceribandina laboratûwarê', 'Hevpeyvîna bi şahidan re', 'D', 'Hevpeyvîna bi kesên ku bûyeran dîtine an jî di wan de cih girtine re, bingeha dîroka devkî ye; ev rêbaz agahiyên kesane û yekser peyda dike.', 'Hevpeyvîna bi kesên ku bûyeran dîtine an jî di wan de cih girtine re, bingeha dîroka devkî ye; ev rêbaz agahiyên kesane û yekser peyda dike.', 'Olayları gören veya bunlara katılan kişilerle yapılan görüşmeler sözlü tarihin temelini oluşturur; bu yöntem kişisel ve doğrudan bilgiler sağlar.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Oral_history', NULL, 'https://en.wikipedia.org/wiki/Oral_history', 'approved', 'Kurmancî', 1, now()),
('a784a622-602e-574a-b74f-26de388383d3', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di dîroka devkî de, kîjan têgeh pêvajoya ku vegotin di nav nifşan de cuda dibe, rave dike?', 'Veguherîna çîrokê', 'Transkrîpsiyon', 'Refleksîvîte', 'Arşîvkirin', 'A', 'Veguherîna çîrokê tê wateya ku çîrok bi demê re û di nav nifşan de diguhere; ev jî ji bo dîroka devkî xaleke girîng e ku divê were hesab kirin.', 'Veguherîna çîrokê tê wateya ku çîrok bi demê re û di nav nifşan de diguhere; ev jî ji bo dîroka devkî xaleke girîng e ku divê were hesab kirin.', 'Hikayenin dönüşümü, hikayenin zamanla ve nesiller arasında değişmesi anlamına gelir; bu da sözlü tarih için dikkate alınması gereken önemli bir noktadır.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Oral_history', NULL, 'https://en.wikipedia.org/wiki/Oral_history', 'approved', 'Kurmancî', 1, now()),
('f1950d2f-1d2c-5df5-b8e2-2e8e07faeba7', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di dîroka devkî de, kîjan pirsgirêk ji ber ziman û wergeran derdikeve?', 'Zêdebûna agahiyan di arşîvan de', 'Kêmasiya şahidan di gundan de', 'Zêdebûna belgeyan di pirtûkxaneyan de', 'Wendabûna wateyê di wergerê de', 'D', 'Dema ku dîroka devkî ji zimanekî bo zimanekî din tê wergerandin, dibe ku wateya resen a çîrokbêj winda bibe an jî biguhere, ev jî rastbûna agahiyan kêm dike.', 'Dema ku dîroka devkî ji zimanekî bo zimanekî din tê wergerandin, dibe ku wateya resen a çîrokbêj winda bibe an jî biguhere, ev jî rastbûna agahiyan kêm dike.', 'Sözlü tarih bir dilden başka bir dile çevrildiğinde, anlatıcının özgün anlamı kaybolabilir veya değişebilir; bu da bilgilerin doğruluğunu azaltır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Oral_history', NULL, 'https://en.wikipedia.org/wiki/Oral_history', 'approved', 'Kurmancî', 1, now()),
('710c350e-40db-59d5-a762-41f2292415d0', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di lêkolîna dîroka devkî de, kîjan pirs ji bo berhevkirina agahiyan herî bi bandor in?', 'Pirsên girtî yên ku bersiva erê an na dixwazin', 'Pirsên ku tenê bi dîrokên rast re têkildar in', 'Pirsên vekirî yên ku çîrokbêj azad dihêlin', 'Pirsên ku bi zanistiya siyasî ve girêdayî ne', 'C', 'Pirsên vekirî dihêlin ku çîrokbêj bi serbestî biaxive û agahiyên nediyar û kûr derkevin holê, ev jî ji bo dîroka devkî zêdetir bikêr e.', 'Pirsên vekirî dihêlin ku çîrokbêj bi serbestî biaxive û agahiyên nediyar û kûr derkevin holê, ev jî ji bo dîroka devkî zêdetir bikêr e.', 'Açık uçlu sorular anlatıcının serbestçe konuşmasını sağlar ve beklenmedik, derin bilgilerin ortaya çıkmasına olanak tanır; bu da sözlü tarih için daha faydalıdır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Oral_history', NULL, 'https://en.wikipedia.org/wiki/Oral_history', 'approved', 'Kurmancî', 1, now()),
('0ac92989-eaac-5f62-8675-2bd7d4afc3f3', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan rêbaz rastbûna agahiyên dîroka devkî zêde dike?', 'Berhevkirina gelek çavkaniyan', 'Bikaranîna yek çavkaniyê', 'Tenê guhdarîkirina çîrokbêj', 'Nivîsandina bêyî kontrolê', 'A', 'Berhevkirina agahiyan ji gelek çavkaniyan û berhevdana wan bi hev re, rastbûna dîroka devkî zêde dike û alîkariya tespîtkirina şaşbîriyan dike.', 'Berhevkirina agahiyan ji gelek çavkaniyan û berhevdana wan bi hev re, rastbûna dîroka devkî zêde dike û alîkariya tespîtkirina şaşbîriyan dike.', 'Birçok kaynaktan bilgi toplamak ve bunları birbiriyle karşılaştırmak sözlü tarihin doğruluğunu artırır ve yanlış hatıraların tespit edilmesine yardımcı olur.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Oral_history', NULL, 'https://en.wikipedia.org/wiki/Oral_history', 'approved', 'Kurmancî', 1, now()),
('0b3b9e14-98c8-59d6-8d2a-8bd95ff6b7fb', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Tora bazirganiyê ya Riya Hevirmêşê bi piranî bi kîjan xanedanê ve tê girêdan?', 'Xanedana Ming', 'Xanedana Han', 'Xanedana Qing', 'Xanedana Tang', 'B', 'Tora birêkûpêk a Riya Hevirmêşê di dema xanedana Han de ava bû.', 'Tora birêkûpêk a Riya Hevirmêşê di dema xanedana Han de ava bû.', 'Organize İpek Yolu ağı MÖ 2. yüzyılda Han hanedanı döneminde kuruldu; Tang döneminde yeniden canlandı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', 'approved', 'Kurmancî', 1, now()),
('ad0433a8-baa8-5443-b73f-25aebad68894', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Ewlehiya Riya Hevirmêşê di kîjan serdemê de bi "Pax Mongolica" ve zêde bû?', 'Serdema Kevir', 'Serdema Bronz', 'Serdema Mongol', 'Serdema Nûjen', 'C', 'Di serdema serdestiya Mongolan de ewlehiya rê zêde bû; jê re Pax Mongolica tê gotin.', 'Di serdema serdestiya Mongolan de ewlehiya rê zêde bû; jê re Pax Mongolica tê gotin.', 'Moğol egemenliği döneminde (13.-14. yy) tek bir siyasal çatı altında yol güvenliği arttı; buna Pax Mongolica denir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', 'approved', 'Kurmancî', 1, now()),
('b1b8da44-4a25-51ff-bfd9-dea26534d63c', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan welat wekî destpêka Riya Hevirmêşê tê zanîn?', 'Hindistan', 'Misir', 'Yewnanistan', 'Çîn', 'D', 'Çîn wekî destpêka Riya Hevirmêşê tê zanîn, ji ber ku ew navenda herî kevn a bazirganiya hevrîşimê bû.', 'Çîn wekî destpêka Riya Hevirmêşê tê zanîn, ji ber ku ew navenda herî kevn a bazirganiya hevrîşimê bû.', 'Çin, İpek Yolu''nun başlangıcı olarak bilinir çünkü ipek ticaretinin en eski geçiş noktasıydı.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', 'approved', 'Kurmancî', 1, now()),
('17f69e3a-db8d-5c4b-89f7-19e35fc0cd7d', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Riya Hevirmêşê navê xwe ji kîjan berhemê digire?', 'Zêr', 'Hevrîşim', 'Qehwe', 'Çerm', 'B', 'Rê navê xwe ji hevirmêşê digire ku ji Çînê ber bi rojava ve dihat veguhastin.', 'Rê navê xwe ji hevirmêşê digire ku ji Çînê ber bi rojava ve dihat veguhastin.', 'Yol adını Çin''den batıya taşınan ipekten alır. Yolda kâğıt, baharat, cam ve at gibi birçok mal da taşındı.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', 'approved', 'Kurmancî', 1, now()),
('215e15bc-b601-529a-b139-3f5ceecbfe6b', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan bajar yek ji navendên sereke yên Riya Hevrîşimê bû?', 'Parîs', 'Semerkand', 'London', 'Berlîn', 'B', 'Bajarên wek Semerkand, Buxara û Merw ji navendên sereke yên Riya Hevrîşimê bûn.', 'Bajarên wek Semerkand, Buxara û Merw ji navendên sereke yên Riya Hevrîşimê bûn.', 'Semerkant, Buhara ve Merv gibi Orta Asya şehirleri İpek Yolu''nun başlıca merkezlerindendi.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', 'approved', 'Kurmancî', 1, now()),
('bbd5e4c2-e35b-54e3-b83e-3ff9d14bb42d', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di Riya Îpekê de kîjan rêbaza veguhestinê dihat bikaranîn?', 'Karwanên deveyan', 'Trenên elektrîkê', 'Balafirên bazirganî', 'Keştiyên buharê', 'A', 'Karwanên deveyan di Riya Îpekê de dihatin bikaranîn, ji ber ku deve li çolê bi hêsanî dimeşiyan û tişt hildigirtin.', 'Karwanên deveyan di Riya Îpekê de dihatin bikaranîn, ji ber ku deve li çolê bi hêsanî dimeşiyan û tişt hildigirtin.', 'İpek Yolu''nda deve kervanları kullanılıyordu çünkü develer çölde kolayca yürüyor ve yük taşıyorlardı.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', 'approved', 'Kurmancî', 1, now()),
('e78fd90d-226f-5460-9d05-3bfed4e9d9bd', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan kesayetî bi Riya Îpekê re têkildar e?', 'Julius Caesar', 'Napoleon', 'Îskenderê Mezin', 'Marko Polo', 'D', 'Marko Polo bi Riya Îpekê re têkildar e, ji ber ku ew bi wê rêyê çû Çînê û seferên xwe nivîsand.', 'Marko Polo bi Riya Îpekê re têkildar e, ji ber ku ew bi wê rêyê çû Çînê û seferên xwe nivîsand.', 'Marko Polo İpek Yolu ile ilişkilidir çünkü o yolla Çin''e gitti ve seyahatlerini yazdı.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Marco_Polo', NULL, 'https://en.wikipedia.org/wiki/Marco_Polo', 'approved', 'Kurmancî', 1, now()),
('dbf01460-1922-5072-a264-d07fe8492d89', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan riya deryayî di bazirganiya Ewropa-Hindistanê de girîngî bi dest xist?', 'Rêya Pasîfîkê', 'Rêya Serê Hêviya Baş', 'Rêya Atlantîkê', 'Rêya Arktîkê', 'B', 'Bi gihîştina Vasco da Gama ya Hindistanê di 1498an de bi riya Serê Hêviyê, ev riya deryayî girîng bû.', 'Bi gihîştina Vasco da Gama ya Hindistanê di 1498an de bi riya Serê Hêviyê, ev riya deryayî girîng bû.', 'Vasco da Gama''nın 1498''de Ümit Burnu üzerinden Hindistan''a ulaşmasıyla bu deniz rotası önem kazandı; kara yolları göreli önemini yitirdi.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', 'approved', 'Kurmancî', 1, now()),
('41942de1-12e6-5e50-b982-ba91ba5dd8e8', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan ol ji Hindistanê ber bi Asyaya Navîn û Çînê ve li ser Riya Hevrîşimê belav bû?', 'Xiristiyanî', 'Budîzm', 'Cihûtî', 'Zerdeştî', 'B', 'Budîzm ji Hindistanê bi rêya Asyaya Navîn ber bi Çînê ve li ser Riya Hevrîşimê belav bû.', 'Budîzm ji Hindistanê bi rêya Asyaya Navîn ber bi Çînê ve li ser Riya Hevrîşimê belav bû.', 'Budizm Hindistan''dan Orta Asya üzerinden Çin''e İpek Yolu boyunca yayıldı. Yol üzerinde Helenistik sanat etkileri de dolaştı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', NULL, 'https://en.wikipedia.org/wiki/Silk_Road', 'approved', 'Kurmancî', 1, now()),
('b8750417-2530-5bb4-b03a-b8f9514ac28b', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di destana Îlyadayê de, kîjan leheng yekem car tê nasîn?', 'Hektor', 'Aşîl', 'Odîseus', 'Agamemnon', 'B', 'Di destana Îlyadayê de, Aşîl lehengê navendî ye, ku bi hêrs û şerê xwe yê li dijî Troyayê tê naskirin.', 'Di destana Îlyadayê de, Aşîl lehengê navendî ye, ku bi hêrs û şerê xwe yê li dijî Troyayê tê naskirin.', 'İlyada Destanı''nda Aşil, Truva''ya karşı öfkesi ve savaşıyla tanınan ana kahramandır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Iliad', NULL, 'https://en.wikipedia.org/wiki/Iliad', 'approved', 'Kurmancî', 1, now()),
('65469713-cc7a-5439-aef5-84b5fc32791d', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan kesayet di destana "Şahname" ya Fîrdewsî de cih digire?', 'Gilgameş', 'Rustem', 'Aşîl', 'Beowulf', 'B', 'Rustem lehengê navendî yê destana "Şahname" ya Fîrdewsî ye, ku bi hêz û mêraniya xwe tê naskirin.', 'Rustem lehengê navendî yê destana "Şahname" ya Fîrdewsî ye, ku bi hêz û mêraniya xwe tê naskirin.', 'Rüstem, Firdevsi''nin "Şehname" destanının gücü ve yiğitliğiyle tanınan ana kahramanıdır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Shahnameh', NULL, 'https://en.wikipedia.org/wiki/Shahnameh', 'approved', 'Kurmancî', 1, now()),
('9b982f0e-7ef2-58a0-9148-23d6d5c6fb11', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan roman ji aliyê Fyodor Dostoyevskî ve hatiye nivîsandin?', 'Şer û Aştî', 'Tawan û Ceza', 'Anna Karenina', 'Karderî', 'B', 'Tawan û Ceza ji aliyê Fyodor Dostoyevskî ve hatiye nivîsandin. Ew romana wî ya herî navdar e û li ser tawan, wijdan û xilasiyê ye.', 'Tawan û Ceza ji aliyê Fyodor Dostoyevskî ve hatiye nivîsandin. Ew romana wî ya herî navdar e û li ser tawan, wijdan û xilasiyê ye.', 'Suç ve Ceza, Fyodor Dostoyevski tarafından yazılmıştır. Yazarın en çok okunan romanlarındandır ve suç, vicdan ve kurtuluş üzerinedir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Crime_and_Punishment', NULL, 'https://en.wikipedia.org/wiki/Crime_and_Punishment', 'approved', 'Kurmancî', 1, now()),
('ebc7362f-8868-572d-a853-ae8dfd936517', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di romana "Şer û Aştî" ya Lev Tolstoy de, kîjan bûyera dîrokî wek paşxane tê bikaranîn?', 'Şerê Napoleon ê li Rûsyayê', 'Şerê cîhanî yê yekem', 'Şoreşa Fransî', 'Şerê navxweyî yê Amerîkayê', 'A', 'Şer û Aştî li ser paşxaneya Şerê Napoleon ê li Rûsyayê ye. Tolstoy di vê romanê de jiyana civaka rûsî di dema şer de vedibêje.', 'Şer û Aştî li ser paşxaneya Şerê Napoleon ê li Rûsyayê ye. Tolstoy di vê romanê de jiyana civaka rûsî di dema şer de vedibêje.', 'Savaş ve Barış, Napolyon''un Rusya Seferi''nin arka planında geçer. Tolstoy bu romanda savaş sırasında Rus toplumunun yaşamını anlatır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/War_and_Peace', NULL, 'https://en.wikipedia.org/wiki/War_and_Peace', 'approved', 'Kurmancî', 1, now()),
('aa8911e9-2471-515f-9a8c-2c5cf9fe008a', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di romana Victor Hugo ya ku behsa Quasimodo dike de, ew li kû dijî?', 'Di qesra padîşah de', 'Di birca Londonê de', 'Di keleha Parisê de', 'Di katedrala Notre-Dame de', 'D', 'Quasimodo di katedrala Notre-Dame de dijî. Ew zengiljenê katedralê ye û ji ber rûyê xwe yê neasayî xwe ji civakê veşartiye.', 'Quasimodo di katedrala Notre-Dame de dijî. Ew zengiljenê katedralê ye û ji ber rûyê xwe yê neasayî xwe ji civakê veşartiye.', 'Quasimodo, Notre Dame Katedrali''nde yaşar. Katedralin çan görevlisidir ve sıra dışı yüzü yüzünden toplumdan gizlenmiştir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Hunchback_of_Notre-Dame', NULL, 'https://en.wikipedia.org/wiki/The_Hunchback_of_Notre-Dame', 'approved', 'Kurmancî', 1, now()),
('943c6a72-015a-5033-b3ae-8c432b0eaa95', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan roman ji aliyê Victor Hugo ve hatiye nivîsandin?', 'Şer û Aştî', 'Tawan û Ceza', 'Karderî', 'Sefîl', 'D', '"Les Misérables" ji aliyê Victor Hugo ve hatiye nivîsandin; li ser dadmendî, xilasî û têkoşîna civakî ye.', '"Les Misérables" ji aliyê Victor Hugo ve hatiye nivîsandin; li ser dadmendî, xilasî û têkoşîna civakî ye.', 'Sefiller (Les Misérables), Victor Hugo tarafından yazılmıştır; adalet, kurtuluş ve toplumsal mücadele üzerinedir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Les_Mis%C3%A9rables', NULL, 'https://en.wikipedia.org/wiki/Les_Mis%C3%A9rables', 'approved', 'Kurmancî', 1, now()),
('630612d6-87e5-5da1-8be3-8205fa4dc477', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di romana "Les Misérables" de, kîjan kesayet ji ber dizîna nan tê girtin?', 'Cosette', 'Jean Valjean', 'Javert', 'Marius', 'B', 'Jean Valjean ji ber ku ji bo zarokên birçî yên xwişka xwe nan diziye, tê girtin û bi salan ceza dibîne. Ev bûyer destpêka çîroka wî ye.', 'Jean Valjean ji ber ku ji bo zarokên birçî yên xwişka xwe nan diziye, tê girtin û bi salan ceza dibîne. Ev bûyer destpêka çîroka wî ye.', 'Jean Valjean, kız kardeşinin aç çocukları için ekmek çaldığı için tutuklanır ve yıllarca ceza görür. Bu olay onun hikayesinin başlangıcıdır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Les_Mis%C3%A9rables', NULL, 'https://en.wikipedia.org/wiki/Les_Mis%C3%A9rables', 'approved', 'Kurmancî', 1, now()),
('e09107f7-b77c-594b-aac6-708106af5b47', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan roman ji aliyê Herman Melville ve hatiye nivîsandin?', 'Moby-Dick', 'Pîrika', 'Jane Eyre', 'Wuthering Heights', 'A', 'Moby-Dick ji aliyê Herman Melville ve hatiye nivîsandin. Ew romana wî ya herî navdar e û li ser nêçîra nehengan û têkoşîna bi nehengekî spî re ye.', 'Moby-Dick ji aliyê Herman Melville ve hatiye nivîsandin. Ew romana wî ya herî navdar e û li ser nêçîra nehengan û têkoşîna bi nehengekî spî re ye.', 'Moby-Dick, Herman Melville tarafından yazılmıştır. Yazarın en çok okunan romanlarındandır ve balina avcılığı ile beyaz bir balinayla mücadeleyi anlatır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Moby-Dick', NULL, 'https://en.wikipedia.org/wiki/Moby-Dick', 'approved', 'Kurmancî', 1, now()),
('4bf4ae33-cff2-518f-93ae-4768f36a7b99', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di romana "Huckleberry Finn" de, kîjan kesayet koleyekî reviyayî ye?', 'Tom Sawyer', 'Jim', 'Pap', 'Judge Thatcher', 'B', 'Jim koleyekî reviyayî ye ku bi Huck re bi kelekê di çemê Mississippi de diçe. Ew di romanê de sembola azadiyê ye.', 'Jim koleyekî reviyayî ye ku bi Huck re bi kelekê di çemê Mississippi de diçe. Ew di romanê de sembola azadiyê ye.', 'Jim, Huck ile birlikte Mississippi Nehri''nde sal ile yolculuk eden kaçak bir köledir. Romanda özgürlüğün sembolüdür.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Adventures_of_Huckleberry_Finn', NULL, 'https://en.wikipedia.org/wiki/Adventures_of_Huckleberry_Finn', 'approved', 'Kurmancî', 1, now()),
('76da55ae-6c13-57b1-b638-eff1f5942ac6', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan berhem ji aliyê William Shakespeare ve hatiye nivîsandin?', 'Hamlet', 'Dîwana Mem û Zîn', 'Şahname', 'Îlyada', 'A', 'Hamlet yek ji berhemên navdar ên Shakespeare e. Dîwana Mem û Zîn a Ehmedê Xanî ye, Şahname ya Fîrdewsî ye, Îlyada jî ya Homêros e.', 'Hamlet yek ji berhemên navdar ên Shakespeare e. Dîwana Mem û Zîn a Ehmedê Xanî ye, Şahname ya Fîrdewsî ye, Îlyada jî ya Homêros e.', 'Hamlet, Shakespeare''in en ünlü eserlerinden biridir. Mem û Zîn Divanı Ahmedê Xanî''ye, Şahname Firdevsî''ye, İlyada ise Homeros''a aittir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Hamlet', NULL, 'https://en.wikipedia.org/wiki/Hamlet', 'approved', 'Kurmancî', 1, now()),
('e5aef09f-99f6-5b7c-96ae-01770cad7b61', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di berhemên Shakespeare de, "To be or not to be" tê çi wateyê?', 'Evîn an nefret', 'Şer an aşitî', 'Jiyan an mirin', 'Xewn an rastî', 'C', '"To be or not to be" di Hamlet de derbas dibe û behsa pirsa jiyan û mirinê dike. Ev yek ji navdartirîn xetên Shakespeare e.', '"To be or not to be" di Hamlet de derbas dibe û behsa pirsa jiyan û mirinê dike. Ev yek ji navdartirîn xetên Shakespeare e.', '"To be or not to be" Hamlet''te geçer ve yaşam ile ölüm sorununu ele alır. Bu, Shakespeare''in en ünlü dizelerinden biridir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/To_be,_or_not_to_be', NULL, 'https://en.wikipedia.org/wiki/To_be,_or_not_to_be', 'approved', 'Kurmancî', 1, now()),
('ea4a2f5c-5705-515c-894a-1105e3d73e05', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan trajediya Shakespeare behsa du evîndarên ciwan ên ji du malbatên dijber ên li Veronayê dike?', 'Macbeth', 'Romeo û Juliet', 'King Lear', 'Othello', 'B', 'Romeo û Juliet yek ji navdartirîn berhemên Shakespeare e. Romeo û Juliet evîndarên ciwan in ku ji malbatên dijmin in.', 'Romeo û Juliet yek ji navdartirîn berhemên Shakespeare e. Romeo û Juliet evîndarên ciwan in ku ji malbatên dijmin in.', 'Romeo ve Juliet, Shakespeare''in en ünlü eserlerinden biridir. Romeo ve Juliet, düşman ailelerden gelen genç aşıklardır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Romeo_and_Juliet', NULL, 'https://en.wikipedia.org/wiki/Romeo_and_Juliet', 'approved', 'Kurmancî', 1, now()),
('79d529e9-ca2c-5efe-940f-4f4f7fcd222e', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di berhemên Shakespeare de kîjan kesayet wekî "Juliet"ê tê naskirin?', 'Evîndara Romeo', 'Keça King Lear', 'Jina Macbeth', 'Xwişka Hamlet', 'A', 'Juliet evîndara Romeoyî ye. Ew ji malbata Capuletan e ku dijminê malbata Montagueyan a Romeoyî ye.', 'Juliet evîndara Romeoyî ye. Ew ji malbata Capuletan e ku dijminê malbata Montagueyan a Romeoyî ye.', 'Juliet, Romeo''nun sevgilisidir. Romeo''nun ailesi Montague''un düşmanı olan Capulet ailesindendir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Romeo_and_Juliet', NULL, 'https://en.wikipedia.org/wiki/Romeo_and_Juliet', 'approved', 'Kurmancî', 1, now()),
('322871a5-d663-5ae7-bf9f-40e15d8081bc', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Berhema Shakespeare a bi navê "King Lear" ji kîjan cureyê wêjeyî ye?', 'Komedî', 'Trajedî', 'Dîrok', 'Romans', 'B', 'King Lear trajediyek e ku behsa pîrbûnê, hêzê û têkiliyên malbatî dike. Lear padîşahek e ku hêza xwe dide keçên xwe.', 'King Lear trajediyek e ku behsa pîrbûnê, hêzê û têkiliyên malbatî dike. Lear padîşahek e ku hêza xwe dide keçên xwe.', 'Kral Lear, yaşlılık, güç ve aile ilişkilerini konu alan bir trajedidir. Lear, gücünü kızlarına devreden bir kraldır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/King_Lear', NULL, 'https://en.wikipedia.org/wiki/King_Lear', 'approved', 'Kurmancî', 1, now()),
('d4640e33-dbb4-5cf7-92cf-087d89cd2773', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Berhema Shakespeare a bi navê "A Midsummer Night''s Dream" ji kîjan cureyê wêjeyî ye?', 'Trajedî', 'Dîrok', 'Komedî', 'Pastoral', 'C', 'A Midsummer Night''s Dream komediyek e ku behsa evînê û xewnan dike. Ew yek ji komediyên herî navdar ên Shakespeare e.', 'A Midsummer Night''s Dream komediyek e ku behsa evînê û xewnan dike. Ew yek ji komediyên herî navdar ên Shakespeare e.', 'Bir Yaz Gecesi Rüyası, aşkı ve hayalleri konu alan bir komedidir. Shakespeare''in en ünlü komedilerinden biridir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/A_Midsummer_Night%27s_Dream', NULL, 'https://en.wikipedia.org/wiki/A_Midsummer_Night%27s_Dream', 'approved', 'Kurmancî', 1, now()),
('cd50356a-d16a-5ec4-9a5b-eb108ae1a1da', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Berhema Shakespeare a bi navê "The Merchant of Venice" ji kîjan cureyê wêjeyî ye?', 'Trajedî', 'Dîrok', 'Komedî', 'Romans', 'C', 'The Merchant of Venice komediyek e ku behsa bazirganekî bi navê Antonio dike. Ew komediyek bi aliyên trajîk e.', 'The Merchant of Venice komediyek e ku behsa bazirganekî bi navê Antonio dike. Ew komediyek bi aliyên trajîk e.', 'Venedik Taciri, Antonio adında bir taciri anlatan bir komedidir. Trajik yönleri de olan bir komedidir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Merchant_of_Venice', NULL, 'https://en.wikipedia.org/wiki/The_Merchant_of_Venice', 'approved', 'Kurmancî', 1, now()),
('bd814ef9-4bfe-5f0c-bbc0-bb697b5ba001', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan berhema Shakespeare behsa bazirganekî bi navê Antonio dike?', 'A Midsummer Night''s Dream', 'Much Ado About Nothing', 'The Merchant of Venice', 'The Tempest', 'C', 'The Merchant of Venice behsa bazirganekî bi navê Antonio dike. Ew komediyek e ku behsa deyn û cezayan dike.', 'The Merchant of Venice behsa bazirganekî bi navê Antonio dike. Ew komediyek e ku behsa deyn û cezayan dike.', 'Venedik Taciri, Antonio adında bir taciri anlatır. Borç ve cezaları konu alan bir komedidir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Merchant_of_Venice', NULL, 'https://en.wikipedia.org/wiki/The_Merchant_of_Venice', 'approved', 'Kurmancî', 1, now()),
('88fed09d-a7cf-57da-81ef-2fed2779a295', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di berhemên Shakespeare de "Prospero" kî ye?', 'Mîrê Danîmarkayê', 'Sêhrbazê The Tempestê', 'Generalê Romayê', 'Bazirganê Venedîkê', 'B', 'Prospero sêhrbazê The Tempestê ye. Ew li giravekê dijî û bi sêhra xwe firtûneyekê çêdike.', 'Prospero sêhrbazê The Tempestê ye. Ew li giravekê dijî û bi sêhra xwe firtûneyekê çêdike.', 'Prospero, Fırtına''nın büyücüsüdür. Bir adada yaşar ve büyüsüyle bir fırtına koparır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Prospero', NULL, 'https://en.wikipedia.org/wiki/Prospero', 'approved', 'Kurmancî', 1, now()),
('b91a749c-a0a9-5aa8-806e-6f1d55b99a22', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di edebiyata realîzmê de, kîjan hêman zêde tê dîtin?', 'Xeyalên berfireh', 'Mîtolojî', 'Rastiya rojane', 'Efsaneyên dîrokî', 'C', 'Realîzm giraniyê dide ser rastiya rojane, jiyana asayî û civakê, ne li ser xeyal û mîtolojiyê.', 'Realîzm giraniyê dide ser rastiya rojane, jiyana asayî û civakê, ne li ser xeyal û mîtolojiyê.', 'Realizm, günlük gerçekliğe, sıradan yaşama ve topluma odaklanır; hayal ve mitolojiye değil.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Literary_realism', NULL, 'https://en.wikipedia.org/wiki/Literary_realism', 'approved', 'Kurmancî', 1, now()),
('c5f922f8-4f8d-58bd-9f2c-7f0ecc67ded4', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di romana "Ulysses"ê de, kîjan teknîk zêde tê bikaranîn?', 'Rêzika kronolojîk', 'Zimanê helbestî', 'Herikîna hiş', 'Diyalogên dirêj', 'C', 'Joyce di "Ulysses"ê de teknîka herikîna hiş bi kar tîne, ev jî taybetmendiyeke modernîzmê ye.', 'Joyce di "Ulysses"ê de teknîka herikîna hiş bi kar tîne, ev jî taybetmendiyeke modernîzmê ye.', 'Joyce, "Ulysses"te bilinç akışı tekniğini kullanır; bu da modernizmin bir özelliğidir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Ulysses_(novel)', NULL, 'https://en.wikipedia.org/wiki/Ulysses_(novel)', 'approved', 'Kurmancî', 1, now()),
('9d9bf136-76c8-5850-b9c2-c062fe5d9e20', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan romana Virginia Woolf wekî mînaka modernîzmê tê naskirin?', 'Ulysses', 'The Great Gatsby', 'One Hundred Years of Solitude', 'Mrs Dalloway', 'D', 'Romana Woolf a bi navê "Mrs Dalloway" bi teknîka herikîna hiş tê naskirin û yek ji berhemên modernîzmê ye.', 'Romana Woolf a bi navê "Mrs Dalloway" bi teknîka herikîna hiş tê naskirin û yek ji berhemên modernîzmê ye.', 'Woolf''un "Mrs Dalloway"i bilinç akışı tekniğiyle tanınır ve modernizmin eserlerinden biridir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Mrs_Dalloway', NULL, 'https://en.wikipedia.org/wiki/Mrs_Dalloway', 'approved', 'Kurmancî', 1, now()),
('916a5707-2d62-5136-91b6-ed20599a8cc8', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan berhema Franz Kafka wekî mînaka modernîzmê tê naskirin?', 'The Metamorphosis', 'Ulysses', 'Madame Bovary', 'Les Misérables', 'A', 'Berhema Kafka ya bi navê "The Metamorphosis" bi naveroka xwe ya surrealîst û modernîst tê naskirin.', 'Berhema Kafka ya bi navê "The Metamorphosis" bi naveroka xwe ya surrealîst û modernîst tê naskirin.', 'Kafka''nın "Dönüşüm"ü gerçeküstü ve modernist bakış açısıyla tanınır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Metamorphosis', NULL, 'https://en.wikipedia.org/wiki/The_Metamorphosis', 'approved', 'Kurmancî', 1, now()),
('e7afabc9-5c9d-5e7b-b6d7-71c86624bc01', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan nivîskara Şîliyî di sala 1945an de bû jina yekem a Amerîkaya Latînî ku Xelata Nobelê ya Edebiyatê wergirtiye?', 'Selma Lagerlöf', 'Pearl S. Buck', 'Gabriela Mistral', 'Nadine Gordimer', 'C', 'Helbestvana Şîliyî Gabriela Mistral di 1945an de Xelata Nobelê wergirt û bû jina yekem a Amerîkaya Latînî ku ev xelat wergirtiye.', 'Helbestvana Şîliyî Gabriela Mistral di 1945an de Xelata Nobelê wergirt û bû jina yekem a Amerîkaya Latînî ku ev xelat wergirtiye.', 'Şilili şair Gabriela Mistral 1945''te Nobel Edebiyat Ödülü''nü kazandı ve bu ödülü alan ilk Latin Amerikalı kadın oldu. Ödülü alan ilk kadın ise 1909''da Selma Lagerlöf''tür.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Gabriela_Mistral', NULL, 'https://en.wikipedia.org/wiki/Gabriela_Mistral', 'approved', 'Kurmancî', 1, now()),
('2af4d661-216a-522b-8a0b-0035bc6ce32f', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di sala 2016an de Xelata Nobelê ya Edebiyatê ji kîjan stranbêj û nivîskarê Amerîkî re hat dayîn?', 'Leonard Cohen', 'Bob Dylan', 'Bruce Springsteen', 'Paul Simon', 'B', 'Bob Dylan di sala 2016an de Xelata Nobelê ya Edebiyatê wergirt. Ew bi helbestên di nava stranên xwe de tê naskirin û ji ber wê yekê ev xelat wergirt.', 'Bob Dylan di sala 2016an de Xelata Nobelê ya Edebiyatê wergirt. Ew bi helbestên di nava stranên xwe de tê naskirin û ji ber wê yekê ev xelat wergirt.', 'Bob Dylan, 2016''da Nobel Edebiyat Ödülü''nü kazandı. Müziğindeki şiirleriyle tanınır ve bu nedenle ödül verilmiştir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Bob_Dylan', NULL, 'https://en.wikipedia.org/wiki/Bob_Dylan', 'approved', 'Kurmancî', 1, now()),
('8724c714-16fb-587a-855d-e8d1756c5993', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan nivîskarê Misrî di sala 1988an de bû yekem nivîskarê Ereb ê ku Xelata Nobelê ya Edebiyatê wergirtiye?', 'Naguib Mahfouz', 'Taha Hussein', 'Nizar Qabbani', 'Adonis', 'A', 'Naguib Mahfouz di sala 1988an de Xelata Nobelê ya Edebiyatê wergirt û bû yekem nivîskarê Ereb ê ku ev xelat bi dest xist. Ew bi berhema xwe ya "The Cairo Trilogy" tê naskirin.', 'Naguib Mahfouz di sala 1988an de Xelata Nobelê ya Edebiyatê wergirt û bû yekem nivîskarê Ereb ê ku ev xelat bi dest xist. Ew bi berhema xwe ya "The Cairo Trilogy" tê naskirin.', 'Necib Mahfuz, 1988''de Nobel Edebiyat Ödülü''nü kazandı ve bu ödülü alan ilk Arap yazar oldu. "Kahire Üçlemesi" adlı romanıyla tanınır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Naguib_Mahfouz', NULL, 'https://en.wikipedia.org/wiki/Naguib_Mahfouz', 'approved', 'Kurmancî', 1, now()),
('65720d16-a291-5072-92d3-a68f1104b602', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan berhem koma fablên nivîskarekî Fransî yê sedsala 17an e ku tê de ajal wekî mirovan dipeyivin?', 'Çîrokên Grimm', 'Hezar û Yek Şev', 'Şahname', 'Fablên La Fontaine', 'D', 'Fablên La Fontaine berhemeke navdar e ku tê de ajel bi zaravayê mirovan dipeyivin û dersên exlaqî didin.', 'Fablên La Fontaine berhemeke navdar e ku tê de ajel bi zaravayê mirovan dipeyivin û dersên exlaqî didin.', 'La Fontaine Masalları, hayvanların insan diliyle konuştuğu ve ahlaki dersler veren ünlü bir eserdir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Jean_de_La_Fontaine', NULL, 'https://en.wikipedia.org/wiki/Jean_de_La_Fontaine', 'approved', 'Kurmancî', 1, now()),
('47736c3d-5b34-5120-bc51-0a6065e8ea8b', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di muzîkê de, nîşana ku bilindahiya dengan diyar dike çi ye?', 'Nota', 'Rîtm', 'Melodî', 'Aheng', 'A', 'Nota di muzîkê de nîşaneya deng e û bilindahî û dirêjiya dengan diyar dike. Rîtm, melodî û aheng jî hêmanên muzîkê ne lê bilindahiya dengan bi notayan tê nîşankirin.', 'Nota di muzîkê de nîşaneya deng e û bilindahî û dirêjiya dengan diyar dike. Rîtm, melodî û aheng jî hêmanên muzîkê ne lê bilindahiya dengan bi notayan tê nîşankirin.', 'Nota müzikte sesin işaretidir ve seslerin yüksekliğini ve süresini belirtir. Ritim, melodi ve armoni de müziğin öğeleridir ancak seslerin yüksekliği notalarla gösterilir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Musical_note', NULL, 'https://en.wikipedia.org/wiki/Musical_note', 'approved', 'Kurmancî', 1, now()),
('7c32ea79-e7cd-5d95-8d9f-28990bc41ff4', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di muzîkê de, rêjdana dengan li gorî demê çi ye?', 'Rîtm', 'Nota', 'Navber', 'Aheng', 'A', 'Rîtm di muzîkê de rêjdana dengan li gorî demê ye. Nota nîşaneya dengan e, navber dûrahiya di navbera dengan de ye û aheng jî hevahengiya dengan e.', 'Rîtm di muzîkê de rêjdana dengan li gorî demê ye. Nota nîşaneya dengan e, navber dûrahiya di navbera dengan de ye û aheng jî hevahengiya dengan e.', 'Ritim müzikte seslerin zamana göre dizilişidir. Nota seslerin işaretidir, aralık sesler arasındaki mesafedir ve armoni de seslerin uyumudur.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Rhythm', NULL, 'https://en.wikipedia.org/wiki/Rhythm', 'approved', 'Kurmancî', 1, now()),
('6cad65e9-1f45-5017-b588-7e7eda9a42f0', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di muzîkê de, leza ku bi piranî bi "beats per minute" tê pîvandin çi ye?', 'Rîtm', 'Aheng', 'Melodî', 'Tempo', 'D', 'Tempo di muzîkê de leza muzîkê ye û bi piranî bi "beats per minute" tê pîvandin. Rîtm rêjdana dengan e, aheng hevahengiya dengan e û melodî jî rêzika dengan e.', 'Tempo di muzîkê de leza muzîkê ye û bi piranî bi "beats per minute" tê pîvandin. Rîtm rêjdana dengan e, aheng hevahengiya dengan e û melodî jî rêzika dengan e.', 'Tempo müzikte müziğin hızıdır ve çoğunlukla "dakikadaki vuruş" ile ölçülür. Ritim seslerin dizilişidir, armoni seslerin uyumudur ve melodi de seslerin dizisidir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Tempo', NULL, 'https://en.wikipedia.org/wiki/Tempo', 'approved', 'Kurmancî', 1, now()),
('d461723a-cfff-598e-b3dc-0ebea3b5172b', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Ludwig van Beethoven herî zêde bi kîjan senfoniyê tê naskirin?', 'Senfoniya 1ê', 'Senfoniya 3yan', 'Senfoniya 6an', 'Senfoniya 5an', 'D', 'Beethoven bi Senfoniya 5an a navdar, ku bi destpêka xwe ya "da-da-da-dum" tê naskirin, herî zêde tê naskirin.', 'Beethoven bi Senfoniya 5an a navdar, ku bi destpêka xwe ya "da-da-da-dum" tê naskirin, herî zêde tê naskirin.', 'Beethoven, "da-da-da-dum" başlangıcıyla bilinen ünlü 5. Senfonisiyle en çok tanınır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Symphony_No._5_(Beethoven)', NULL, 'https://en.wikipedia.org/wiki/Symphony_No._5_(Beethoven)', 'approved', 'Kurmancî', 1, now()),
('07092a36-6d9e-5873-ba04-0fe353766bfc', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Ludwig van Beethoven herî zêde bi kîjan operayê tê naskirin?', 'Don Giovanni', 'The Magic Flute', 'The Creation', 'Fidelio', 'D', 'Beethoven tenê yek opera nivîsiye, bi navê "Fidelio", ku yek ji navdartirîn berhemên wî ye.', 'Beethoven tenê yek opera nivîsiye, bi navê "Fidelio", ku yek ji navdartirîn berhemên wî ye.', 'Beethoven sadece bir opera yazmıştır, adı "Fidelio"dur ve en ünlü operalarından biridir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Fidelio', NULL, 'https://en.wikipedia.org/wiki/Fidelio', 'approved', 'Kurmancî', 1, now()),
('02678600-6117-55cf-a38b-50c6a8d86875', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan bestekarê klasîk bi operaya xwe ya "The Magic Flute" tê naskirin?', 'Wolfgang Amadeus Mozart', 'Ludwig van Beethoven', 'Joseph Haydn', 'Franz Schubert', 'A', 'Mozart operaya "The Magic Flute" (Die Zauberflöte) di sala 1791ê de nivîsiye û ev opera yek ji navdartirîn operayên wî ye.', 'Mozart operaya "The Magic Flute" (Die Zauberflöte) di sala 1791ê de nivîsiye û ev opera yek ji navdartirîn operayên wî ye.', 'Mozart, "The Magic Flute" (Die Zauberflöte) operasını 1791''de yazmıştır ve bu opera onun en ünlü operalarından biridir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Magic_Flute', NULL, 'https://en.wikipedia.org/wiki/The_Magic_Flute', 'approved', 'Kurmancî', 1, now()),
('51daf1b5-2a3b-542f-9868-776d4db010af', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Joseph Haydn bi giştî çend senfonî nivîsîne?', '41', '104', '9', '32', 'B', 'Haydn bi qasî 104 senfonî nivîsîne û ji ber vê yekê wekî "bavê senfoniyê" tê naskirin.', 'Haydn bi qasî 104 senfonî nivîsîne û ji ber vê yekê wekî "bavê senfoniyê" tê naskirin.', 'Haydn yaklaşık 104 senfoni yazmıştır ve bu nedenle "senfoninin babası" olarak bilinir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Joseph_Haydn', NULL, 'https://en.wikipedia.org/wiki/Joseph_Haydn', 'approved', 'Kurmancî', 1, now()),
('3ef5dea5-ed87-5c03-81d9-e9916f205ce2', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan bestekarê klasîk bi leqeba Bavê Senfoniyê tê naskirin?', 'Wolfgang Amadeus Mozart', 'Ludwig van Beethoven', 'Joseph Haydn', 'Franz Schubert', 'C', 'Joseph Haydn ji ber bandora xwe ya li ser formên muzîkê yên klasîk wekî "Bavê Senfoniyê" tê naskirin.', 'Joseph Haydn ji ber bandora xwe ya li ser formên muzîkê yên klasîk wekî "Bavê Senfoniyê" tê naskirin.', 'Joseph Haydn, klasik müzik formları üzerindeki etkisi nedeniyle "Klasik Müziğin Babası" olarak bilinir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Joseph_Haydn', NULL, 'https://en.wikipedia.org/wiki/Joseph_Haydn', 'approved', 'Kurmancî', 1, now()),
('d26cb883-890d-553f-98b8-fda11cdb8711', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Caz li kîjan bajarî derketiye holê?', 'New Orleans', 'New York', 'Chicago', 'Los Angeles', 'A', 'Caz di destpêka sedsala 20î de li New Orleansê, ji bingeha blues û ragtime a civakên afroamerîkî derket.', 'Caz di destpêka sedsala 20î de li New Orleansê, ji bingeha blues û ragtime a civakên afroamerîkî derket.', 'Caz 20. yüzyılın başında New Orleans''ta, Afroamerikan toplulukların blues ve ragtime birikiminden doğdu.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Jazz', NULL, 'https://en.wikipedia.org/wiki/Jazz', 'approved', 'Kurmancî', 1, now()),
('7cbf93ad-96bd-56ad-8e75-e2d9d3d4fa09', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Blues bi piranî ji kîjan herêmê derketiye?', 'Ji bakurê Dewletên Yekbûyî', 'Ji başûrê Dewletên Yekbûyî', 'Ji rojhilatê Dewletên Yekbûyî', 'Ji rojavayê Dewletên Yekbûyî', 'B', 'Blues di dawiya sedsala 19an de li başûrê Dewletên Yekbûyî, bi taybetî li eyaleta Mississippi, ji muzîka afroamerîkî derketiye. Ev muzîk ji xemgînî û zehmetiyên jiyanê derketiye holê.', 'Blues di dawiya sedsala 19an de li başûrê Dewletên Yekbûyî, bi taybetî li eyaleta Mississippi, ji muzîka afroamerîkî derketiye. Ev muzîk ji xemgînî û zehmetiyên jiyanê derketiye holê.', 'Blues, 19. yüzyılın sonlarında ABD''nin güneyinde, özellikle Mississippi eyaletinde Afro-Amerikan müziğinden ortaya çıkmıştır. Bu müzik, hayatın acılarından ve zorluklarından doğmuştur.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Blues', NULL, 'https://en.wikipedia.org/wiki/Blues', 'approved', 'Kurmancî', 1, now()),
('a3392dfa-bd00-57b0-83e3-07e363ff1e16', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Michael Jackson bi kîjan strana xwe ya navdar a popê tê naskirin?', 'Like a Virgin', 'I Will Always Love You', 'Thriller', 'Respect', 'C', 'Michael Jackson bi strana xwe ya "Thriller" pir navdar bû. Ev stran di sala 1982an de derketiye û wekî yek ji stranên herî navdar ên dîroka muzîkê tê hesibandin.', 'Michael Jackson bi strana xwe ya "Thriller" pir navdar bû. Ev stran di sala 1982an de derketiye û wekî yek ji stranên herî navdar ên dîroka muzîkê tê hesibandin.', 'Michael Jackson, "Thriller" şarkısıyla çok ünlü olmuştur. Bu şarkı 1982''de çıkmış ve müzik tarihinin en ünlü şarkılarından biri olarak kabul edilir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Thriller_(song)', NULL, 'https://en.wikipedia.org/wiki/Thriller_(song)', 'approved', 'Kurmancî', 1, now()),
('e09ffd01-97c5-53e8-858b-204a8ac5c867', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Louis Armstrong bi kîjan strana xwe ya navdar a cazê tê naskirin?', 'My Way', 'Fly Me to the Moon', 'Take Five', 'What a Wonderful World', 'D', 'Louis Armstrong bi strana xwe ya "What a Wonderful World" pir navdar bû. Ev stran di sala 1967an de derketiye û wekî yek ji klasîkên cazê tê hesibandin.', 'Louis Armstrong bi strana xwe ya "What a Wonderful World" pir navdar bû. Ev stran di sala 1967an de derketiye û wekî yek ji klasîkên cazê tê hesibandin.', 'Louis Armstrong, "What a Wonderful World" şarkısıyla çok ünlü olmuştur. Bu şarkı 1967''de çıkmış ve cazın klasiklerinden biri olarak kabul edilir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/What_a_Wonderful_World', NULL, 'https://en.wikipedia.org/wiki/What_a_Wonderful_World', 'approved', 'Kurmancî', 1, now()),
('11fb2749-3e29-52fd-bfb4-c089f424d28e', (select id from categories where slug = 'cihan'), 'ku-kmr', 'The Rolling Stones bi kîjan strana xwe ya navdar a rockê tê naskirin?', '(I Can''t Get No) Satisfaction', 'Hey Jude', 'Stairway to Heaven', 'Hotel California', 'A', 'The Rolling Stones bi strana xwe ya "(I Can''t Get No) Satisfaction" pir navdar bûn. Ev stran di sala 1965an de derketiye û wekî yek ji klasîkên rockê tê hesibandin.', 'The Rolling Stones bi strana xwe ya "(I Can''t Get No) Satisfaction" pir navdar bûn. Ev stran di sala 1965an de derketiye û wekî yek ji klasîkên rockê tê hesibandin.', 'The Rolling Stones, "(I Can"t Get No) Satisfaction'' şarkısıyla çok ünlü olmuştur. Bu şarkı 1965''te çıkmış ve rock''ın klasiklerinden biri olarak kabul edilir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/(I_Can%27t_Get_No)_Satisfaction', NULL, 'https://en.wikipedia.org/wiki/(I_Can%27t_Get_No)_Satisfaction', 'approved', 'Kurmancî', 1, now()),
('f802e161-1608-5ec5-b1d0-710c94aa0f12', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Senfonî bi piranî ji bo çi tê nivîsandin?', 'Piyanoyê', 'Kemançeyê', 'Tembûrê', 'Orkestrayê', 'D', 'Senfonî bi piranî ji bo orkestrayê tê nivîsandin. Orkestra ji gelek amûran pêk tê, wekî amûrên têldar, pifdar û yên lêdanê.', 'Senfonî bi piranî ji bo orkestrayê tê nivîsandin. Orkestra ji gelek amûran pêk tê, wekî amûrên têldar, pifdar û yên lêdanê.', 'Senfoni çoğunlukla orkestra için bestelenir. Orkestra; yaylı, nefesli ve vurmalı çalgılar gibi birçok enstrümandan oluşur.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Symphony', NULL, 'https://en.wikipedia.org/wiki/Symphony', 'approved', 'Kurmancî', 1, now()),
('2f33db30-e9a4-53a8-9d43-ba36bbbc2367', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di operayê de, kîjan peyv ji bo strana soloyê tê bikaranîn?', 'Arya', 'Koros', 'Rîtm', 'Melodî', 'A', 'Arya di operayê de perçeyeke vokal a serbixwe ye ku ji bo stranbêjekî tenê hatiye nivîsandin; bi orkestrayê re tê gotin.', 'Arya di operayê de perçeyeke vokal a serbixwe ye ku ji bo stranbêjekî tenê hatiye nivîsandin; bi orkestrayê re tê gotin.', 'Arya, operada tek bir solist için yazılmış bağımsız vokal parçadır; orkestra eşliği bulunur.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Aria', NULL, 'https://en.wikipedia.org/wiki/Aria', 'approved', 'Kurmancî', 1, now()),
('c564ed12-1265-5d7b-8754-4bb415fe5e20', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Senfonî bi piranî ji çend beşan pêk tê?', 'Sê beşan', 'Du beşan', 'Pênc beşan', 'Çar beşan', 'D', 'Senfonî bi piranî ji çar beşan pêk tê. Ev beş bi leza xwe ji hev cihê ne: yekem lezgîn, duyem hêdî, sêyem reqs û çarem lezgîn.', 'Senfonî bi piranî ji çar beşan pêk tê. Ev beş bi leza xwe ji hev cihê ne: yekem lezgîn, duyem hêdî, sêyem reqs û çarem lezgîn.', 'Senfoni çoğunlukla dört bölümden oluşur. Bu bölümler hızlarıyla birbirinden ayrılır: birincisi hızlı, ikincisi yavaş, üçüncüsü dans ve dördüncüsü hızlıdır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Symphony', NULL, 'https://en.wikipedia.org/wiki/Symphony', 'approved', 'Kurmancî', 1, now()),
('ad1d9dda-0457-5840-93ff-e3b5e7883a39', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di senfoniyê de, kîjan amûr bi piranî di beşa amûrên têldar de cih digire û dişibe kemanê?', 'Bilûr', 'Viyola', 'Tembûr', 'Def', 'B', 'Di senfoniyê de, viyola bi piranî di beşa amûrên têldar de cih digire û dişibe kemanê. Viyola ji kemanê mezintir e û dengê wê kûrtir e.', 'Di senfoniyê de, viyola bi piranî di beşa amûrên têldar de cih digire û dişibe kemanê. Viyola ji kemanê mezintir e û dengê wê kûrtir e.', 'Senfonide, viyola çoğunlukla yaylı bölümde yer alır ve kemana benzer. Viyola, kemandan daha büyüktür ve sesi daha derindir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Viola', NULL, 'https://en.wikipedia.org/wiki/Viola', 'approved', 'Kurmancî', 1, now()),
('54ee06d4-b3c5-5d29-a930-ba441507ab07', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di operayê de, kîjan peyv ji bo koma stranbêjan tê bikaranîn?', 'Koro', 'Arya', 'Solîst', 'Rîtm', 'A', 'Di operayê de, koro ji bo koma stranbêjan tê bikaranîn. Koro bi piranî ji bo nîşandana hestên gel an jî komê tê bikaranîn.', 'Di operayê de, koro ji bo koma stranbêjan tê bikaranîn. Koro bi piranî ji bo nîşandana hestên gel an jî komê tê bikaranîn.', 'Operada, şarkıcılar topluluğu için koro kullanılır. Koro çoğunlukla halkın veya topluluğun duygularını göstermek için kullanılır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Choir', NULL, 'https://en.wikipedia.org/wiki/Choir', 'approved', 'Kurmancî', 1, now()),
('cc203284-985a-5f2b-8c46-ef5c4ad71439', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan têgîn bilindahiya dengan di muzîkê de diyar dike?', 'Rîtm', 'Tempo', 'Dînamîk', 'Perde', 'D', 'Perde bilindahiya dengan diyar dike. Rîtm demê, tempo lezê û dînamîk jî bihêzbûna dengan nîşan dide.', 'Perde bilindahiya dengan diyar dike. Rîtm demê, tempo lezê û dînamîk jî bihêzbûna dengan nîşan dide.', 'Pitch, seslerin yüksekliğini ifade eder. Ritim zamanı, tempo hızı ve dinamik de seslerin gücünü gösterir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Pitch_(music)', NULL, 'https://en.wikipedia.org/wiki/Pitch_(music)', 'approved', 'Kurmancî', 1, now()),
('f99b88c6-4199-55dc-936d-8ea6e76dc907', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di kîjan salê de fîlma yekem a bi navê "La Sortie de l''usine Lumière à Lyon" ji aliyê Auguste û Louis Lumière ve hate kişandin?', '1905', '1915', '1895', '1925', 'C', 'Fîlma "La Sortie de l''usine Lumière à Lyon" di sala 1895an de ji aliyê birayên Lumière ve hate kişandin. Ev fîlm yek ji fîlmên yekem ên dîrokê ye û destpêka sînemayê nîşan dide.', 'Fîlma "La Sortie de l''usine Lumière à Lyon" di sala 1895an de ji aliyê birayên Lumière ve hate kişandin. Ev fîlm yek ji fîlmên yekem ên dîrokê ye û destpêka sînemayê nîşan dide.', '"La Sortie de l"usine Lumière à Lyon'' filmi 1895''te Lumière kardeşler tarafından çekildi. Bu film tarihin ilk filmlerinden biridir ve sinemanın başlangıcını gösterir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Workers_Leaving_the_Lumi%C3%A8re_Factory', NULL, 'https://en.wikipedia.org/wiki/Workers_Leaving_the_Lumi%C3%A8re_Factory', 'approved', 'Kurmancî', 1, now()),
('f7acaacf-4814-56f1-b0ee-dafcdfea7d48', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di kîjan salê de fîlma "Bicycle Thieves" a Vittorio De Sica derket?', '1950', '1946', '1952', '1948', 'D', 'Ev fîlma îtalyan a neorealîst di sala 1948an de derket û weke yek ji berhemên herî girîng ên vê tevgerê tê zanîn.', 'Ev fîlma îtalyan a neorealîst di sala 1948an de derket û weke yek ji berhemên herî girîng ên vê tevgerê tê zanîn.', 'Bu İtalyan Yeni Gerçekçilik filmi 1948''de gösterime girdi ve bu akımın en önemli eserlerinden biri olarak kabul edilir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Bicycle_Thieves', NULL, 'https://en.wikipedia.org/wiki/Bicycle_Thieves', 'approved', 'Kurmancî', 1, now()),
('b9e77db8-8fe4-56ff-89b5-d1e015253e9d', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerê amerîkî fîlma "The Godfather Part II" derxist?', 'Martin Scorsese', 'Steven Spielberg', 'Quentin Tarantino', 'Francis Ford Coppola', 'D', 'Francis Ford Coppola derhênerê fîlma "The Godfather Part II" ye. Ev fîlm di sala 1974an de derket û Xelata Oscarê ji bo fîlma herî baş wergirt. Fîlm hem çîroka Michael Corleone û hem jî çîroka bavê wî Vito Corleone yê ciwan vedibêje.', 'Francis Ford Coppola derhênerê fîlma "The Godfather Part II" ye. Ev fîlm di sala 1974an de derket û Xelata Oscarê ji bo fîlma herî baş wergirt. Fîlm hem çîroka Michael Corleone û hem jî çîroka bavê wî Vito Corleone yê ciwan vedibêje.', 'Francis Ford Coppola, "Baba II" filminin yönetmenidir. Bu film 1974''te gösterime girdi ve En İyi Film dalında Oscar Ödülü kazandı. Film hem Michael Corleone''nin hikayesini hem de babası genç Vito Corleone''nin hikayesini anlatır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Godfather_Part_II', NULL, 'https://en.wikipedia.org/wiki/The_Godfather_Part_II', 'approved', 'Kurmancî', 1, now()),
('3cde5058-c284-5683-bbd1-5bb70872d779', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerê îngilîz fîlma "The Lodger: A Story of the London Fog" derxist?', 'Alfred Hitchcock', 'Michael Powell', 'David Lean', 'Carol Reed', 'A', 'Alfred Hitchcock derhênerê vî fîlmê bêdeng e ku di sala 1927an de derketiye û weke yek ji berhemên wî yên destpêkê tê zanîn.', 'Alfred Hitchcock derhênerê vî fîlmê bêdeng e ku di sala 1927an de derketiye û weke yek ji berhemên wî yên destpêkê tê zanîn.', 'Alfred Hitchcock, 1927''de gösterime giren bu sessiz filmin yönetmenidir ve onun ilk dönem işlerinden biri olarak kabul edilir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Lodger:_A_Story_of_the_London_Fog', NULL, 'https://en.wikipedia.org/wiki/The_Lodger:_A_Story_of_the_London_Fog', 'approved', 'Kurmancî', 1, now()),
('7dc521aa-c73d-5849-8692-ba8555d5bd68', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerê rûs fîlma "The Man with a Movie Camera" derxist?', 'Sergei Eisenstein', 'Vsevolod Pudovkin', 'Dziga Vertov', 'Alexander Dovzhenko', 'C', 'Dziga Vertov derhênerê vî belgefîlmê ezmûnî ye ku di sala 1929an de derketiye û bi teknîkên xwe yên montajê tê zanîn.', 'Dziga Vertov derhênerê vî belgefîlmê ezmûnî ye ku di sala 1929an de derketiye û bi teknîkên xwe yên montajê tê zanîn.', 'Dziga Vertov, 1929''da gösterime giren bu deneysel belgeselin yönetmenidir ve montaj teknikleriyle tanınır.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Man_with_a_Movie_Camera', NULL, 'https://en.wikipedia.org/wiki/Man_with_a_Movie_Camera', 'approved', 'Kurmancî', 1, now()),
('2bf9fe3f-bc37-572c-8913-6887f0cc760c', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerê japonî fîlma "Rashomon" derxist?', 'Kenji Mizoguchi', 'Yasujirō Ozu', 'Akira Kurosawa', 'Masaki Kobayashi', 'C', 'Akira Kurosawa derhênerê vî fîlmî ye ku di sala 1950î de derket û sînemaya japonî bi cîhanê da nasîn.', 'Akira Kurosawa derhênerê vî fîlmî ye ku di sala 1950î de derket û sînemaya japonî bi cîhanê da nasîn.', 'Akira Kurosawa, 1950''de gösterime giren bu filmin yönetmenidir ve Japon sinemasını dünyaya tanıtmıştır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Rashomon', NULL, 'https://en.wikipedia.org/wiki/Rashomon', 'approved', 'Kurmancî', 1, now()),
('f8a358b7-728d-546c-859f-661822123586', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerê îranî fîlmê "A Separation" derxist?', 'Abbas Kiarostami', 'Jafar Panahi', 'Mohsen Makhmalbaf', 'Asghar Farhadi', 'D', 'Asghar Farhadi derhênerê vî fîlmî ye ku di sala 2011an de derket û Xelata Oscarê ya fîlmê biyanî yê herî baş wergirt.', 'Asghar Farhadi derhênerê vî fîlmî ye ku di sala 2011an de derket û Xelata Oscarê ya fîlmê biyanî yê herî baş wergirt.', 'Asghar Farhadi, 2011''de gösterime giren bu filmin yönetmenidir ve film En İyi Yabancı Film Oscar''ını kazanmıştır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/A_Separation', NULL, 'https://en.wikipedia.org/wiki/A_Separation', 'approved', 'Kurmancî', 1, now()),
('85e8f75b-fcc7-5da0-be46-59bd16248648', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerê meksîkî fîlmê "Birdman" derxist?', 'Alfonso Cuarón', 'Guillermo del Toro', 'Alejandro González Iñárritu', 'Carlos Reygadas', 'C', 'Alejandro González Iñárritu derhênerê vî fîlmî ye ku di sala 2014an de derket û Xelata Oscarê ji bo derhêneriya herî baş wergirt.', 'Alejandro González Iñárritu derhênerê vî fîlmî ye ku di sala 2014an de derket û Xelata Oscarê ji bo derhêneriya herî baş wergirt.', 'Alejandro González Iñárritu, 2014''te gösterime giren bu filmin yönetmenidir ve En İyi Yönetmen Oscar''ını kazanmıştır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Birdman_(film)', NULL, 'https://en.wikipedia.org/wiki/Birdman_(film)', 'approved', 'Kurmancî', 1, now()),
('49c1eed5-222e-56ee-a657-37a22539b199', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerê amerîkî fîlmê "Schindler''s List" derxist?', 'Martin Scorsese', 'Steven Spielberg', 'Francis Ford Coppola', 'George Lucas', 'B', 'Steven Spielberg derhênerê vî fîlmî ye ku di sala 1993an de derket û li ser holokostê ye.', 'Steven Spielberg derhênerê vî fîlmî ye ku di sala 1993an de derket û li ser holokostê ye.', 'Steven Spielberg, 1993''te gösterime giren ve Holokost''u konu alan bu filmin yönetmenidir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Schindler%27s_List', NULL, 'https://en.wikipedia.org/wiki/Schindler%27s_List', 'approved', 'Kurmancî', 1, now()),
('f2e8848c-e331-54b8-95b4-7cee82689d30', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan têgeha sînemayê ji bo rêza wêneyan a ku piştî kişandinê tê birîn û li hev tê zeliqandin tê bikaranîn?', 'Montaj', 'Senaryo', 'Kadraj', 'Diyalog', 'A', 'Montaj (editing) pêvajoya hilbijartin, birîn û lihevxistina wêneyan e ji bo çêkirina fîlmekî. Senaryo çîroka fîlmê ye, kadraj wêneyê ku di kamerayê de tê dîtin e, diyalog jî axaftina karakteran e.', 'Montaj (editing) pêvajoya hilbijartin, birîn û lihevxistina wêneyan e ji bo çêkirina fîlmekî. Senaryo çîroka fîlmê ye, kadraj wêneyê ku di kamerayê de tê dîtin e, diyalog jî axaftina karakteran e.', 'Montaj (kurgu), bir film oluşturmak için görüntüleri seçme, kesme ve birleştirme sürecidir. Senaryo filmin hikayesidir, kadraj kamerada görülen görüntüdür, diyalog ise karakterlerin konuşmasıdır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Film_editing', NULL, 'https://en.wikipedia.org/wiki/Film_editing', 'approved', 'Kurmancî', 1, now()),
('2e476071-87fd-507f-af7c-44fcc9d461f4', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan têgeha sînemayê ji bo rêbaza ku tê de kamera ji cihê xwe diçe û wêneyê dişopîne tê bikaranîn?', 'Kadra sabît', 'Kadra statîk', 'Kadra tevger', 'Kadra rast', 'C', 'Kadra tevger (moving shot) ew wêne ye ku kamera bi tevgera xwe re çêdike. Ev tevger dikare bi kameraya destan, bi dolly an jî bi crane ve be. Kadra sabît jî ew wêne ye ku kamera di cihê xwe de disekine.', 'Kadra tevger (moving shot) ew wêne ye ku kamera bi tevgera xwe re çêdike. Ev tevger dikare bi kameraya destan, bi dolly an jî bi crane ve be. Kadra sabît jî ew wêne ye ku kamera di cihê xwe de disekine.', 'Hareketli kadraj (moving shot), kameranın hareketiyle oluşturulan bir görüntüdür. Bu hareket el kamerası, dolly veya vinç ile yapılabilir. Sabit kadraj ise kameranın yerinde sabit kaldığı görüntüdür.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Shot_(filmmaking)', NULL, 'https://en.wikipedia.org/wiki/Shot_(filmmaking)', 'approved', 'Kurmancî', 1, now()),
('ef1c3cc5-9b90-5aa4-8847-ad79b1c5b2ba', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan têgeha sînemayê ji bo pêvajoya hilbijartina wêneyan û lihevxistina wan ji bo çêkirina fîlmekî tê bikaranîn?', 'Kadraj', 'Senaryo', 'Montaj', 'Diyalog', 'C', 'Montaj (editing) pêvajoya hilbijartina wêneyan, birîna wan û lihevxistina wan e ji bo çêkirina fîlmekî. Ev pêvajo ji bo kontrolkirina rîtm û çîrokbêjiya fîlmê girîng e. Kadraj wêneyê ku tê dîtin e, senaryo çîrok e, diyalog jî axaftin e.', 'Montaj (editing) pêvajoya hilbijartina wêneyan, birîna wan û lihevxistina wan e ji bo çêkirina fîlmekî. Ev pêvajo ji bo kontrolkirina rîtm û çîrokbêjiya fîlmê girîng e. Kadraj wêneyê ku tê dîtin e, senaryo çîrok e, diyalog jî axaftin e.', 'Montaj (kurgu), bir film oluşturmak için görüntüleri seçme, kesme ve birleştirme sürecidir. Bu süreç filmin ritmini ve hikaye anlatımını kontrol etmek için önemlidir. Kadraj görülen görüntüdür, senaryo hikayedir, diyalog ise konuşmadır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Film_editing', NULL, 'https://en.wikipedia.org/wiki/Film_editing', 'approved', 'Kurmancî', 1, now()),
('ef0caef8-1f16-56a9-bc7c-5c49d5fa1bc4', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerê îtalyan fîlmê "Bicycle Thieves" derxistiye?', 'Federico Fellini', 'Roberto Rossellini', 'Luchino Visconti', 'Vittorio De Sica', 'D', '"Bicycle Thieves" fîlmekî navdar ê neorealîzmê ye ku di sala 1948an de ji aliyê Vittorio De Sica ve hatiye derxistin. Ev fîlm çîroka bav û kurê ku li pey bisîkleteke diziyayî digerin vedibêje.', '"Bicycle Thieves" fîlmekî navdar ê neorealîzmê ye ku di sala 1948an de ji aliyê Vittorio De Sica ve hatiye derxistin. Ev fîlm çîroka bav û kurê ku li pey bisîkleteke diziyayî digerin vedibêje.', '"Bicycle Thieves", 1948''de Vittorio De Sica tarafından çekilen ünlü bir neorealizm filmidir. Bu film, çalınan bir bisikletin peşine düşen bir baba ve oğlunun hikayesini anlatır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Bicycle_Thieves', NULL, 'https://en.wikipedia.org/wiki/Bicycle_Thieves', 'approved', 'Kurmancî', 1, now()),
('c9a1d405-89b3-5518-834c-b3b7a834d83e', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlmê "Rome, Open City" yê ku yek ji destpêkên neorealîzma îtalyan e, ji aliyê kîjan derhênerî ve hatiye kişandin?', 'Roberto Rossellini', 'Michelangelo Antonioni', 'Pier Paolo Pasolini', 'Bernardo Bertolucci', 'A', '"Rome, Open City" di sala 1945an de ji aliyê Roberto Rossellini ve hatiye derxistin û wekî yek ji fîlmên bingehîn ên neorealîzma îtalyan tê qebûlkirin. Fîlm li ser berxwedana îtalyan a li dijî dagirkeriya nazî ye.', '"Rome, Open City" di sala 1945an de ji aliyê Roberto Rossellini ve hatiye derxistin û wekî yek ji fîlmên bingehîn ên neorealîzma îtalyan tê qebûlkirin. Fîlm li ser berxwedana îtalyan a li dijî dagirkeriya nazî ye.', '"Rome, Open City" 1945''te Roberto Rossellini tarafından çekilmiş ve İtalyan neorealizminin temel filmlerinden biri olarak kabul edilir. Film, İtalyanların Nazi işgaline karşı direnişini konu alır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Rome,_Open_City', NULL, 'https://en.wikipedia.org/wiki/Rome,_Open_City', 'approved', 'Kurmancî', 1, now()),
('7ddd8aed-2d7b-5c74-aba4-f1b7f3a332c5', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlmê "Breathless" (À bout de souffle) yê Jean-Luc Godard di kîjan salê de derketiye?', '1960', '1955', '1965', '1970', 'A', '"Breathless" di sala 1960î de ji aliyê Jean-Luc Godard ve hatiye derxistin. Ev fîlm yek ji fîlmên herî navdar ên Pêla Nû ya Fransî ye û bi teknîka xwe ya "jump cut" tê nasîn.', '"Breathless" di sala 1960î de ji aliyê Jean-Luc Godard ve hatiye derxistin. Ev fîlm yek ji fîlmên herî navdar ên Pêla Nû ya Fransî ye û bi teknîka xwe ya "jump cut" tê nasîn.', '"Breathless" 1960''ta Jean-Luc Godard tarafından çekilmiştir. Bu film, Fransız Yeni Dalgası''nın en ünlü filmlerinden biridir ve "jump cut" tekniğiyle tanınır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Breathless_(1960_film)', NULL, 'https://en.wikipedia.org/wiki/Breathless_(1960_film)', 'approved', 'Kurmancî', 1, now()),
('0a48bada-6e29-541a-a2e1-a0cb7786950c', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlmê "The 400 Blows" yê François Truffaut çîroka kîjan kesî vedibêje?', 'Kesekî mezin ê dewlemend', 'Jinekê bi navê Gelsomina', 'Mêrekî bi navê Zampanò', 'Xortekî bi navê Antoine Doinel', 'D', '"The 400 Blows" çîroka xortekî bi navê Antoine Doinel vedibêje ku li Parîsê dijî û bi gelek pirsgirêkan re rû bi rû dimîne. Fîlm yek ji fîlmên bingehîn ên Pêla Nû ya Fransî ye.', '"The 400 Blows" çîroka xortekî bi navê Antoine Doinel vedibêje ku li Parîsê dijî û bi gelek pirsgirêkan re rû bi rû dimîne. Fîlm yek ji fîlmên bingehîn ên Pêla Nû ya Fransî ye.', '"The 400 Blows", Paris''te yaşayan ve birçok sorunla karşı karşıya kalan Antoine Doinel adlı bir gencin hikayesini anlatır. Film, Fransız Yeni Dalgası''nın temel filmlerinden biridir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_400_Blows', NULL, 'https://en.wikipedia.org/wiki/The_400_Blows', 'approved', 'Kurmancî', 1, now()),
('b564b739-de3f-5bed-90a3-76a524c18dbf', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerê îtalyan fîlmê "Umberto D." derxistiye?', 'Federico Fellini', 'Vittorio De Sica', 'Roberto Rossellini', 'Luchino Visconti', 'B', '"Umberto D." di sala 1952an de ji aliyê Vittorio De Sica ve hatiye derxistin. Ev fîlm yek ji fîlmên dawî yên neorealîzma îtalyan e û çîroka mêrekî kal û kûçikê wî vedibêje.', '"Umberto D." di sala 1952an de ji aliyê Vittorio De Sica ve hatiye derxistin. Ev fîlm yek ji fîlmên dawî yên neorealîzma îtalyan e û çîroka mêrekî kal û kûçikê wî vedibêje.', '"Umberto D." 1952''de Vittorio De Sica tarafından çekilmiştir. Bu film, İtalyan neorealizminin son filmlerinden biridir ve yaşlı bir adam ile köpeğinin hikayesini anlatır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Umberto_D.', NULL, 'https://en.wikipedia.org/wiki/Umberto_D.', 'approved', 'Kurmancî', 1, now()),
('2a7b88f3-ec0c-5fd8-8efb-b9638d3f3b0e', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlmê "Breathless" yê Jean-Luc Godard bi kîjan teknîkê tê nasîn?', 'Teknîka "long take"', 'Teknîka "slow motion"', 'Teknîka "jump cut"', 'Teknîka "stop motion"', 'C', '"Breathless" bi teknîka xwe ya "jump cut" tê nasîn. Ev teknîk tê de wêne bi awayekî nişkêve û bêyî domdariyê tên birîn, ku bûye yek ji nîşanên Pêla Nû ya Fransî.', '"Breathless" bi teknîka xwe ya "jump cut" tê nasîn. Ev teknîk tê de wêne bi awayekî nişkêve û bêyî domdariyê tên birîn, ku bûye yek ji nîşanên Pêla Nû ya Fransî.', '"Breathless", "jump cut" tekniğiyle tanınır. Bu teknikte görüntüler aniden ve süreklilik olmadan kesilir ve Fransız Yeni Dalgası''nın işaretlerinden biri haline gelmiştir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Breathless_(1960_film)', NULL, 'https://en.wikipedia.org/wiki/Breathless_(1960_film)', 'approved', 'Kurmancî', 1, now()),
('0f091054-e444-54f1-821b-8bd630ff91d0', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlmê "Bicycle Thieves" yê Vittorio De Sica çîroka kîjan kesan vedibêje?', 'Jinekê û keça wê', 'Xortekî û hevala wî', 'Mêrekî û jina wî', 'Bavekî û kurê wî', 'D', '"Bicycle Thieves" çîroka bavekî û kurê wî vedibêje ku li pey bisîkleteke diziyayî digerin. Ev fîlm yek ji fîlmên herî navdar ên neorealîzma îtalyan e.', '"Bicycle Thieves" çîroka bavekî û kurê wî vedibêje ku li pey bisîkleteke diziyayî digerin. Ev fîlm yek ji fîlmên herî navdar ên neorealîzma îtalyan e.', '"Bicycle Thieves", çalınan bir bisikletin peşine düşen bir baba ve oğlunun hikayesini anlatır. Bu film, İtalyan neorealizminin en ünlü filmlerinden biridir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Bicycle_Thieves', NULL, 'https://en.wikipedia.org/wiki/Bicycle_Thieves', 'approved', 'Kurmancî', 1, now()),
('31e2c946-fc00-5e95-8ddb-6053c8052602', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerê fransî fîlmê "Jules and Jim" derxistiye?', 'Jean-Luc Godard', 'François Truffaut', 'Alain Resnais', 'Claude Chabrol', 'B', '"Jules and Jim" di sala 1962an de ji aliyê François Truffaut ve hatiye derxistin. Ev fîlm yek ji fîlmên navdar ên Pêla Nû ya Fransî ye û çîroka sê hevalan vedibêje.', '"Jules and Jim" di sala 1962an de ji aliyê François Truffaut ve hatiye derxistin. Ev fîlm yek ji fîlmên navdar ên Pêla Nû ya Fransî ye û çîroka sê hevalan vedibêje.', '"Jules and Jim" 1962''de François Truffaut tarafından çekilmiştir. Bu film, Fransız Yeni Dalgası''nın ünlü filmlerinden biridir ve üç arkadaşın hikayesini anlatır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Jules_and_Jim', NULL, 'https://en.wikipedia.org/wiki/Jules_and_Jim', 'approved', 'Kurmancî', 1, now()),
('243a79b7-72d3-5b4e-b888-8a707ce51105', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerê amerîkî di sala 1972an de fîlmê "The Godfather" derxist?', 'Stanley Kubrick', 'Francis Ford Coppola', 'Martin Scorsese', 'Steven Spielberg', 'B', 'Francis Ford Coppola derhênerê fîlma "The Godfather" e. Fîlm di sala 1972an de derket û bû yek ji fîlmên herî navdar ên dîroka sînemayê.', 'Francis Ford Coppola derhênerê fîlma "The Godfather" e. Fîlm di sala 1972an de derket û bû yek ji fîlmên herî navdar ên dîroka sînemayê.', 'Francis Ford Coppola, "The Godfather" filminin yönetmenidir. Film 1972''de gösterime girdi ve sinema tarihinin en ünlü filmlerinden biri oldu.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Godfather', NULL, 'https://en.wikipedia.org/wiki/The_Godfather', 'approved', 'Kurmancî', 1, now()),
('36e0fa87-0d64-5d49-9f7f-caeb9db105b2', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlmê "Schindler''s List" yê Steven Spielberg di kîjan salê de derket?', '1990', '1995', '1993', '1998', 'C', 'Fîlmê "Schindler''s List" yê Steven Spielberg di sala 1993an de derket. Ev fîlm li ser Oskar Schindler e ku di dema Holokostê de gelek cihû rizgar kirin.', 'Fîlmê "Schindler''s List" yê Steven Spielberg di sala 1993an de derket. Ev fîlm li ser Oskar Schindler e ku di dema Holokostê de gelek cihû rizgar kirin.', 'Steven Spielberg''in "Schindler"s List'' filmi 1993''te gösterime girdi. Bu film, Holokost sırasında birçok Yahudi''yi kurtaran Oskar Schindler''i konu alır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Schindler%27s_List', NULL, 'https://en.wikipedia.org/wiki/Schindler%27s_List', 'approved', 'Kurmancî', 1, now()),
('71baca13-52bb-527a-a105-bb6a8454feb6', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlmê "Psycho" yê Alfred Hitchcock di kîjan salê de derket?', '1958', '1962', '1960', '1964', 'C', 'Fîlmê "Psycho" yê Alfred Hitchcock di sala 1960î de derket. Ev fîlm yek ji fîlmên herî navdar ên tirsê ye û bi dîmena serşokê tê nasîn.', 'Fîlmê "Psycho" yê Alfred Hitchcock di sala 1960î de derket. Ev fîlm yek ji fîlmên herî navdar ên tirsê ye û bi dîmena serşokê tê nasîn.', 'Alfred Hitchcock''un "Psycho" filmi 1960''ta gösterime girdi. Bu film, en ünlü korku filmlerinden biridir ve duş sahnesiyle tanınır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Psycho_(1960_film)', NULL, 'https://en.wikipedia.org/wiki/Psycho_(1960_film)', 'approved', 'Kurmancî', 1, now()),
('3efb72e7-b6db-5ab6-9558-e97830d653de', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlmê "The Birth of a Nation" yê D.W. Griffith di kîjan salê de derket?', '1913', '1917', '1919', '1915', 'D', 'Fîlmê "The Birth of a Nation" yê D.W. Griffith di sala 1915an de derket. Ev fîlm ji ber naveroka xwe ya nijadperest tê rexnekirin, lê ji aliyê teknîkî ve girîng e.', 'Fîlmê "The Birth of a Nation" yê D.W. Griffith di sala 1915an de derket. Ev fîlm ji ber naveroka xwe ya nijadperest tê rexnekirin, lê ji aliyê teknîkî ve girîng e.', 'D.W. Griffith''in "The Birth of a Nation" filmi 1915 yılında gösterime girdi. Bu film, ırkçı içeriği nedeniyle eleştirilir, ancak teknik açıdan önemlidir.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Birth_of_a_Nation', NULL, 'https://en.wikipedia.org/wiki/The_Birth_of_a_Nation', 'approved', 'Kurmancî', 1, now()),
('5ce78f04-f481-5c0b-acd8-c9221ade846e', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlmê "Spirited Away" yê Hayao Miyazaki di kîjan salê de derket?', '2001', '1997', '2004', '2008', 'A', 'Fîlmê "Spirited Away" yê Hayao Miyazaki di sala 2001ê de derket. Ev fîlm bi Xelata Oscarê ya fîlmê herî baş ê anîmasyonê hate xelatkirin û navdariya Miyazaki zêde kir.', 'Fîlmê "Spirited Away" yê Hayao Miyazaki di sala 2001ê de derket. Ev fîlm bi Xelata Oscarê ya fîlmê herî baş ê anîmasyonê hate xelatkirin û navdariya Miyazaki zêde kir.', 'Hayao Miyazaki''nin "Spirited Away" filmi 2001 yılında gösterime girdi. Bu film, En İyi Animasyon Filmi dalında Oscar kazandı ve Miyazaki''nin ününü artırdı.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Spirited_Away', NULL, 'https://en.wikipedia.org/wiki/Spirited_Away', 'approved', 'Kurmancî', 1, now()),
('61f798b5-38ca-54cb-bc5d-b79fc1d897f0', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan stûdyoya anîmasyonê fîlmê "Toy Story" yê yekem derxist?', 'DreamWorks', 'Blue Sky Studios', 'Pixar', 'Illumination', 'C', 'Fîlmê "Toy Story" yê yekem di sala 1995an de ji aliyê stûdyoya Pixar ve hate derxistin. Ev fîlm yekem fîlmê dirêj e ku bi tevahî bi kompîturê hatiye çêkirin.', 'Fîlmê "Toy Story" yê yekem di sala 1995an de ji aliyê stûdyoya Pixar ve hate derxistin. Ev fîlm yekem fîlmê dirêj e ku bi tevahî bi kompîturê hatiye çêkirin.', 'İlk "Toy Story" filmi 1995 yılında Pixar stüdyosu tarafından yayınlandı. Bu film, tamamen bilgisayarla yapılan ilk uzun metrajlı filmdir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Toy_Story', NULL, 'https://en.wikipedia.org/wiki/Toy_Story', 'approved', 'Kurmancî', 1, now()),
('05f0fdbb-4384-5dd8-be52-2e017f43b877', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di anîmasyona "The Lion King" de, kîjan karakter bavê Simba ye?', 'Mufasa', 'Scar', 'Timon', 'Zazu', 'A', 'Mufasa bavê Simba ye û qiralê şêran e di fîlmê "The Lion King" de. Scar birayê Mufasa ye ku dixwaze qiraliyê bi dest bixe.', 'Mufasa bavê Simba ye û qiralê şêran e di fîlmê "The Lion King" de. Scar birayê Mufasa ye ku dixwaze qiraliyê bi dest bixe.', 'Mufasa, Simba''nın babasıdır ve "The Lion King" filminde kralların kralıdır. Scar, Mufasa''nın krallığı ele geçirmek isteyen kardeşidir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Lion_King', NULL, 'https://en.wikipedia.org/wiki/The_Lion_King', 'approved', 'Kurmancî', 1, now()),
('7a6df1c9-db0b-500d-b625-e5cc7dd48695', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerî fîlmê belgefîlm ê "Waltz with Bashir" derxist?', 'Werner Herzog', 'Errol Morris', 'Ari Folman', 'Michael Moore', 'C', 'Derhênerê îsraêlî Ari Folman fîlmê belgefîlm ê "Waltz with Bashir" derxist. Ev fîlm bi teknîka anîmasyonê hatiye çêkirin û li ser serpêhatiyên Folman ên di şerê Libnanê de ye.', 'Derhênerê îsraêlî Ari Folman fîlmê belgefîlm ê "Waltz with Bashir" derxist. Ev fîlm bi teknîka anîmasyonê hatiye çêkirin û li ser serpêhatiyên Folman ên di şerê Libnanê de ye.', 'İsrailli yönetmen Ari Folman, "Waltz with Bashir" belgesel filmini yayınladı. Bu film animasyon tekniğiyle yapılmıştır ve Folman''ın Lübnan Savaşı''ndaki deneyimleri hakkındadır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Waltz_with_Bashir', NULL, 'https://en.wikipedia.org/wiki/Waltz_with_Bashir', 'approved', 'Kurmancî', 1, now()),
('29ed828d-1dc5-5130-bf09-4891e5d27b05', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di anîmasyona "The Incredibles" de, navê rastî yê kîjan karakterî Bob Parr e?', 'Dash', 'Mr. Incredible', 'Frozone', 'Syndrome', 'B', 'Bob Parr bi navê superqehreman "Mr. Incredible" tê nasîn. Dash kurê wî ye, Frozone hevalê wî ye û Syndrome dijminê wî ye.', 'Bob Parr bi navê superqehreman "Mr. Incredible" tê nasîn. Dash kurê wî ye, Frozone hevalê wî ye û Syndrome dijminê wî ye.', 'Bob Parr, "Mr. Incredible" süper kahramanı olarak bilinir. Dash onun oğludur, Frozone onun arkadaşıdır ve Syndrome onun düşmanıdır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Incredibles', NULL, 'https://en.wikipedia.org/wiki/The_Incredibles', 'approved', 'Kurmancî', 1, now()),
('9276a3ad-d582-5d78-be20-0e4cb3974111', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerê belgefîlman fîlmê "Grizzly Man" ê li ser jiyana Timothy Treadwell derxist?', 'Ken Burns', 'Errol Morris', 'Werner Herzog', 'Alex Gibney', 'C', 'Derhênerê alman Werner Herzog fîlmê "Grizzly Man" derxist. Ev belgefîlm li ser jiyana Timothy Treadwell e ku bi hirçên grizzly re dijî.', 'Derhênerê alman Werner Herzog fîlmê "Grizzly Man" derxist. Ev belgefîlm li ser jiyana Timothy Treadwell e ku bi hirçên grizzly re dijî.', 'Alman yönetmen Werner Herzog, "Grizzly Man" filmini yayınladı. Bu belgesel, boz ayılarla birlikte yaşayan Timothy Treadwell''in hayatı hakkındadır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Grizzly_Man', NULL, 'https://en.wikipedia.org/wiki/Grizzly_Man', 'approved', 'Kurmancî', 1, now()),
('9ca34b67-d55b-54e9-8bd3-666caaf0f245', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di anîmasyona "Frozen" de, kîjan karakter xwişka Elsa ye?', 'Anna', 'Kristoff', 'Olaf', 'Hans', 'A', 'Anna xwişka Elsa ye di fîlmê "Frozen" de. Kristoff hevalê Anna ye, Olaf mirovekî berfîn e û Hans prensek e.', 'Anna xwişka Elsa ye di fîlmê "Frozen" de. Kristoff hevalê Anna ye, Olaf mirovekî berfîn e û Hans prensek e.', 'Anna, "Frozen" filminde Elsa''nın kız kardeşidir. Kristoff, Anna''nın arkadaşıdır, Olaf bir kardan adamdır ve Hans bir prenstir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Frozen_(2013_film)', NULL, 'https://en.wikipedia.org/wiki/Frozen_(2013_film)', 'approved', 'Kurmancî', 1, now()),
('e644e404-7aa6-55bd-8654-f6bf35fb0ac2', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlmê belgefîlm ê "An Inconvenient Truth" yê ku li ser guherîna avhewayê ye, ji aliyê kîjan kesî ve hatiye pêşkêşkirin?', 'Barack Obama', 'Bill Clinton', 'Al Gore', 'John Kerry', 'C', 'Fîlmê "An Inconvenient Truth" ji aliyê Al Gore, cîgirê serokê berê yê Dewletên Yekbûyî, ve hatiye pêşkêşkirin. Ev belgefîlm li ser guherîna avhewayê û bandorên wê ye.', 'Fîlmê "An Inconvenient Truth" ji aliyê Al Gore, cîgirê serokê berê yê Dewletên Yekbûyî, ve hatiye pêşkêşkirin. Ev belgefîlm li ser guherîna avhewayê û bandorên wê ye.', '"An Inconvenient Truth" filmi, Amerika Birleşik Devletleri''nin eski başkan yardımcısı Al Gore tarafından sunuldu. Bu belgesel iklim değişikliği ve etkileri hakkındadır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/An_Inconvenient_Truth', NULL, 'https://en.wikipedia.org/wiki/An_Inconvenient_Truth', 'approved', 'Kurmancî', 1, now()),
('526c45e6-3416-5332-ae49-dc62384e1146', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di anîmasyona "Up" de, kîjan karakter zarokekî biçûk e ku bi Carl Fredricksen re diçe Amerîkaya Başûr?', 'Dug', 'Russell', 'Kevin', 'Charles Muntz', 'B', 'Russell zarokekî biçûk e ku bi Carl Fredricksen re diçe Amerîkaya Başûr di fîlmê "Up" de. Dug kûçik e, Kevin çûk e û Charles Muntz dijmin e.', 'Russell zarokekî biçûk e ku bi Carl Fredricksen re diçe Amerîkaya Başûr di fîlmê "Up" de. Dug kûçik e, Kevin çûk e û Charles Muntz dijmin e.', 'Russell, "Up" filminde Carl Fredricksen ile Güney Amerika''ya giden küçük çocuktur. Dug bir köpektir, Kevin bir kuştur ve Charles Muntz düşmandır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Up_(2009_film)', NULL, 'https://en.wikipedia.org/wiki/Up_(2009_film)', 'approved', 'Kurmancî', 1, now()),
('fc69c0fe-0a12-570c-bacb-ca8c21eaa68d', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di anîmasyona "Ratatouille" de, kîjan karakter mişkek e ku xwesteka wî ya xwarinçêkirinê heye?', 'Linguini', 'Colette', 'Remy', 'Anton Ego', 'C', 'Remy mişkek e ku xwesteka wî ya xwarinçêkirinê heye di fîlmê "Ratatouille" de. Linguini xortek e ku bi Remy re dixebite, Colette aşpêj e û Anton Ego rexnegirê xwarinê ye.', 'Remy mişkek e ku xwesteka wî ya xwarinçêkirinê heye di fîlmê "Ratatouille" de. Linguini xortek e ku bi Remy re dixebite, Colette aşpêj e û Anton Ego rexnegirê xwarinê ye.', 'Remy, "Ratatouille" filminde yemek yapma arzusu olan faredir. Linguini, Remy ile çalışan genç bir adamdır, Colette bir aşçıdır ve Anton Ego bir yemek eleştirmenidir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Ratatouille_(film)', NULL, 'https://en.wikipedia.org/wiki/Ratatouille_(film)', 'approved', 'Kurmancî', 1, now()),
('fea7ffcb-4dcb-542f-8a24-9bba3dd0b28b', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di anîmasyona "Moana" de, kîjan karakter xwedawenda giravê ye ku Maui dilê wê dizî?', 'Maui', 'Te Fiti', 'Gramma Tala', 'Tamatoa', 'B', 'Te Fiti xwedawenda giravê ye di fîlmê "Moana" de. Maui nîvxwedawendek e ku dixwaze dilê Te Fiti vegerîne, Gramma Tala dapîra Moana ye û Tamatoa kevjalekî dêw e.', 'Te Fiti xwedawenda giravê ye di fîlmê "Moana" de. Maui nîvxwedawendek e ku dixwaze dilê Te Fiti vegerîne, Gramma Tala dapîra Moana ye û Tamatoa kevjalekî dêw e.', 'Te Fiti, "Moana" filminde ada tanrıçasıdır. Maui, Te Fiti''nin kalbini geri getirmek isteyen yarı tanrıdır, Gramma Tala Moana''nın büyükannesidir ve Tamatoa dev bir yengeçtir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Moana_(2016_film)', NULL, 'https://en.wikipedia.org/wiki/Moana_(2016_film)', 'approved', 'Kurmancî', 1, now()),
('95ba436f-2297-5000-8b11-2eb40d214194', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Fîlmê belgefîlm ê "Senna" li ser jiyana kîjan ajokarê pêşbirkê ye?', 'Ayrton Senna', 'Michael Schumacher', 'Alain Prost', 'Niki Lauda', 'A', 'Fîlmê "Senna" li ser jiyana Ayrton Senna, ajokarê pêşbirkê yê brazîlî ye. Ev belgefîlm jiyana wî ji destpêka kariyera wî heta mirina wî di pêşbirka San Marînoyê de vedibêje.', 'Fîlmê "Senna" li ser jiyana Ayrton Senna, ajokarê pêşbirkê yê brazîlî ye. Ev belgefîlm jiyana wî ji destpêka kariyera wî heta mirina wî di pêşbirka San Marînoyê de vedibêje.', '"Senna" filmi, Brezilyalı yarış pilotu Ayrton Senna''nın hayatı hakkındadır. Bu belgesel, kariyerinin başlangıcından San Marino yarışındaki ölümüne kadar hayatını anlatır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Senna_(film)', NULL, 'https://en.wikipedia.org/wiki/Senna_(film)', 'approved', 'Kurmancî', 1, now()),
('8aafee93-c69c-516c-9764-be55f9c2aa60', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di anîmasyona "Zootopia" de, kîjan karakter roviyek e ku bi polîs Judy Hopps re dixebite?', 'Chief Bogo', 'Nick Wilde', 'Flash', 'Clawhauser', 'B', 'Nick Wilde roviyek e ku bi Judy Hopps re dixebite di fîlmê "Zootopia" de. Chief Bogo serokê polîsan e, Flash ajalekî tembel e û Clawhauser polîsekî qelew e.', 'Nick Wilde roviyek e ku bi Judy Hopps re dixebite di fîlmê "Zootopia" de. Chief Bogo serokê polîsan e, Flash ajalekî tembel e û Clawhauser polîsekî qelew e.', 'Nick Wilde, "Zootopia" filminde Judy Hopps ile birlikte çalışan tilkidir. Chief Bogo polis şefidir, Flash bir tembelhayvandır ve Clawhauser şişman bir polis memurudur.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Zootopia', NULL, 'https://en.wikipedia.org/wiki/Zootopia', 'approved', 'Kurmancî', 1, now()),
('80e6eb24-33eb-5219-8112-20980ff4b472', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Kîjan derhênerê belgefîlman ê fransî fîlmê "Shoah" ê li ser Holokostê derxist?', 'Marcel Ophüls', 'Leni Riefenstahl', 'Alain Resnais', 'Claude Lanzmann', 'D', 'Derhênerê fransî Claude Lanzmann fîlmê "Shoah" derxist. Ev belgefîlm bi dirêjahiya xwe ya 9 saetan ve li ser Holokostê ye û bi hevpeyvînên bi şahidan û kesên din re hatiye çêkirin.', 'Derhênerê fransî Claude Lanzmann fîlmê "Shoah" derxist. Ev belgefîlm bi dirêjahiya xwe ya 9 saetan ve li ser Holokostê ye û bi hevpeyvînên bi şahidan û kesên din re hatiye çêkirin.', 'Fransız yönetmen Claude Lanzmann, "Shoah" filmini yayınladı. Bu belgesel, 9 saatlik uzunluğuyla Holokost hakkındadır ve tanıklar ve diğer kişilerle yapılan röportajlarla oluşturulmuştur.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Shoah_(film)', NULL, 'https://en.wikipedia.org/wiki/Shoah_(film)', 'approved', 'Kurmancî', 1, now()),
('a3e28ed8-c92d-50ea-9db6-596ea18c9f66', (select id from categories where slug = 'cihan'), 'ku-kmr', 'Di anîmasyona "Coco" de, kîjan karakter ew lawik e ku dixwaze bibe muzîkjen?', 'Héctor', 'Miguel', 'Ernesto de la Cruz', 'Dante', 'B', 'Miguel ew lawik e ku dixwaze bibe muzîkjen di fîlmê "Coco" de. Héctor kesek e ku di Axa Miriyan de ye, Ernesto de la Cruz muzîkjenê navdar e û Dante kûçikê Miguel e.', 'Miguel ew lawik e ku dixwaze bibe muzîkjen di fîlmê "Coco" de. Héctor kesek e ku di Axa Miriyan de ye, Ernesto de la Cruz muzîkjenê navdar e û Dante kûçikê Miguel e.', 'Miguel, "Coco" filminde müzisyen olmak isteyen çocuktur. Héctor, Ölüler Diyarı''nda olan biridir, Ernesto de la Cruz ünlü bir müzisyendir ve Dante, Miguel''in köpeğidir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Coco_(2017_film)', NULL, 'https://en.wikipedia.org/wiki/Coco_(2017_film)', 'approved', 'Kurmancî', 1, now())
